                    </Svg>
                    <Text className="text-slate-700 font-semibold ml-3 flex-1">
                      Configuración
                    </Text>
                    <Svg
                      height="20"
                      viewBox="0 -960 960 960"
                      width="20"
                      fill="#94a3b8"
                    >
                      <Path d="M504-480 320-664l56-56 240 240-240 240-56-56 184-184Z" />
                    </Svg>
                  </TouchableOpacity>
                )}

                {onLogout && (
                  <TouchableOpacity
                    onPress={() => {
                      setProfileMenuVisible(false);
                      onLogout();
