export default function RegistroAsesor({
  asesorToEdit,
  onFormClose,
  viewOnly = false,
}) {
  const { width, height } = useWindowDimensions();
  const isSmall = width < 640;
  const isLandscape = width > height && Platform.OS !== "web";
  const isTablet = width >= 640 && width < 1024;
  // Anclar el contenido arriba; en tablets solo damos un poco mÃƒÂ¡s de padding top
  const contentStyle = {
    padding: 16,
    paddingBottom: 0, // Asegura que el contenido llene el espacio vertical
    ...(isTablet ? { paddingTop: 24 } : {}),
  };
  // Medir el alto del bloque de tÃƒÂ­tulo y centrar SOLO el formulario en tablets
  const [titleHeight, setTitleHeight] = useState(0);

  const initialFormState = {
    nombre_asesor: "",
    desc_asesor: "",
    correo_asesor: "",
    telefono_asesor: "",
    direccion_asesor: "",
    municipio_asesor: "",
    rfc_asesor: "",
    nacionalidad_asesor: "Mexicana",
    genero_asesor: "",
  };

  const [form, setForm] = useState(initialFormState);
  const originalFormRef = useRef(null);
  const [editableFields, setEditableFields] = useState({});
  const [showDomainSuggestions, setShowDomainSuggestions] = useState(false);
  const [domainSuggestions, setDomainSuggestions] = useState([]);
  const emailInputContainerRef = useRef(null);
  const [isOtroMunicipio, setIsOtroMunicipio] = useState(false);
  const [emailInputLayout, setEmailInputLayout] = useState(null);

  const [isPreviewVisible, setIsPreviewVisible] = useState(false);
  useEffect(() => {
    // Si recibimos un asesor para editar, llenamos el formulario
    if (asesorToEdit) {
      // Sanitizar null/undefined a string vacÃƒÂ­o para que los inputs no reciban null
      const sanitized = {};
      for (const [key, val] of Object.entries(asesorToEdit)) {
        sanitized[key] = val ?? "";
      }
      setForm({ ...initialFormState, ...sanitized });
      originalFormRef.current = { ...initialFormState, ...sanitized };

      const checkAvatar = async () => {
        try {
          const fileName = `${asesorToEdit.id_asesor}.png`;
          const { data: files, error } = await supabase.storage
            .from("AvatarAsesor")
            .list("public");

          if (!error && files) {
            const hasAvatar = files.some((f) => f.name === fileName);
            if (hasAvatar) {
              const { data } = supabase.storage
                .from("AvatarAsesor")
                .getPublicUrl(`public/${fileName}`);
              if (data) {
                setForm((f) => ({ ...f, avatar_url: `${data.publicUrl}?t=${Date.now()}` }));
              }
            } else {
              setForm((f) => ({ ...f, avatar_url: "" }));
            }
          } else {
            setForm((f) => ({ ...f, avatar_url: "" }));
          }
        } catch (err) {
          console.error("Error checking avatar:", err);
          setForm((f) => ({ ...f, avatar_url: "" }));
        }
      };

      checkAvatar();

      // Inicializar todos los campos como no editables en modo ediciÃƒÂ³n
      const isCustomMunicipio =
        asesorToEdit.municipio_asesor &&
        !MUNICIPIOS.some((m) => m.value === asesorToEdit.municipio_asesor);
      if (isCustomMunicipio) {
        setIsOtroMunicipio(true);
      }

      const initialEditableState = Object.keys(initialFormState).reduce(
        (acc, key) => {
          acc[key] = true;
          return acc;
        },
        {},
      );
      setEditableFields(initialEditableState);
    }
    // Si no hay asesorToEdit, el formulario estÃƒÂ¡ vacÃƒÂ­o y todos los campos son editables por defecto (o no controlados por editableFields)
  }, [asesorToEdit]);

  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState({ type: "", msg: "" });
  const [fieldErrors, setFieldErrors] = useState({});
  const [genderOpen, setGenderOpen] = useState(false);
  const genderAnchorRef = useRef(null);
  const [genderMenuPos, setGenderMenuPos] = useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
  });
  const [municipioOpen, setMunicipioOpen] = useState(false);
  const municipioAnchorRef = useRef(null);
  const [municipioMenuPos, setMunicipioMenuPos] = useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
  });

  const set = (key) => (value) => setForm((f) => ({ ...f, [key]: value }));

  // Helper para renderizar el label con el botÃƒÂ³n de editar
  const pickImage = async () => {
    if (viewOnly) return;

    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== "granted") {
      notifyError("Necesitamos acceso a tu galería para seleccionar una foto.");
      return;
    }

    let result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: [`images`],
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.5,
      base64: true,
    });

    if (!result.canceled) {
      const { uri, base64 } = result.assets[0];
      setForm((prevForm) => ({
        ...prevForm,
        avatar_url: uri,
        avatar_base64: base64,
      }));
    }
  };

  const handleDeleteImage = async () => {
    const ok = await confirm({
      title: "Eliminar foto de perfil",
      message: "¿Estás seguro de que quieres eliminar la foto? Esta acción no se puede deshacer.",
      confirmText: "Eliminar",
      type: "destructive",
