  // Helpers de validaciÃƒÂ³n
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const phoneDigits = (v) => v.replace(/\D+/g, "");
  const onlyLettersSpaces = (v) =>
    /^(?=.{2,100}$)[A-Za-zÃƒÂÃƒâ€°ÃƒÂÃƒâ€œÃƒÅ¡ÃƒÅ“Ãƒâ€˜ÃƒÂ¡ÃƒÂ©ÃƒÂ­ÃƒÂ³ÃƒÂºÃƒÂ¼ÃƒÂ±'\-\.\s]+$/.test(v.trim());
  // RFC personas y morales MX
  const rfcRe =
    /^([A-Z&Ãƒâ€˜]{3,4})(\d{2})(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])[A-Z\d]{3}$/;

  const validateRFC = (rfc) => {
    // RFC es opcional Ã¢â‚¬â€ solo validamos el formato si se ingresa algo
    if (!rfc) return "";
    const upper = rfc.toUpperCase();
