import React, { useCallback, useRef, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Animated,
  Platform,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
  useWindowDimensions,
} from "react-native";
import { useFocusEffect } from "@react-navigation/native";
import Svg, { Path } from "react-native-svg";
import { supabase } from "../../lib/supabase";
import RegistroAsesor from "./RegistroAsesor";
import TablaAsesores from "./TablaAsesores";
import { useConfirm } from "../../hooks/use-confirm";

const ScreenAsesores = () => {
  const confirm = useConfirm();
  const [asesores, setAsesores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isRefetching, setIsRefetching] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [editingAsesor, setEditingAsesor] = useState(null);
  const [viewOnly, setViewOnly] = useState(false);
  const formAnimation = useRef(new Animated.Value(0)).current;
  const { height } = useWindowDimensions();

  const fetchAsesores = useCallback(async () => {
    const showRefetch = asesores.length > 0;
    if (showRefetch) {
      setIsRefetching(true);
    } else {
      setLoading(true);
    }

    const { data, error } = await supabase
      .from("asesores")
      .select("*")
      .order("id_asesor", { ascending: false });

    if (!error && data) {
      setAsesores(data);
    }

    setLoading(false);
    setIsRefetching(false);
  }, [asesores.length]);

  const handleRefresh = useCallback(async () => {
    if (isRefetching || loading) return;
    await fetchAsesores();
  }, [fetchAsesores, isRefetching, loading]);

  useFocusEffect(
    useCallback(() => {
      fetchAsesores();
    }, [fetchAsesores]),
  );

  const handleDelete = async (idAsesor) => {
    const confirmed = await confirm({
      title: "Confirmar eliminación",
      message: "¿Estás seguro de que quieres eliminar este asesor?",
      confirmText: "Eliminar",
      cancelText: "Cancelar",
      type: "destructive",
    });

    if (!confirmed) return;

    const { error } = await supabase
      .from("asesores")
      .delete()
      .eq("id_asesor", idAsesor);

    if (error) {
      await confirm({
        title: "Error",
        message: "No se pudo eliminar el asesor.",
        confirmText: "Aceptar",
        showCancel: false,
      });
      return;
    }

    handleRefresh();
  };

  const openForm = (asesor = null, readOnly = false) => {
    setEditingAsesor(asesor);
    setViewOnly(readOnly);
    setIsFormVisible(true);
    Animated.timing(formAnimation, {
      toValue: 1,
      duration: 300,
      useNativeDriver: false,
    }).start();
  };

  const handleCloseForm = async (formHasUnsavedChanges = false) => {
    const closeAction = () => {
      Animated.timing(formAnimation, {
        toValue: 0,
        duration: 300,
        useNativeDriver: false,
      }).start(() => {
        setIsFormVisible(false);
        setEditingAsesor(null);
        setViewOnly(false);
        handleRefresh();
      });
    };

    if (!formHasUnsavedChanges) {
      closeAction();
      return;
    }

    const confirmed = await confirm({
      title: "Cambios sin guardar",
      message: "¿Tienes cambios sin guardar? ¿Deseas descartarlos?",
      confirmText: "Descartar",
      cancelText: "Cancelar",
      type: "destructive",
    });

    if (confirmed) {
      closeAction();
    }
  };

  const formContainerStyle = {
    transform: [
      {
        translateY: formAnimation.interpolate({
          inputRange: [0, 1],
          outputRange: [height, 0],
        }),
      },
    ],
  };

  return (
    <View className="flex-1 bg-slate-50 relative">
      <View className="flex-row items-center justify-between p-4">
        <View className="flex-row items-center bg-white border border-slate-300 rounded-full px-3 py-1 shadow-sm">
          <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#9ca3af">
            <Path d="M784-120 532-372q-30 24-69 38t-83 14q-109 0-184.5-75.5T120-580q0-109 75.5-184.5T380-840q109 0 184.5 75.5T640-580q0 44-14 83t-38 69l252 252-56 56ZM380-400q75 0 127.5-52.5T560-580q0-75-52.5-127.5T380-760q-75 0-127.5 52.5T200-580q0 75 52.5 127.5T380-400Z" />
          </Svg>
          <TextInput
            placeholder="Buscar asesor..."
            value={searchTerm}
            onChangeText={setSearchTerm}
            className="ml-2 text-base"
          />
        </View>

        <TouchableOpacity
          onPress={() => openForm()}
          className="bg-indigo-600 p-2 rounded-full shadow-md shadow-indigo-600/30 flex-row items-center px-4"
        >
          <Svg height="18" viewBox="0 -960 960 960" width="18" fill="#ffffff">
            <Path d="M440-440H200v-80h240v-240h80v240h240v80H520v240h-80v-240Z" />
          </Svg>
          <Text className="text-white font-bold ml-2">Agregar Asesor</Text>
        </TouchableOpacity>
      </View>

      <TablaAsesores
        data={asesores}
        loading={loading}
        query={searchTerm}
        isRefetching={isRefetching}
        onRefresh={handleRefresh}
        onEdit={(asesor) => openForm(asesor, false)}
        onDelete={handleDelete}
      />

      {isFormVisible && (
        <Animated.View
          style={[StyleSheet.absoluteFill, formContainerStyle]}
          className="absolute inset-0 z-10 bg-slate-50"
        >
          <RegistroAsesor
            key={editingAsesor ? `edit-${editingAsesor.id_asesor}` : "new"}
            asesorToEdit={editingAsesor}
            onFormClose={handleCloseForm}
            viewOnly={viewOnly}
          />
        </Animated.View>
      )}

      {loading && asesores.length === 0 && (
        <View className="absolute inset-0 items-center justify-center bg-slate-50/80">
          <ActivityIndicator size="large" color="#6F09EA" />
        </View>
      )}
    </View>
  );
};

export default ScreenAsesores;

import React, { useMemo, useState } from "react";
import {
  ActivityIndicator,
  Platform,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from "react-native";
import Svg, { Path } from "react-native-svg";

const TablaAsesores = ({
  data,
  loading = false,
  query,
  isRefetching,
  onRefresh,
  onEdit,
  onDelete,
}) => {
  const [sortKey, setSortKey] = useState("nombre_asesor");
  const [sortDir, setSortDir] = useState("asc");

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const filteredRows = data.filter((item) => {
      if (!q) return true;
      const phone = String(item.telefono_asesor || "").replace(/\D/g, "");
      const phoneQuery = q.replace(/\D/g, "");
      return (
        String(item.nombre_asesor || "").toLowerCase().includes(q) ||
        String(item.correo_asesor || "").toLowerCase().includes(q) ||
        String(item.especialidad_asesor || "").toLowerCase().includes(q) ||
        String(item.direccion_asesor || "").toLowerCase().includes(q) ||
        String(item.notas || "").toLowerCase().includes(q) ||
        (phoneQuery && phone.includes(phoneQuery))
      );
    });

    return [...filteredRows].sort((a, b) => {
      let left = a[sortKey] ?? "";
      let right = b[sortKey] ?? "";
      if (typeof left === "string") left = left.toLowerCase();
      if (typeof right === "string") right = right.toLowerCase();
      if (left < right) return sortDir === "asc" ? -1 : 1;
      if (left > right) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
  }, [data, query, sortDir, sortKey]);

  const SortHeader = ({ label, field, flex = 1, center = false }) => (
    <TouchableOpacity
      activeOpacity={0.6}
      onPress={() => {
        if (!field) return;
        setSortKey(field);
        setSortDir((c) => (sortKey === field ? (c === "asc" ? "desc" : "asc") : "asc"));
      }}
      style={{ flex, paddingVertical: 12, paddingHorizontal: 12, alignItems: center ? "center" : "flex-start" }}
    >
      <View style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
        <Text style={{ color: "#1e293b", fontWeight: "600", fontSize: 13, textTransform: "uppercase", letterSpacing: 0.5 }}>
          {label}
        </Text>
        {sortKey === field && (
          <Svg width={12} height={12} viewBox="0 -960 960 960" fill="#334155">
            {sortDir === "asc" ? <Path d="M480-680 240-440h480L480-680Z" /> : <Path d="M240-520h480L480-280 240-520Z" />}
          </Svg>
        )}
      </View>
    </TouchableOpacity>
  );

  return (
    <View style={{ paddingHorizontal: 8, paddingBottom: 16, flex: 1 }}>
      <View
        style={{
          borderRadius: 12,
          overflow: "hidden",
          borderWidth: 1,
          borderColor: "#e2e8f0",
          backgroundColor: "white",
          flex: Platform.OS === "web" ? 1 : undefined,
          opacity: loading || isRefetching ? 0.5 : 1,
        }}
      >
        <ScrollView
          stickyHeaderIndices={[0]}
          refreshControl={<RefreshControl refreshing={isRefetching} onRefresh={onRefresh} tintColor="#6F09EA" />}
        >
          {/* Header */}
          <View style={{ flexDirection: "row", backgroundColor: "#f1f5f9", borderBottomWidth: 1, borderBottomColor: "#e2e8f0" }}>
            <SortHeader label="Nombre" field="nombre_asesor" flex={3} />
            <SortHeader label="Correo" field="correo_asesor" flex={5} />
            <SortHeader label="Telefono" field="telefono_asesor" flex={2} />
