      if (numericValue.length === 2) monthInputRef.current?.focus();
    }
    if (part === "month") {
      if (parseInt(numericValue, 10) > 12) newParts.month = "12";
      if (numericValue.length === 2) yearInputRef.current?.focus();
    }
