      );
    } else {
      setIsAddingEvent(false);
      setEditingEventId(null);
      setNewEvent({ nombre: "", descripcion: "", hora: "09", minutos: "00" });
      handleRefresh();

      notifySuccess(
        `Evento ${editingEventId ? "actualizado" : "creado"} correctamente`,
