        detalles_evento: `Monto: $${egreso.monto_egreso} - ${egreso.desc_egreso}`,
        fechayhora_evento: `${egreso.fecha_egreso}T09:00:00`, // Asumimos 9 AM por defecto para visualización
        tipo: "egreso", // Identificador para lógica de UI
        originalData: egreso, // Guardamos datos originales por si acaso
      }));

      // 4. Combinar y ordenar ambos tipos
      const todos = [...(eventos || []), ...egresosComoEventos].sort((a, b) => {
        const dateA = new Date(a.fechayhora_evento);
        const dateB = new Date(b.fechayhora_evento);
        return dateB - dateA;
      });

      setAllEvents(todos);
    } catch (err) {
      console.error("Unexpected error in fetchEvento:", err);
    } finally {
      setRefreshing(false);
      setLoading(false);
      setIsRefetching(false);
    }
  }

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    handleRefresh();
  }, []);

  const handleDeleteEvent = async (id) => {
    const ok = await confirm({
      title: "Eliminar Evento",
      message: "¿Estás seguro de que quieres eliminar este evento?",
      confirmText: "Eliminar",
      type: "destructive",
    });
    if (!ok) return;

    const { error } = await supabase
      .from("eventos_calendario")
      .delete()
      .eq("id_evento", id);

    if (error) {
      notifyError("No se pudo eliminar el evento");
      console.error(error);
    } else {
      handleRefresh();
    }
  };

  useFocusEffect(
    useCallback(() => {
      const loadEvents = async () => {
        if (allEvents.length > 0) {
          setIsRefetching(true);
        } else {
          setLoading(true);
        }
        await fetchEvento();
      };
      loadEvents();
    }, []),
  );

  return (
    <TouchableWithoutFeedback
      onPress={Platform.OS !== "web" ? Keyboard.dismiss : ""}
    >
      <View
        className={`flex-1 lg:flex-row gap-6 p-4 lg:items-stretch`} // Usamos clases lg: para responsividad en web/tablets
      >
        {/* Contenedor del Calendario */}
        <View
          id="contendor-calendario"
          className={`flex items-center ${isLandscape ? "" : "w-full"}`}
        >
          <View
            className={`bg-white rounded-xl shadow-sm border ${isLandscape ? "h-full" : ""} border-slate-200 p-4`}
            style={{
              width: CALENDAR_WIDTH,
            }}
          >
            <Calendar
              // Props para el calendario
              ref={calendarRef}
              current={selectedDate} // Controlamos el mes visible con 'current'
              onDayPress={(day) => setSelectedDate(day.dateString)}
              markedDates={markedDates}
              enableSwipeMonths={true}
              showSixWeeks
              style={{
                // El estilo ahora es más limpio, controlado por el contenedor
                backgroundColor: "transparent",
              }}
              theme={{
                // Tema visual del calendario
                calendarBackground: "transparent",
                textSectionTitleColor: "#64748b",
                selectedDayBackgroundColor: "#6F09EA",
                selectedDayTextColor: "#ffffff",
                todayTextColor: "#6F09EA",
                dayTextColor: "#1e293b",
                textDisabledColor: "#9ca3af",
                arrowColor: "#6F09EA",
                monthTextColor: "#1e293b",
                textDayFontWeight: "500",
                textMonthFontWeight: "bold",
                textDayHeaderFontWeight: "600",
                textDayFontSize: 16,
                textMonthFontSize: 18,
                textDayHeaderFontSize: 14,
              }}
              renderHeader={(date) => {
                const month = date.toString("MMMM yyyy");
                return (
                  <View className="flex-row justify-center relative px-10">
                    {/* El título del mes se centra automáticamente */}
                    <Text className="text-lg font-bold text-slate-800 capitalize">
                      {month}
                    </Text>
                    {/* Botón "Hoy" con posicionamiento absoluto */}
                    <TouchableOpacity
                      onPress={goToToday}
                      className="bg-indigo-100 px-3 py-1 rounded-full absolute"
                      style={{ top: 0, right: -30 }}
                    >
                      <Text className="font-bold text-sm text-indigo-600">
                        Hoy
                      </Text>
                    </TouchableOpacity>
                  </View>
                );
              }}
            />
          </View>
        </View>

        {/* Contenedor de Eventos */}
        <View style={{ flex: 1 }}>
          <View className="bg-white rounded-xl w-full h-full shadow-sm border border-slate-200 p-4">
            {/* Cabecera de la sección de eventos */}
            <View
              className={`flex-row justify-between items-center border-b border-slate-200 pb-3 mb-4`}
            >
              <Text className="text-lg font-bold text-slate-800">
                Próximos eventos
              </Text>
              <TouchableOpacity
                onPress={isAddingEvent ? handleCancelEvent : openAddEventForm}
                className={`bg-indigo-600 p-2 rounded-full shadow-md shadow-indigo-600/30 flex-row items-center ${isAddingEvent ? "px-2" : "px-3"}`}
              >
                {isAddingEvent ? (
                  <Svg
                    height="18"
                    viewBox="0 -960 960 960"
                    width="18"
                    fill="#ffffff"
                  >
                    <Path d="m256-200-56-56 224-224-224-224 56-56 224 224 224-224 56 56-224 224 224 224-56 56-224-224-224 224Z" />
                  </Svg>
                ) : (
                  <>
                    <Svg
                      height="16"
                      viewBox="0 -960 960 960"
                      width="16"
                      fill="#ffffff"
                    >
                      <Path d="M440-440H200v-80h240v-240h80v240h240v80H520v240h-80v-240Z" />
                    </Svg>
                    <Text className="text-white font-bold ml-2 text-sm">
                      Agregar
                    </Text>
                  </>
                )}
              </TouchableOpacity>
            </View>

            {/* Filtros de búsqueda y tipo */}
            {!isAddingEvent && (
              <View className="mb-4">
                <View className="flex-row items-center bg-slate-50 border border-slate-200 rounded-full px-3 py-1.5 shadow-sm mb-3">
                  <Svg height="16" viewBox="0 -960 960 960" width="16" fill="#9ca3af">
                    <Path d="M784-120 532-372q-30 24-69 38t-83 14q-109 0-184.5-75.5T120-580q0-109 75.5-184.5T380-840q109 0 184.5 75.5T640-580q0 44-14 83t-38 69l252 252-56 56ZM380-400q75 0 127.5-52.5T560-580q0-75-52.5-127.5T380-760q-75 0-127.5 52.5T200-580q0 75 52.5 127.5T380-400Z" />
                  </Svg>
                  <TextInput
                    placeholder="Buscar actividad..."
                    value={eventSearchQuery}
                    onChangeText={setEventSearchQuery}
                    className="ml-2 text-sm flex-1 p-0 py-0.5"
                  />
                  {eventSearchQuery !== "" && (
                    <TouchableOpacity onPress={() => setEventSearchQuery("")}>
                      <Svg height="16" viewBox="0 -960 960 960" width="16" fill="#9ca3af">
                        <Path d="m256-200-56-56 224-224-224-224 56-56 224 224 224-224 56 56-224 224 224 224-56 56-224-224-224 224Z" />
                      </Svg>
                    </TouchableOpacity>
                  )}
                </View>

                <View className="flex-row items-center justify-between">
                  {/* Botones de filtro de tipo */}
                  <View className="flex-row gap-x-2">
                    {["all", "event", "egreso"].map((type) => {
                      const label = type === "all" ? "Todos" : type === "event" ? "Eventos" : "Pagos";
                      const isSelected = eventTypeFilter === type;
                      return (
                        <TouchableOpacity
                          key={type}
                          onPress={() => setEventTypeFilter(type)}
                          style={{
                            backgroundColor: isSelected ? "#6F09EA" : "#f1f5f9",
                            borderRadius: 20,
                            paddingHorizontal: 12,
                            paddingVertical: 6,
                          }}
                        >
                          <Text
                            style={{
                              color: isSelected ? "#ffffff" : "#475569",
                              fontSize: 12,
                              fontWeight: "bold",
                            }}
                          >
                            {label}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>

                  {/* Toggle para mostrar/ocultar eventos pasados */}
                  <View className="flex-row items-center">
                    <Text className="text-xs text-slate-500 mr-2">
                      Pasados
                    </Text>
                    <Switch
                      trackColor={{ false: "#e2e8f0", true: "#c7d2fe" }}
                      thumbColor={showPastEvents ? "#6366f1" : "#f1f5f9"}
                      ios_backgroundColor="#e2e8f0"
                      onValueChange={setShowPastEvents}
                      value={showPastEvents}
                      style={{ transform: [{ scaleX: 0.8 }, { scaleY: 0.8 }] }}
                    />
                  </View>
                </View>
              </View>
            )}

            {isAddingEvent ? (
              // --- FORMULARIO PARA AGREGAR EVENTO ---
              <ScrollView className="p-2">
                <Text className="text-xl font-bold mb-4 text-slate-800">
                  {editingEventId ? "Editar Evento" : "Agregar Evento"}
                </Text>

                {/* Campo Nombre del Evento */}
                <View className="mb-4">
                  <View className="flex-row items-center mb-1">
                    <Text className="text-sm font-semibold text-slate-700">
                      Nombre del Evento
                    </Text>
                    <Text className="text-red-500 ml-1">*</Text>
                  </View>
                  <TextInput
                    className="border border-slate-300 rounded-xl px-4 py-3 text-slate-900 bg-white"
                    placeholder="Ej. Reunión de equipo"
                    value={newEvent.nombre}
                    onChangeText={(text) =>
                      setNewEvent((prev) => ({ ...prev, nombre: text }))
                    }
                  />
                </View>

                {/* Campo de Fecha */}
                <View className="mb-4">
                  <View className="flex-row items-center mb-1">
                    <Text className="text-sm font-semibold text-slate-700">
                      Fecha del Evento
                    </Text>
                    <TouchableOpacity
                      onPress={() => setIsDateEditable(!isDateEditable)}
                      className="ml-2 p-1 rounded-full bg-slate-200"
                    >
                      <Svg
                        height="14"
                        viewBox="0 -960 960 960"
                        width="14"
                        fill="#475569"
                      >
                        <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                      </Svg>
                    </TouchableOpacity>
                  </View>
                  <View
                    className={`flex-row items-center border border-slate-300 rounded-xl p-1 ${isDateEditable ? "bg-white" : "bg-slate-100 opacity-70"}`}
                  >
                    <TextInput
                      style={styles_registro_venta.dateInput}
                      placeholder="DD"
                      value={dateParts.day}
                      editable={isDateEditable}
                      onChangeText={(text) => handleDatePartChange("day", text)}
                      keyboardType="number-pad"
                      maxLength={2}
                    />
                    <Text style={styles.dateSeparator}>/</Text>
                    <TextInput
                      ref={monthInputRef}
                      style={styles_registro_venta.dateInput}
                      placeholder="MM"
                      value={dateParts.month}
                      editable={isDateEditable}
                      onChangeText={(text) =>
                        handleDatePartChange("month", text)
                      }
                      keyboardType="number-pad"
                      maxLength={2}
                    />
                    <Text style={styles.dateSeparator}>/</Text>
                    <TextInput
                      ref={yearInputRef}
                      style={[styles_registro_venta.dateInput, { flex: 1.5 }]}
                      placeholder="AAAA"
                      value={dateParts.year}
                      editable={isDateEditable}
                      onChangeText={(text) =>
                        handleDatePartChange("year", text)
                      }
                      keyboardType="number-pad"
                      maxLength={4}
                    />
                  </View>
                </View>

                {/* Selector de Hora */}
                <View className="mb-4">
                  <View className="flex-row items-center mb-1">
                    <Text className="text-sm font-semibold text-slate-700">
                      Hora del Evento (Formato 24HH)
                    </Text>
                    <TouchableOpacity
                      onPress={() => setIsTimeEditable(!isTimeEditable)}
                      className="ml-2 p-1 rounded-full bg-slate-200"
                    >
                      <Svg
                        height="14"
                        viewBox="0 -960 960 960"
                        width="14"
                        fill="#475569"
                      >
                        <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                      </Svg>
                    </TouchableOpacity>
                  </View>
                  <View
                    className={`flex-row items-center border border-slate-300 rounded-xl p-1 ${isTimeEditable ? "bg-white" : "bg-slate-100 opacity-70"}`}
                  >
                    <TextInput
                      className="flex-1 text-center text-base py-2"
                      placeholder="HH"
                      value={newEvent.hora}
                      editable={isTimeEditable}
                      onChangeText={(text) => {
                        // Solo permitir números
                        const numericValue = text.replace(/[^0-9]/g, "");
                        // Validar que esté entre 00 y 23
                        if (numericValue === "" || numericValue.length === 1) {
                          setNewEvent((prev) => ({
                            ...prev,
                            hora: numericValue,
                          }));
                        } else if (numericValue.length === 2) {
                          const hourValue = parseInt(numericValue, 10);
                          if (hourValue >= 0 && hourValue <= 23) {
                            setNewEvent((prev) => ({
                              ...prev,
                              hora: numericValue,
                            }));
                          }
                        }
                      }}
                      onBlur={() => {
                        // Agregar cero a la izquierda si es necesario
                        if (newEvent.hora.length === 1) {
                          setNewEvent((prev) => ({
                            ...prev,
                            hora: prev.hora.padStart(2, "0"),
                          }));
                        }
                      }}
                      keyboardType="number-pad"
                      maxLength={2}
                    />
                    <Text className="text-xl font-bold text-slate-400">:</Text>
                    <TextInput
                      className="flex-1 text-center text-base py-2"
                      placeholder="MM"
                      value={newEvent.minutos}
                      editable={isTimeEditable}
                      onChangeText={(text) => {
                        // Solo permitir números
                        const numericValue = text.replace(/[^0-9]/g, "");
                        // Validar que esté entre 00 y 59
                        if (numericValue === "" || numericValue.length === 1) {
                          setNewEvent((prev) => ({
                            ...prev,
                            minutos: numericValue,
                          }));
                        } else if (numericValue.length === 2) {
                          const minuteValue = parseInt(numericValue, 10);
                          if (minuteValue >= 0 && minuteValue <= 59) {
                            setNewEvent((prev) => ({
                              ...prev,
                              minutos: numericValue,
                            }));
                          }
                        }
                      }}
                      onBlur={() => {
                        // Agregar cero a la izquierda si es necesario
                        if (newEvent.minutos.length === 1) {
                          setNewEvent((prev) => ({
                            ...prev,
                            minutos: prev.minutos.padStart(2, "0"),
                          }));
                        }
                      }}
                      keyboardType="number-pad"
                      maxLength={2}
                    />
                  </View>
                </View>

                {/* Campo Descripción */}
                <LabeledInput
                  label="Descripción (Opcional)"
                  containerClassName="mb-4"
                >
                  <TextInput
                    placeholder="Detalles adicionales sobre el evento..."
                    className="border border-slate-300 rounded-xl px-4 py-3 text-slate-900 bg-white h-20"
                    style={{ textAlignVertical: "top" }}
                    multiline
                    value={newEvent.descripcion}
                    onChangeText={(text) =>
                      setNewEvent((prev) => ({
                        ...prev,
                        descripcion: text,
                      }))
                    }
                  />
                </LabeledInput>

                {/* Botones de Acción */}
                <View className="flex-row justify-end mt-4 gap-x-4">
                  <TouchableOpacity
                    onPress={handleCancelEvent}
                    className="bg-slate-200 px-5 py-3 rounded-lg"
                  >
                    <Text className="font-bold text-slate-600">Cancelar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={handleSaveEvent}
                    disabled={!newEvent.nombre.trim()}
                    style={[
                      {
                        paddingHorizontal: 20,
                        paddingVertical: 12,
                        borderRadius: 8,
                      },
                      newEvent.nombre.trim()
                        ? {
                          backgroundColor: "#6366f1",
                          shadowColor: "#6366f1",
                          shadowOffset: { width: 0, height: 2 },
                          shadowOpacity: 0.3,
                          shadowRadius: 4,
                          elevation: 4,
                        }
                        : { backgroundColor: "#cbd5e1" },
                    ]}
                  >
                    <Text
                      style={{
                        fontWeight: "bold",
                        color: newEvent.nombre.trim() ? "#ffffff" : "#64748b",
                      }}
                    >
                      {editingEventId ? "Actualizar" : "Guardar Evento"}
                    </Text>
                  </TouchableOpacity>
                </View>
              </ScrollView>
            ) : (
              // --- VISTA POR DEFECTO (LISTA DE EVENTOS O MENSAJE) ---

              <View className="flex-1 relative">
                {loading ? (
                  <View className="flex-1 justify-center items-center">
                    <ActivityIndicator size="large" color="#6F09EA" />
                  </View>
                ) : (
                  <>
                    <View
                      className="flex-1"
                      style={{ opacity: isRefetching ? 0.5 : 1 }}
                    >
                      <ScrollView
                        className="flex-1"
                        contentContainerStyle={{
                          paddingBottom: 20,
                          flexGrow: 1,
                        }}
                        nestedScrollEnabled={true}
                        scrollEventThrottle={16}
                        refreshControl={
                          <RefreshControl
                            refreshing={isRefetching}
                            onRefresh={handleRefresh}
                            tintColor="#6F09EA"
                            colors={["#6F09EA"]}
                          />
                        }
                      >
                        {visibleEvents.length > 0 ? (
                          visibleEvents.map((evento, index) => (
                            <Pressable
                              key={evento.id_evento || index}
                              onPress={() => {
                                if (evento.tipo !== "egreso") {
                                  handleEditEvent(evento);
                                }
                              }}
                              android_ripple={{ color: "rgba(0,0,0,0.05)" }}
                              className={`p-4 mb-3 bg-slate-50 rounded-xl border-l-4 shadow-sm border-l-indigo-500 ${evento.tipo === "egreso"
                                  ? "border-amber-200"
                                  : "border-indigo-500"
                                }`}
                              style={{
                                borderWidth: 0,
                                borderLeftWidth: 4,
                                borderColor:
                                  evento.tipo === "egreso"
                                    ? "#fcd34d"
                                    : "#6366f1", // Amber-300 para egresos, Indigo-500 para normales
                                borderLeftColor: "#6366f1", // Siempre Indigo-500
                              }}
                            >
                              <View className="flex-row justify-between items-start">
                                <View className="flex-1">
                                  <Text className="font-bold text-base text-slate-800 mb-1">
                                    {evento.nombre_evento}
                                  </Text>
                                  <Text className="text-slate-600 text-sm mb-2 leading-relaxed">
                                    {evento.detalles_evento}
                                  </Text>
                                  <View className="flex-row items-center">
                                    {/* Icono dinámico según tipo */}
                                    {evento.tipo === "egreso" ? (
                                      <Svg
                                        height="14"
                                        width="14"
                                        viewBox="0 -960 960 960"
                                        fill="#f59e0b"
                                        className="mr-1"
                                      >
                                        <Path d="M440-120v-80h80v80h-80Zm0-320v-80h80v80h-80Zm0-320v-80h80v80h-80ZM200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                                      </Svg>
                                    ) : (
                                      <Svg
                                        height="14"
                                        width="14"
                                        viewBox="0 -960 960 960"
                                        fill="#94a3b8"
                                        className="mr-1"
                                      >
                                        <Path d="M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Zm0-480h560v-80H200v80Zm0 0v-80 80Z" />
                                      </Svg>
                                    )}

                                    <Text
                                      className={`text-xs font-medium ${evento.tipo === "egreso" ? "text-amber-600" : "text-slate-500"}`}
                                    >
                                      {(() => {
                                        if (!evento.fechayhora_evento)
                                          return "";

                                        // Parsear el timestamp en formato local
                                        // Formato esperado: "YYYY-MM-DD HH:MM:SS"
                                        const timestampStr =
                                          evento.fechayhora_evento
                                            .replace("T", " ")
                                            .split(".")[0];
                                        const [datePart, timePart] =
                                          timestampStr.split(" ");
                                        const [year, month, day] = datePart
                                          .split("-")
                                          .map(Number);

                                        let hours = 0,
                                          minutes = 0;
                                        if (timePart) {
                                          const [h, m] = timePart
                                            .split(":")
                                            .map(Number);
                                          hours = h;
                                          minutes = m;
                                        }

                                        const dayStr = String(day).padStart(
                                          2,
                                          "0",
                                        );
                                        const monthStr = String(month).padStart(
                                          2,
                                          "0",
                                        );
                                        const hoursStr = String(hours).padStart(
                                          2,
                                          "0",
                                        );
                                        const minutesStr = String(
                                          minutes,
                                        ).padStart(2, "0");

                                        // Para egresos, solo mostramos fecha, no hora (ya que es ficticia)
                                        if (evento.tipo === "egreso") {
                                          return `${dayStr}/${monthStr}/${year} (Próximo pago)`;
                                        }
                                        return `${dayStr}/${monthStr}/${year} ${hoursStr}:${minutesStr}`;
                                      })()}
                                    </Text>
                                  </View>
                                </View>

                                {/* Botones de acción solo para eventos normales */}
                                {evento.tipo !== "egreso" && (
                                  <View className="flex-row items-center ml-2">
                                    <TouchableOpacity
                                      onPress={() => handleEditEvent(evento)}
                                      className="p-2 opacity-60"
                                    >
                                      <Svg
                                        height="20"
                                        viewBox="0 -960 960 960"
                                        width="20"
                                        fill="#64748b"
                                      >
                                        <Path d="M200-200h57l391-391-57-57-391 391v57Zm-80 80v-170l528-527q12-11 26.5-17t30.5-6q16 0 31 6t26 18l55 56q12 11 17.5 26t5.5 30q0 16-5.5 30.5T817-647L290-120H120Zm640-584-56-56 56 56Zm-141 85-28-29 57 57-29-28Z" />
                                      </Svg>
                                    </TouchableOpacity>
                                    <TouchableOpacity
                                      onPress={() =>
                                        handleDeleteEvent(evento.id_evento)
                                      }
                                      className="p-2 ml-1 opacity-60"
                                    >
                                      <Svg
                                        height="20"
                                        viewBox="0 -960 960 960"
                                        width="20"
                                        fill="#64748b"
                                      >
                                        <Path d="M280-120q-33 0-56.5-23.5T200-200v-520h-40v-80h200v-40h240v40h200v80h-40v520q0 33-23.5 56.5T680-120H280Zm400-600H280v520h400v-520ZM360-280h80v-360h-80v360Zm160 0h80v-360h-80v360ZM280-720v520-520Z" />
                                      </Svg>
                                    </TouchableOpacity>
                                  </View>
                                )}
                              </View>
                            </Pressable>
                          ))
                        ) : (
                          <View className="flex-1 justify-center items-center">
                            <Svg
                              height="60"
                              viewBox="0 -960 960 960"
                              width="60"
                              fill="#cbd5e1"
                            >
                              <Path d="M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Zm0-480h560v-80H200v80Zm0 0v-80 80Z" />
                            </Svg>
                            <Text className="text-slate-500 font-semibold mt-4 text-center">
                              No hay eventos registrados.
                            </Text>
                            <Text className="text-slate-400 text-sm mt-1 text-center">
                              Agrega un nuevo evento para comenzar.
                            </Text>
                          </View>
                        )}
                      </ScrollView>
                    </View>
                    {isRefetching && (
                      <View
                        style={StyleSheet.absoluteFill}
                        className="absolute inset-0 bg-white/50 flex items-center justify-center"
                      >
                        <ActivityIndicator size="large" color="#6F09EA" />
                      </View>
                    )}
                  </>
                )}
              </View>
            )}
          </View>
        </View>
      </View>
    </TouchableWithoutFeedback>
  );
};


const styles = StyleSheet.create({
  dateSeparator: {
    fontSize: 16,
    color: "#9ca3af",
  },
});

export default ScreenCalendario;

import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  ScrollView,
  Image,
  ActivityIndicator,
  Platform,
  Modal,
} from "react-native";
import * as ImagePicker from "expo-image-picker";
import * as DocumentPicker from "expo-document-picker";
import * as FileSystem from "expo-file-system";
import { decode } from "base64-arraybuffer";
import { supabase } from "../../lib/supabase";
import { useAuthContext } from "../../hooks/use-auth-context";
import { useConfirm, useNotify } from "../../hooks/use-confirm";
import { invalidateCatalogCache } from "../../lib/catalogCache";
import Svg, { Path } from "react-native-svg";
import {
  APP_SETTING_KEYS,
  DEFAULT_BANK_DETAILS,
  DEFAULT_PAYMENT_CONTENT,
  DEFAULT_TICKET_BRANDING,
  loadAppSetting,
  saveAppSetting,
} from "../../lib/appSettings";
import {
  TICKET_LOGO_BUCKET,
  TICKET_LOGO_PATH,
  getTicketLogoUri,
  ticketLogoSource,
} from "../../lib/ticketBranding";

export default function ScreenConfiguracion() {
  const { session, profile, refreshProfile } = useAuthContext();
  const confirm = useConfirm();
  const { notifySuccess, notifyError, notify } = useNotify();
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [isPreviewVisible, setIsPreviewVisible] = useState(false);
  const [activeTab, setActiveTab] = useState("perfil"); // "perfil" | "pagos" | "archivos"

  // Estados del formulario
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [avatarUrl, setAvatarUrl] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const [bankBanco, setBankBanco] = useState("");
  const [bankBeneficiario, setBankBeneficiario] = useState("");
  const [bankCuenta, setBankCuenta] = useState("");
  const [bankClabe, setBankClabe] = useState("");
  const [loadingBank, setLoadingBank] = useState(false);
  const [paymentContent, setPaymentContent] = useState(DEFAULT_PAYMENT_CONTENT);
  const [loadingPaymentContent, setLoadingPaymentContent] = useState(false);
  const [ticketBranding, setTicketBranding] = useState(DEFAULT_TICKET_BRANDING);
  const [loadingTicketBranding, setLoadingTicketBranding] = useState(false);
  const [ticketLogoPreviewUri, setTicketLogoPreviewUri] = useState("");

  const [catalogFiles, setCatalogFiles] = useState([]);
  const [tarifarioFiles, setTarifarioFiles] = useState([]);
  const [loadingFiles, setLoadingFiles] = useState(false);

  const loadBankSettings = async () => {
    try {
      const settings = await loadAppSetting(
        APP_SETTING_KEYS.bankDetails,
        DEFAULT_BANK_DETAILS,
      );
      setBankBanco(settings.banco || "");
      setBankBeneficiario(settings.beneficiario || "");
      setBankCuenta(settings.cuenta || "");
      setBankClabe(settings.clabe || "");
    } catch (err) {
      console.error("Error loading bank settings:", err);
    }
  };

  const loadPaymentContentSettings = async () => {
    try {
      const settings = await loadAppSetting(
        APP_SETTING_KEYS.paymentContent,
        DEFAULT_PAYMENT_CONTENT,
      );
      setPaymentContent(settings);
    } catch (err) {
      console.error("Error loading payment content settings:", err);
    }
  };

  const loadTicketBrandingSettings = async () => {
    try {
      const settings = await loadAppSetting(
        APP_SETTING_KEYS.ticketBranding,
        DEFAULT_TICKET_BRANDING,
      );
      setTicketBranding(settings);
      const resolvedLogoUri = await getTicketLogoUri();
      setTicketLogoPreviewUri(settings.logoPath ? resolvedLogoUri : "");
    } catch (err) {
      console.error("Error loading ticket branding settings:", err);
    }
  };

  const saveBankSettings = async () => {
    setLoadingBank(true);
    try {
      await saveAppSetting(APP_SETTING_KEYS.bankDetails, {
        banco: bankBanco,
        beneficiario: bankBeneficiario,
        cuenta: bankCuenta,
        clabe: bankClabe,
      });
      notifySuccess("Datos bancarios actualizados correctamente");
    } catch (err) {
      console.error("Error saving bank settings:", err);
      notifyError("No se pudieron guardar los datos bancarios");
    } finally {
      setLoadingBank(false);
    }
  };

  const updatePaymentContentField = (field, value) => {
    setPaymentContent((current) => ({ ...current, [field]: value }));
  };

  const updatePaymentContentArrayField = (field, index, value) => {
    setPaymentContent((current) => {
      const nextValues = [...(current[field] || [])];
      nextValues[index] = value;
      return { ...current, [field]: nextValues };
    });
  };

  const savePaymentContentSettings = async () => {
    setLoadingPaymentContent(true);
    try {
      await saveAppSetting(APP_SETTING_KEYS.paymentContent, paymentContent);
      notifySuccess("Contenido de pagos actualizado correctamente");
    } catch (err) {
      console.error("Error saving payment content settings:", err);
      notifyError("No se pudo guardar el contenido de pagos");
    } finally {
      setLoadingPaymentContent(false);
    }
  };

  const updateTicketBrandingField = (field, value) => {
    setTicketBranding((current) => ({ ...current, [field]: value }));
  };

  const clampLogoSize = (value, fallback) => {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) return fallback;
    return Math.max(40, Math.min(320, parsed));
  };

  const updateTicketLogoDimension = (field, delta) => {
    setTicketBranding((current) => {
      const fallback =
        field === "logoWidth"
          ? DEFAULT_TICKET_BRANDING.logoWidth
          : DEFAULT_TICKET_BRANDING.logoHeight;
      const nextValue = clampLogoSize((current[field] || fallback) + delta, fallback);
      return {
        ...current,
        [field]: nextValue,
      };
    });
  };

  const applyTicketLogoPreset = (logoWidth, logoHeight) => {
    setTicketBranding((current) => ({
      ...current,
      logoWidth,
      logoHeight,
    }));
  };

  const saveTicketBrandingSettings = async () => {
    setLoadingTicketBranding(true);
    try {
      await saveAppSetting(APP_SETTING_KEYS.ticketBranding, {
        logoPath: ticketBranding.logoPath || "",
        logoUpdatedAt: ticketBranding.logoUpdatedAt || "",
        logoWidth:
          Number(ticketBranding.logoWidth) || DEFAULT_TICKET_BRANDING.logoWidth,
        logoHeight:
          Number(ticketBranding.logoHeight) ||
          DEFAULT_TICKET_BRANDING.logoHeight,
      });
      notifySuccess("Logo del ticket actualizado correctamente");
    } catch (err) {
      console.error("Error saving ticket branding settings:", err);
      notifyError("No se pudo guardar el logo del ticket");
    } finally {
      setLoadingTicketBranding(false);
    }
  };

  const ensureStorageBucket = async (bucketName) => {
    const { error } = await supabase.functions.invoke("ensure-storage-bucket", {
      body: {
        bucketName,
        isPublic: true,
        allowedMimeTypes: ["image/png", "image/jpeg", "image/webp", "image/svg+xml"],
      },
    });

    if (error) {
      throw error;
    }
  };

  const pickTicketLogo = async () => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();

    if (status !== "granted") {
      notifyError(
        "Necesitamos permiso para acceder a tus fotos.",
        "Permiso denegado",
      );
      return;
    }

    try {
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        allowsEditing: true,
        quality: 0.8,
      });

      if (!result.canceled && result.assets[0]) {
        setLoadingTicketBranding(true);
        const asset = result.assets[0];
        let fileData;

        await ensureStorageBucket(TICKET_LOGO_BUCKET);

        if (Platform.OS === "web") {
          const response = await fetch(asset.uri);
          const blob = await response.blob();
          fileData = await blob.arrayBuffer();
        } else {
          const base64 = await FileSystem.readAsStringAsync(asset.uri, {
            encoding: FileSystem.EncodingType.Base64,
          });
          fileData = decode(base64);
        }

        const contentType = asset.mimeType || "image/png";
        const { error } = await supabase.storage
          .from(TICKET_LOGO_BUCKET)
          .upload(TICKET_LOGO_PATH, fileData, {
            contentType,
            upsert: true,
          });

        if (error) throw error;

        const logoUpdatedAt = new Date().toISOString();
        const {
          data: { publicUrl },
        } = supabase.storage.from(TICKET_LOGO_BUCKET).getPublicUrl(TICKET_LOGO_PATH);

        setTicketLogoPreviewUri(
          `${publicUrl}?t=${encodeURIComponent(logoUpdatedAt)}`,
        );
        setTicketBranding((current) => ({
          ...current,
          logoPath: TICKET_LOGO_PATH,
          logoUpdatedAt,
        }));
      }
    } catch (error) {
      console.error("Error picking ticket logo:", error);
      notifyError(`No se pudo seleccionar el logo: ${error.message}`);
    } finally {
      setLoadingTicketBranding(false);
    }
  };

  const removeTicketLogo = async () => {
    setLoadingTicketBranding(true);
    try {
      if (ticketBranding.logoPath) {
        const { error } = await supabase.storage
          .from(TICKET_LOGO_BUCKET)
          .remove([ticketBranding.logoPath]);

        if (error) throw error;
      }

      const nextSettings = {
        ...ticketBranding,
        logoPath: "",
        logoUpdatedAt: "",
      };

      setTicketBranding(nextSettings);
      setTicketLogoPreviewUri("");
      await saveAppSetting(APP_SETTING_KEYS.ticketBranding, nextSettings);
      notifySuccess("Logo del ticket eliminado correctamente");
    } catch (error) {
      console.error("Error removing ticket logo:", error);
      notifyError("No se pudo eliminar el logo del ticket");
    } finally {
      setLoadingTicketBranding(false);
    }
  };

  const loadFilesFromBucket = async () => {
    setLoadingFiles(true);
    try {
      // List catalogs
      const { data: catData, error: catErr } = await supabase.storage
        .from("Catalogos")
        .list("");
      
      if (!catErr && catData) {
        setCatalogFiles(catData.filter(f => f.name !== ".emptyFolderPlaceholder"));
      }

      // List prices
      const { data: tarData, error: tarErr } = await supabase.storage
        .from("Tarifarios")
        .list("");
      
      if (!tarErr && tarData) {
        setTarifarioFiles(tarData.filter(f => f.name !== ".emptyFolderPlaceholder"));
      }
    } catch (err) {
      console.error("Error listing storage files:", err);
    } finally {
      setLoadingFiles(false);
    }
  };

  const readAssetData = async (asset) => {
    if (Platform.OS === "web") {
      const response = await fetch(asset.uri);
      const blob = await response.blob();
      return blob.arrayBuffer();
    }
    const base64 = await FileSystem.readAsStringAsync(asset.uri, {
      encoding: FileSystem.EncodingType.Base64,
    });
    return decode(base64);
  };

  const uploadFileToBucket = async (bucketName) => {
    try {
      const result = await DocumentPicker.getDocumentAsync({
        type: ["image/*", "application/pdf"],
        multiple: true, // Permite seleccionar varias imágenes / PDF a la vez
      });

      if (result.canceled || !result.assets?.length) return;

      setLoadingFiles(true);

      const assets = result.assets;
      let uploaded = 0;
      const failed = [];

      // Subimos cada archivo por separado; se mostrarán como páginas en el visor.
      for (const asset of assets) {
        try {
          // Nombre seguro para el storage
          const cleanName = asset.name.replace(/[^a-zA-Z0-9.-]/g, "_");
          const fileData = await readAssetData(asset);

          const { error } = await supabase.storage
            .from(bucketName)
            .upload(cleanName, fileData, {
              contentType: asset.mimeType || "application/octet-stream",
              upsert: true,
            });

          if (error) throw error;
          uploaded += 1;
        } catch (fileError) {
          console.error(`Error subiendo ${asset.name}:`, fileError);
          failed.push(asset.name);
        }
      }

      // Invalida el caché del visor para que muestre los archivos nuevos.
      invalidateCatalogCache(bucketName);
      await loadFilesFromBucket();

      if (uploaded > 0 && failed.length === 0) {
        notifySuccess(
          uploaded === 1
            ? "Archivo subido correctamente"
            : `${uploaded} archivos subidos correctamente`,
        );
      } else if (uploaded > 0 && failed.length > 0) {
        notify({
          type: "warning",
          title: "Subida parcial",
          message: `Se subieron ${uploaded} de ${assets.length}. Fallaron: ${failed.join(", ")}`,
        });
      } else {
        notifyError("No se pudo subir ningún archivo.");
      }
    } catch (err) {
      console.error("Error uploading file:", err);
      notifyError(`No se pudieron subir los archivos: ${err.message}`);
    } finally {
      setLoadingFiles(false);
    }
  };

  const deleteFileFromBucket = async (bucketName, fileName) => {
    const ok = await confirm({
      title: "Confirmar eliminación",
      message: `¿Estás seguro de que quieres eliminar "${fileName}"?`,
      confirmText: "Eliminar",
      type: "destructive",
    });

    if (!ok) return;

    setLoadingFiles(true);
    try {
      const { error } = await supabase.storage
        .from(bucketName)
        .remove([fileName]);

      if (error) throw error;

      invalidateCatalogCache(bucketName);
      await loadFilesFromBucket();
      notifySuccess("Archivo eliminado correctamente");
    } catch (err) {
      console.error("Error deleting file:", err);
      notifyError("No se pudo eliminar el archivo");
    } finally {
      setLoadingFiles(false);
    }
  };

  const replaceFileInBucket = async (bucketName, oldFileName) => {
    try {
      const result = await DocumentPicker.getDocumentAsync({
        type: ["image/*", "application/pdf"],
        multiple: false,
      });

      if (result.canceled || !result.assets?.length) return;

      const asset = result.assets[0];
      setLoadingFiles(true);

      // Eliminar el archivo anterior
      const { error: removeError } = await supabase.storage
        .from(bucketName)
        .remove([oldFileName]);

      if (removeError) throw removeError;

      // Subir el nuevo archivo con el mismo nombre
      const cleanName = asset.name.replace(/[^a-zA-Z0-9.-]/g, "_");
      const fileData = await readAssetData(asset);

      const { error: uploadError } = await supabase.storage
        .from(bucketName)
        .upload(cleanName, fileData, {
          contentType: asset.mimeType || "application/octet-stream",
          upsert: true,
        });

      if (uploadError) throw uploadError;

      invalidateCatalogCache(bucketName);
      await loadFilesFromBucket();
      notifySuccess("Archivo reemplazado correctamente");
    } catch (err) {
      console.error("Error replacing file:", err);
      notifyError(`No se pudo reemplazar el archivo: ${err.message}`);
    } finally {
      setLoadingFiles(false);
    }
  };

  useEffect(() => {
    if (profile) {
      setFullName(profile.full_name || "");

      // Si tenemos avatar_url en el perfil, la usamos. Si no, buscamos el archivo en el bucket
      if (profile.avatar_url) {
        setAvatarUrl(profile.avatar_url);
      } else if (session?.user?.id) {
        loadAvatarFromStorage();
      }
    }
      if (session?.user) {
        setEmail(session.user.email || "");
        loadBankSettings();
        loadPaymentContentSettings();
        loadTicketBrandingSettings();
        loadFilesFromBucket();
      }
  }, [profile, session]);

  const loadAvatarFromStorage = async () => {
    if (!session?.user?.id) return;

    try {
      // Intentar buscar en la carpeta del usuario
      let { data, error } = await supabase.storage
        .from("PPUser")
        .list(session.user.id, {
          limit: 10,
          offset: 0,
        });

      // Si no hay archivos en la carpeta del usuario, intentar en la raíz
      if (!data || data.length === 0) {
        const rootResult = await supabase.storage.from("PPUser").list("", {
          limit: 50,
          offset: 0,
        });

        data = rootResult.data;
        error = rootResult.error;
      }

      if (error) {
        console.error("Error listing files:", error);
        return;
      }

      // Buscar archivo que comience con "avatar" o que contenga el ID del usuario
      const avatarFile = data?.find(
        (file) =>
          file.name.startsWith("avatar.") ||
          file.name.includes(session.user.id),
      );

      if (avatarFile) {
        // Determinar la ruta correcta
        const filePath = avatarFile.name.includes("/")
          ? avatarFile.name
          : `${session.user.id}/${avatarFile.name}`;

        const {
          data: { publicUrl },
        } = supabase.storage.from("PPUser").getPublicUrl(filePath);

        // Añadimos timestamp para evitar caché
        setAvatarUrl(`${publicUrl}?t=${Date.now()}`);
      }
    } catch (error) {
      console.error("Error loading avatar:", error);
    }
  };

  const pickImage = async () => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();

    if (status !== "granted") {
      notifyError(
        "Necesitamos permiso para acceder a tus fotos.",
        "Permiso denegado",
      );
      return;
    }

    try {
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        allowsEditing: true,
        aspect: [1, 1],
        quality: 0.5,
        base64: true,
      });

      if (!result.canceled && result.assets[0]) {
        // Mostrar previsualización inmediata de la imagen local
        setAvatarUrl(result.assets[0].uri);
        // Luego subir la imagen
        await uploadAvatar(result.assets[0]);
      }
    } catch (error) {
      console.error("Error picking image:", error);
      notifyError(`No se pudo seleccionar la imagen: ${error.message}`);
    }
  };
  const uploadAvatar = async (asset) => {
    if (!session?.user?.id) {
      notifyError("No se pudo obtener la información del usuario");
      return;
    }

    try {
      setUploading(true);

      if (!asset.base64) {
        throw new Error("No se pudo obtener el contenido de la imagen");
      }

      const fileExt = asset.uri.split(".").pop()?.toLowerCase() || "jpg";
      // Usamos un nombre fijo para no necesitar guardar la URL en la BD
      const fileName = `avatar.${fileExt}`;
      const filePath = `${session.user.id}/${fileName}`;

      // Convertir base64 a ArrayBuffer
      const fileData = decode(asset.base64);

      // Subir a Supabase Storage (sobrescribiendo si existe)
      const { error: uploadError } = await supabase.storage
        .from("PPUser")
        .upload(filePath, fileData, {
          contentType: `image/${fileExt}`,
          upsert: true,
        });

      if (uploadError) {
        throw uploadError;
      }

      // Actualizar el campo updated_at en profiles para forzar recarga en AppHeader
      await supabase
        .from("profiles")
        .update({ updated_at: new Date().toISOString() })
        .eq("id", session.user.id);

      // Recargar el avatar desde el storage para obtener la URL correcta
      await loadAvatarFromStorage();

      await refreshProfile();
      notifySuccess("Foto de perfil actualizada correctamente");
    } catch (error) {
      console.error("Error uploading avatar:", error);
      notifyError(`No se pudo subir la foto de perfil: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };

  const updateProfile = async () => {
    if (!session?.user?.id) {
      notifyError("No se pudo obtener la información del usuario");
      return;
    }

    try {
      setLoading(true);

      // Actualizar nombre en profiles
      const { error: profileError } = await supabase
        .from("profiles")
        .update({ full_name: fullName })
        .eq("id", session.user.id);

      if (profileError) throw profileError;

      await refreshProfile();
      notifySuccess("Perfil actualizado correctamente");
    } catch (error) {
      console.error("Error updating profile:", error);
      notifyError("No se pudo actualizar el perfil");
    } finally {
      setLoading(false);
    }
  };

  const deleteAvatar = async () => {
    const ok = await confirm({
      title: "Eliminar foto de perfil",
      message: "¿Estás seguro de que quieres eliminar tu foto de perfil?",
      confirmText: "Eliminar",
      type: "destructive",
    });

    if (!ok) return;

    try {
      setUploading(true);

      // Buscar y eliminar el archivo del bucket
      const { data: files } = await supabase.storage
        .from("PPUser")
        .list(session.user.id);

      const avatarFile = files?.find((file) =>
        file.name.startsWith("avatar."),
      );

      if (avatarFile) {
        const { error } = await supabase.storage
          .from("PPUser")
          .remove([`${session.user.id}/${avatarFile.name}`]);

        if (error) throw error;
      }

      // Actualizar el campo updated_at en profiles para forzar recarga en AppHeader
      await supabase
        .from("profiles")
        .update({ updated_at: new Date().toISOString() })
        .eq("id", session.user.id);

      setAvatarUrl("");
      await refreshProfile();
      notifySuccess("Foto de perfil eliminada correctamente");
    } catch (error) {
      console.error("Error deleting avatar:", error);
      notifyError("No se pudo eliminar la foto de perfil");
    } finally {
      setUploading(false);
    }
  };

  const getInitials = (name) => {
    if (!name) return "??";
    const parts = name.trim().split(" ");
    if (parts.length === 1) {
      return parts[0].substring(0, 2).toUpperCase();
    }
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  };

  const updateEmail = async () => {
    try {
      setLoading(true);

      const { error } = await supabase.auth.updateUser({ email });

      if (error) throw error;

      notifySuccess(
        "Se ha enviado un correo de confirmación a tu nueva dirección de email",
      );
    } catch (error) {
      console.error("Error updating email:", error);
      notifyError("No se pudo actualizar el correo electrónico");
    } finally {
      setLoading(false);
    }
  };

  const updatePassword = async () => {
    if (newPassword !== confirmPassword) {
      notifyError("Las contraseñas no coinciden");
      return;
    }

    if (newPassword.length < 6) {
      notifyError("La contraseña debe tener al menos 6 caracteres");
      return;
    }

    try {
      setLoading(true);

      const { error } = await supabase.auth.updateUser({
        password: newPassword,
      });

      if (error) throw error;

      setNewPassword("");
      setConfirmPassword("");
      notifySuccess("Contraseña actualizada correctamente");
    } catch (error) {
      console.error("Error updating password:", error);
      notifyError("No se pudo actualizar la contraseña");
    } finally {
      setLoading(false);
    }
  };

  // Mostrar indicador de carga si no hay sesión
  if (!session) {
    return (
      <View className="flex-1 bg-slate-50 justify-center items-center">
        <ActivityIndicator size="large" color="#6366f1" />
        <Text className="text-slate-600 mt-4">Cargando configuración...</Text>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-slate-50">
      {/* Barra de pestañas (Tabs) */}
      <View className="flex-row border-b border-slate-200 bg-white p-2.5 gap-2 shadow-sm">
        <TouchableOpacity
          onPress={() => setActiveTab("perfil")}
          className={`flex-1 flex-row items-center justify-center gap-2 py-3 rounded-xl ${
            activeTab === "perfil" ? "bg-[#6F09EA]" : "bg-slate-50"
          }`}
          activeOpacity={0.8}
        >
          <Svg
            height="20"
            viewBox="0 -960 960 960"
            width="20"
            fill={activeTab === "perfil" ? "#ffffff" : "#64748b"}
          >
            <Path d="M480-480q-66 0-113-47t-47-113q0-66 47-113t113-47q66 0 113 47t47 113q0 66-47 113t-113 47ZM160-240v-32q0-34 17.5-62.5T224-378q62-31 126-46.5T480-440q66 0 130 15.5T736-378q30 15 47 43.5t17 62.5v32q0 33-23.5 56.5T720-160H240q-33 0-56.5-23.5T160-240Z" />
          </Svg>
          <Text
            className={`font-bold text-sm ${
              activeTab === "perfil" ? "text-white" : "text-slate-600"
            }`}
          >
            Mi Perfil
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={() => setActiveTab("pagos")}
          className={`flex-1 flex-row items-center justify-center gap-2 py-3 rounded-xl ${
            activeTab === "pagos" ? "bg-[#6F09EA]" : "bg-slate-50"
          }`}
          activeOpacity={0.8}
        >
          <Svg
            height="20"
            viewBox="0 -960 960 960"
            width="20"
            fill={activeTab === "pagos" ? "#ffffff" : "#64748b"}
          >
            <Path d="M880-120H80v-80h800v80ZM240-280H160v-360h80v360Zm160 0h-80v-360h80v360Zm160 0h-80v-360h80v360Zm160 0h-80v-360h80v360ZM480-720 80-520v-80l400-200 400 200v80L480-720Z" />
          </Svg>
          <Text
            className={`font-bold text-sm ${
              activeTab === "pagos" ? "text-white" : "text-slate-600"
            }`}
          >
            Pagos
          </Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={() => setActiveTab("archivos")}
          className={`flex-1 flex-row items-center justify-center gap-2 py-3 rounded-xl ${
            activeTab === "archivos" ? "bg-[#6F09EA]" : "bg-slate-50"
          }`}
          activeOpacity={0.8}
        >
          <Svg
            height="20"
            viewBox="0 -960 960 960"
            width="20"
            fill={activeTab === "archivos" ? "#ffffff" : "#64748b"}
          >
            <Path d="M320-240h320v-80H320v80Zm0-160h320v-80H320v80ZM240-80q-33 0-56.5-23.5T160-200v-560q0-33 23.5-56.5T240-880h320l240 240v440q0 33-23.5 56.5T720-80H240Zm280-560v-160H240v560h480v-400H520ZM240-800v160-160 560-560Z" />
          </Svg>
          <Text
            className={`font-bold text-sm ${
              activeTab === "archivos" ? "text-white" : "text-slate-600"
            }`}
          >
            Archivos
          </Text>
        </TouchableOpacity>
      </View>

      <ScrollView
        className="flex-1 bg-slate-50"
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode="interactive"
        automaticallyAdjustKeyboardInsets
        contentContainerStyle={{ paddingBottom: 100 }}
      >
        <View className="px-3 md:px-6 lg:px-8 w-full">
          {activeTab === "perfil" && (
            <View className="flex-col md:flex-row gap-6 items-start w-full">
              {/* Columna Izquierda */}
              <View className="flex-1 w-full gap-6">
                {/* Sección de foto de perfil */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Foto de Perfil
                  </Text>

                  <View className="items-center">
                    <TouchableOpacity
                      onPress={() => avatarUrl && setIsPreviewVisible(true)}
                      activeOpacity={avatarUrl ? 0.7 : 1}
                    >
                      <View className="relative">
                        {avatarUrl ? (
                          <Image
                            source={{ uri: avatarUrl }}
                            className="w-32 h-32 rounded-full border-4 border-indigo-500"
                          />
                        ) : (
                          <View className="w-32 h-32 rounded-full bg-indigo-500 items-center justify-center border-4 border-indigo-500">
                            <Text className="text-white text-4xl font-bold">
                              {getInitials(fullName)}
                            </Text>
                          </View>
                        )}

                        {uploading && (
                          <View className="absolute inset-0 bg-black/50 rounded-full items-center justify-center">
                            <ActivityIndicator size="large" color="#ffffff" />
                          </View>
                        )}
                      </View>
                    </TouchableOpacity>

                    <View className="flex-row gap-3 mt-4">
                      <TouchableOpacity
                        onPress={pickImage}
                        disabled={uploading}
                        className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                      >
                        <Text className="text-white font-bold">
                          {uploading
                            ? "Subiendo..."
                            : avatarUrl
                              ? "Cambiar Foto"
                              : "Subir Foto"}
                        </Text>
                      </TouchableOpacity>

                      {avatarUrl && !uploading && (
                        <TouchableOpacity
                          onPress={deleteAvatar}
                          className="bg-red-600 px-6 py-3 rounded-lg shadow-md shadow-red-600/30"
                        >
                          <Text className="text-white font-bold">Eliminar</Text>
                        </TouchableOpacity>
                      )}
                    </View>
                  </View>

                  {/* Modal de previsualización */}
                  <Modal
                    visible={isPreviewVisible}
                    transparent={true}
                    animationType="fade"
                    onRequestClose={() => setIsPreviewVisible(false)}
                  >
                    <TouchableOpacity
                      activeOpacity={1}
                      onPress={() => setIsPreviewVisible(false)}
                      className="flex-1 bg-black/90 justify-center items-center"
                    >
                      <Image
                        source={{ uri: avatarUrl }}
                        className="w-11/12 h-96 rounded-2xl"
                        resizeMode="contain"
                      />
                      <TouchableOpacity
                        onPress={() => setIsPreviewVisible(false)}
                        className="mt-6 bg-white px-8 py-3 rounded-full"
                      >
                        <Text className="text-slate-900 font-bold">Cerrar</Text>
                      </TouchableOpacity>
                    </TouchableOpacity>
                  </Modal>
                </View>

                {/* Sección de información personal */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Información Personal
                  </Text>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Nombre Completo
                    </Text>
                    <TextInput
                      value={fullName}
                      onChangeText={setFullName}
                      placeholder="Ingresa tu nombre completo"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <TouchableOpacity
                    onPress={updateProfile}
                    disabled={loading}
                    className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                  >
                    <Text className="text-white font-bold text-center">
                      {loading ? "Guardando..." : "Guardar Cambios"}
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>

              {/* Columna Derecha */}
              <View className="flex-1 w-full gap-6">
                {/* Sección de correo electrónico */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Correo Electrónico
                  </Text>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Email
                    </Text>
                    <TextInput
                      value={email}
                      onChangeText={setEmail}
                      placeholder="correo@ejemplo.com"
                      keyboardType="email-address"
                      autoCapitalize="none"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <TouchableOpacity
                    onPress={updateEmail}
                    disabled={loading}
                    className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                  >
                    <Text className="text-white font-bold text-center">
                      {loading ? "Actualizando..." : "Actualizar Email"}
                    </Text>
                  </TouchableOpacity>

                  <Text className="text-slate-500 text-xs mt-2">
                    Se enviará un correo de confirmación a tu nueva dirección
                  </Text>
                </View>

                {/* Sección de contraseña */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Cambiar Contraseña
                  </Text>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Nueva Contraseña
                    </Text>
                    <TextInput
                      value={newPassword}
                      onChangeText={setNewPassword}
                      placeholder="Mínimo 6 caracteres"
                      secureTextEntry
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Confirmar Contraseña
                    </Text>
                    <TextInput
                      value={confirmPassword}
                      onChangeText={setConfirmPassword}
                      placeholder="Repite la nueva contraseña"
                      secureTextEntry
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <TouchableOpacity
                    onPress={updatePassword}
                    disabled={loading || !newPassword || !confirmPassword}
                    className={`px-6 py-3 rounded-lg shadow-md ${
                      loading || !newPassword || !confirmPassword
                        ? "bg-slate-400"
                        : "bg-indigo-600 shadow-indigo-600/30"
                    }`}
                  >
                    <Text className="text-white font-bold text-center">
                      {loading ? "Actualizando..." : "Cambiar Contraseña"}
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          )}

          {activeTab === "pagos" && (
            <View className="flex-col md:flex-row gap-6 items-start w-full">
              {/* Columna Izquierda */}
              <View className="flex-1 w-full gap-6">
                {/* Sección de Datos Bancarios */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Datos Bancarios de Pago
                  </Text>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Banco
                    </Text>
                    <TextInput
                      value={bankBanco}
                      onChangeText={setBankBanco}
                      placeholder="Ej. Bancoppel"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Beneficiario
                    </Text>
                    <TextInput
                      value={bankBeneficiario}
                      onChangeText={setBankBeneficiario}
                      placeholder="Ej. Nombre del titular"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Número de Cuenta
                    </Text>
                    <TextInput
                      value={bankCuenta}
                      onChangeText={setBankCuenta}
                      placeholder="Ej. 4169 1608 5392 8977"
                      keyboardType="numeric"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      CLABE Interbancaria
                    </Text>
                    <TextInput
                      value={bankClabe}
                      onChangeText={setBankClabe}
                      placeholder="Ej. 137628103732170052"
                      keyboardType="numeric"
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <TouchableOpacity
                    onPress={saveBankSettings}
                    disabled={loadingBank}
                    className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                  >
                    {loadingBank ? (
                      <ActivityIndicator size="small" color="#ffffff" />
                    ) : (
                      <Text className="text-white font-bold text-center">
                        Guardar Datos Bancarios
                      </Text>
                    )}
                  </TouchableOpacity>
                </View>

                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Logo del Ticket
                  </Text>

                  <Text className="text-slate-500 text-sm mb-4">
                    Este logo se mostrará en los tickets visuales y en las impresiones.
                  </Text>

                  <View className="items-center rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-5 mb-4">
                    <Image
                      source={
                        ticketLogoPreviewUri
                          ? { uri: ticketLogoPreviewUri }
                          : ticketLogoSource
                      }
                      resizeMode="contain"
                      style={{
                        width:
                          Number(ticketBranding.logoWidth) ||
                          DEFAULT_TICKET_BRANDING.logoWidth,
                        height:
                          Number(ticketBranding.logoHeight) ||
                          DEFAULT_TICKET_BRANDING.logoHeight,
                      }}
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Tamaño del logo
                    </Text>
                    <View className="flex-row gap-3 mb-3">
                      <View className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3">
                        <Text className="text-slate-500 text-xs font-semibold mb-2">
                          Ancho
                        </Text>
                        <View className="flex-row items-center justify-between">
                          <TouchableOpacity
                            onPress={() =>
                              updateTicketLogoDimension("logoWidth", -10)
                            }
                            className="bg-white border border-slate-300 w-10 h-10 rounded-lg items-center justify-center"
                          >
                            <Text className="text-slate-700 text-lg font-bold">-</Text>
                          </TouchableOpacity>
                          <Text className="text-slate-900 text-lg font-bold">
                            {Number(ticketBranding.logoWidth) ||
                              DEFAULT_TICKET_BRANDING.logoWidth}
                          </Text>
                          <TouchableOpacity
                            onPress={() =>
                              updateTicketLogoDimension("logoWidth", 10)
                            }
                            className="bg-white border border-slate-300 w-10 h-10 rounded-lg items-center justify-center"
                          >
                            <Text className="text-slate-700 text-lg font-bold">+</Text>
                          </TouchableOpacity>
                        </View>
                      </View>

                      <View className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3">
                        <Text className="text-slate-500 text-xs font-semibold mb-2">
                          Alto
                        </Text>
                        <View className="flex-row items-center justify-between">
                          <TouchableOpacity
                            onPress={() =>
                              updateTicketLogoDimension("logoHeight", -5)
                            }
                            className="bg-white border border-slate-300 w-10 h-10 rounded-lg items-center justify-center"
                          >
                            <Text className="text-slate-700 text-lg font-bold">-</Text>
                          </TouchableOpacity>
                          <Text className="text-slate-900 text-lg font-bold">
                            {Number(ticketBranding.logoHeight) ||
                              DEFAULT_TICKET_BRANDING.logoHeight}
                          </Text>
                          <TouchableOpacity
                            onPress={() =>
                              updateTicketLogoDimension("logoHeight", 5)
                            }
                            className="bg-white border border-slate-300 w-10 h-10 rounded-lg items-center justify-center"
                          >
                            <Text className="text-slate-700 text-lg font-bold">+</Text>
                          </TouchableOpacity>
                        </View>
                      </View>
                    </View>

                    <Text className="text-slate-500 text-xs font-semibold mb-2">
                      Tamaños rápidos
                    </Text>
                    <View className="flex-row flex-wrap gap-2">
                      {[
                        { label: "Chico", width: 150, height: 48 },
                        { label: "Medio", width: 188, height: 60 },
                        { label: "Grande", width: 220, height: 70 },
                        { label: "Extra", width: 250, height: 82 },
                      ].map((preset) => {
                        const isActive =
                          Number(ticketBranding.logoWidth) === preset.width &&
                          Number(ticketBranding.logoHeight) === preset.height;

                        return (
                          <TouchableOpacity
                            key={preset.label}
                            onPress={() =>
                              applyTicketLogoPreset(
                                preset.width,
                                preset.height,
                              )
                            }
                            className={`px-4 py-2 rounded-full border ${
                              isActive
                                ? "bg-indigo-600 border-indigo-600"
                                : "bg-white border-slate-300"
                            }`}
                          >
                            <Text
                              className={`font-bold text-xs ${
                                isActive ? "text-white" : "text-slate-700"
                              }`}
                            >
                              {preset.label}
                            </Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                  </View>

                  <View className="flex-row gap-3 mb-4">
                    <TouchableOpacity
                      onPress={pickTicketLogo}
                      className="bg-indigo-600 px-5 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                    >
                      <Text className="text-white font-bold">
                        {ticketBranding.logoPath ? "Cambiar Logo" : "Subir Logo"}
                      </Text>
                    </TouchableOpacity>

                    {ticketBranding.logoPath ? (
                      <TouchableOpacity
                        onPress={removeTicketLogo}
                        className="bg-red-600 px-5 py-3 rounded-lg shadow-md shadow-red-600/30"
                      >
                        <Text className="text-white font-bold">Quitar</Text>
                      </TouchableOpacity>
                    ) : null}
                  </View>

                  <TouchableOpacity
                    onPress={saveTicketBrandingSettings}
                    disabled={loadingTicketBranding}
                    className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                  >
                    {loadingTicketBranding ? (
                      <ActivityIndicator size="small" color="#ffffff" />
                    ) : (
                      <Text className="text-white font-bold text-center">
                        Guardar Logo del Ticket
                      </Text>
                    )}
                  </TouchableOpacity>
                </View>
              </View>

              {/* Columna Derecha */}
              <View className="flex-1 w-full gap-6">
                {/* Contenido de la Sección de Pagos */}
                <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                  <Text className="text-xl font-bold text-slate-800 mb-4">
                    Contenido de la Sección de Pagos
                  </Text>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Título principal
                    </Text>
                    <TextInput
                      value={paymentContent.headerTitle}
                      onChangeText={(value) =>
                        updatePaymentContentField("headerTitle", value)
                      }
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Subtítulo principal
                    </Text>
                    <TextInput
                      value={paymentContent.headerSubtitle}
                      onChangeText={(value) =>
                        updatePaymentContentField("headerSubtitle", value)
                      }
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  {paymentContent.instructions.map((instruction, index) => (
                    <View key={`instruction-${index}`} className="mb-4">
                      <Text className="text-slate-700 text-sm font-semibold mb-2">{`Instrucción ${
                        index + 1
                      }`}</Text>
                      <TextInput
                        value={instruction}
                        onChangeText={(value) =>
                          updatePaymentContentArrayField(
                            "instructions",
                            index,
                            value,
                          )
                        }
                        multiline
                        className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                      />
                    </View>
                  ))}

                  <View className="mb-4">
                    <Text className="text-slate-700 text-sm font-semibold mb-2">
                      Teléfono de contacto
                    </Text>
                    <TextInput
                      value={paymentContent.contactPhone}
                      onChangeText={(value) =>
                        updatePaymentContentField("contactPhone", value)
                      }
                      className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                    />
                  </View>

                  {paymentContent.locationLines.map((line, index) => (
                    <View key={`location-${index}`} className="mb-4">
                      <Text className="text-slate-700 text-sm font-semibold mb-2">{`Dirección ${
                        index + 1
                      }`}</Text>
                      <TextInput
                        value={line}
                        onChangeText={(value) =>
                          updatePaymentContentArrayField(
                            "locationLines",
                            index,
                            value,
                          )
                        }
                        className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                      />
                    </View>
                  ))}

                  {paymentContent.documents.map((document, index) => (
                    <View key={`document-${index}`} className="mb-4">
                      <Text className="text-slate-700 text-sm font-semibold mb-2">{`Documento ${
                        index + 1
                      }`}</Text>
                      <TextInput
                        value={document}
                        onChangeText={(value) =>
                          updatePaymentContentArrayField("documents", index, value)
                        }
                        multiline
                        className="border border-slate-300 rounded-lg px-4 py-3 text-slate-900 bg-white"
                      />
                    </View>
                  ))}

                  <TouchableOpacity
                    onPress={savePaymentContentSettings}
                    disabled={loadingPaymentContent}
                    className="bg-indigo-600 px-6 py-3 rounded-lg shadow-md shadow-indigo-600/30"
                  >
                    {loadingPaymentContent ? (
                      <ActivityIndicator size="small" color="#ffffff" />
                    ) : (
                      <Text className="text-white font-bold text-center">
                        Guardar Contenido de Pagos
                      </Text>
                    )}
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          )}

          {activeTab === "archivos" && (
            <>
              {/* Sección de Catálogos y Tarifarios */}
              <View className="bg-white rounded-2xl p-6 mb-6 shadow-sm border border-slate-200">
                <Text className="text-xl font-bold text-slate-800 mb-1">
                  Catálogo de Cursos y Tarifario
                </Text>
                <Text className="text-slate-500 text-xs mb-4">
                  Puedes seleccionar y subir varias imágenes o PDF a la vez. Cada
                  archivo se muestra como una página; se ordenan por nombre (usa
                  01, 02, 03… para el orden correcto).
                </Text>

                {loadingFiles ? (
                  <ActivityIndicator
                    size="large"
                    color="#6366f1"
                    className="my-4"
                  />
                ) : (
                  <View className="flex-col md:flex-row gap-6 w-full">
                    {/* Categoría Catálogo */}
                    <View className="flex-1 w-full mb-6 md:mb-0">
                      <View className="flex-row justify-between items-center mb-3">
                        <Text className="text-base font-bold text-slate-700">
                          Archivos del Catálogo
                        </Text>
                        <TouchableOpacity
                          onPress={() => uploadFileToBucket("Catalogos")}
                          className="bg-indigo-600 px-3 py-2 rounded-lg"
                        >
                          <Text className="text-white text-xs font-bold">
                            Subir Imágenes/PDF
                          </Text>
                        </TouchableOpacity>
                      </View>

                      {catalogFiles.length === 0 ? (
                        <Text className="text-slate-500 text-xs italic my-1">
                          No hay archivos personalizados. Se mostrarán los
                          predeterminados.
                        </Text>
                      ) : (
                        <View className="flex-row flex-wrap gap-3">
                          {catalogFiles.map((file) => (
                            <View
                              key={file.id || file.name}
                              className="bg-white rounded-xl border border-slate-200 overflow-hidden"
                              style={{ width: 140 }}
                            >
                              {file.isPdf ? (
                                <View className="h-24 bg-slate-100 items-center justify-center">
                                  <Svg height="32" viewBox="0 -960 960 960" width="32" fill="#dc2626">
                                    <Path d="M280-120q-33 0-56.5-23.5T200-200v-560q0-33 23.5-56.5T280-800h400l200 200v480q0 33-23.5 56.5T800-120H280Zm0-80h520v-430H640v-130H280v560Z" />
                                  </Svg>
                                  <Text className="text-slate-500 text-xs mt-1">PDF</Text>
                                </View>
                              ) : (
                                <Image
                                  source={{ uri: file.uri }}
                                  className="h-24"
                                  resizeMode="cover"
                                />
                              )}
                              <View className="p-2">
                                <Text className="text-slate-700 text-xs font-medium" numberOfLines={1}>
