          className={`border border-slate-300 rounded-xl px-4 py-3 text-slate-900 ${
            disabled ? "bg-slate-100 opacity-60" : "bg-white"
          }`}
          editable={!disabled}
          {...rest}
        />
        {!!error && (
          <Text className="text-red-600 text-xs mt-1 absolute -bottom-4 left-1">
            {error}
          </Text>
        )}
      </View>
    </TouchableOpacity>
  );
}

