  const egresoFormAnimation = useRef(new Animated.Value(0)).current;
  const { height } = useWindowDimensions();

  const fetchAvailableYears = useCallback(async () => {
    setLoadingYears(true);
    try {
      const [{ data: ingresos, error: ingresosError }, { data: egresos, error: egresosError }] =
        await Promise.all([
          supabase.from("ingresos").select("fecha_ingreso"),
          supabase.from("egresos").select("fecha_egreso, estado").eq("estado", "pagado"),
        ]);

      if (ingresosError || egresosError) {
        console.error("Error fetching years:", ingresosError || egresosError);
        return;
      }

      const currentYear = new Date().getFullYear();
      const years = new Set();

      ingresos?.forEach((item) => {
        if (item.fecha_ingreso) years.add(Number(item.fecha_ingreso.split("-")[0]));
      });

      egresos?.forEach((item) => {
        if (item.fecha_egreso) years.add(Number(item.fecha_egreso.split("-")[0]));
      });

      const sorted = [...years].sort((a, b) => b - a);
      const future = sorted
        .filter((year) => year > currentYear)
        .map((year) => ({ label: String(year), value: `year-${year}` }));
      const current = years.has(currentYear)
        ? [{ label: "Este ano", value: `year-${currentYear}` }]
        : [];
      const past = sorted
        .filter((year) => year < currentYear)
        .map((year) => ({ label: String(year), value: `year-${year}` }));

      setAvailableYears([...future, ...current, ...past]);
    } catch (error) {
      console.error("Error fetching available years:", error);
    } finally {
      setLoadingYears(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
