              </View>
            )}

            <View
              className="flex-row justify-between items-center mb-4"
              style={{ opacity: isAnyFormVisible ? 0.5 : 1 }}
              pointerEvents={isAnyFormVisible ? "none" : "auto"}
            >
              <View className="w-60">
                <Dropdown
                  style={[styles.dropdown, loadingYears && { opacity: 0.5 }]}
