                  value={selectedIngresoDateFilter}
                  onChange={(item) => {
                    setSelectedIngresoDateFilter(item.value);
                    if (syncDateFilters) setSelectedEgresoDateFilter(item.value);
                  }}
                  disable={loadingYears}
