                </Svg>
                <Text className="text-white font-bold ml-2">Agregar Ingreso</Text>
              </TouchableOpacity>
            </View>

            <TablaIngresos
              onEdit={openIngresoForm}
              refreshTrigger={ingresoRefreshTrigger}
              dateFilter={selectedIngresoDateFilter}
            />

            {isIngresoFormVisible && (
              <Animated.View
                style={[StyleSheet.absoluteFill, formContainerStyle(ingresoFormAnimation)]}
                className="absolute inset-0 z-10 bg-slate-50"
              >
                <RegistroIngreso
                  key={editingIngreso ? `edit-${editingIngreso.id}` : "new"}
                  ingresoToEdit={editingIngreso}
                  onFormClose={closeIngresoForm}
