      const { data: egresos, error } = await supabase
        .from("egresos")
        .select("*")
        .order("fecha_egreso", { ascending: false })
        .order("estado", { ascending: true });

      if (error) throw error;
      setData(egresos || []);
    } catch (error) {
      console.error("Error fetching egresos:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData, refreshTrigger]);

  useFocusEffect(
    useCallback(() => {
      fetchData();
    }, [fetchData]),
  );

  const filteredAndGroupedData = useMemo(() => {
    const now = new Date();
    let filtered = showPending
      ? data
      : data.filter((item) => item.estado !== "pendiente");

    if (dateFilter) {
      filtered = filtered.filter((item) => {
        if (!item.fecha_egreso) return false;
        const [year, month, day] = item.fecha_egreso.split("-").map(Number);
        const itemDate = new Date(year, month - 1, day, 12, 0, 0);

        if (dateFilter === "last_month") {
          const oneMonthAgo = new Date(now);
          oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);
          oneMonthAgo.setHours(0, 0, 0, 0);
          return itemDate >= oneMonthAgo;
        }

        if (dateFilter === "3_months_ago") {
          const threeMonthsAgo = new Date(now);
          threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);
          threeMonthsAgo.setHours(0, 0, 0, 0);
          return itemDate >= threeMonthsAgo;
        }

        if (String(dateFilter).startsWith("year-")) {
          return itemDate.getFullYear() === Number(String(dateFilter).split("-")[1]);
        }

        return true;
      });
    }

    const groups = {};
    filtered.forEach((item) => {
      if (!item.fecha_egreso) return;
      const [year, month] = item.fecha_egreso.split("-");
      const monthIndex = Number(month) - 1;
      const key = `${year}-${monthIndex}-${MONTH_NAMES[monthIndex]}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(item);
    });

    const keys = Object.keys(groups).sort((a, b) => {
      const [yearA, monthA] = a.split("-").map(Number);
      const [yearB, monthB] = b.split("-").map(Number);
      if (yearA !== yearB) return yearB - yearA;
      return monthB - monthA;
    });

    return { keys, data: groups };
  }, [data, dateFilter, showPending]);

  const onRefresh = async () => {
    setRefreshing(true);
    await fetchData();
    setRefreshing(false);
  };

  return (
    <View className="flex-1">
      <View className="flex-row justify-end mb-3">
        <TouchableOpacity
          onPress={() => setShowPending((current) => !current)}
          className={`px-4 py-2 rounded-full ${showPending ? "bg-amber-500" : "bg-slate-200"}`}
        >
          <Text className={showPending ? "text-white font-bold" : "text-slate-700 font-bold"}>
            {showPending ? "Incluyendo pendientes" : "Ocultar pendientes"}
          </Text>
        </TouchableOpacity>
      </View>

      <ScrollView
        contentContainerStyle={{ flexGrow: 1 }}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor="#6366f1" />
        }
      >
        <View className="rounded-xl overflow-hidden border border-slate-200 bg-white shadow-sm">
          <View className="bg-slate-100 border-b border-slate-200 flex-row">
            <Text style={{ flex: 4 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase">
              Nombre
            </Text>
            <Text style={{ flex: 5 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase">
              Descripcion
            </Text>
            <Text style={{ flex: 2.3 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase text-center">
              Fecha
            </Text>
            <Text style={{ flex: 2.5 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase text-center">
              Monto
            </Text>
            <Text style={{ flex: 2.2 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase text-center">
              Estado
            </Text>
            <Text style={{ flex: 1 }} className="py-3 px-3 text-slate-800 font-semibold text-xs uppercase text-center">
              Accion
            </Text>
          </View>

          {loading ? (
            <View className="p-8 items-center justify-center bg-white">
              <ActivityIndicator size="large" color="#6366f1" />
              <Text className="text-slate-500 text-center font-medium mt-4">
                Cargando egresos...
              </Text>
            </View>
          ) : filteredAndGroupedData.keys.length > 0 ? (
            filteredAndGroupedData.keys.map((key) => {
              const [year, , monthName] = key.split("-");
              const label =
                Number(year) === new Date().getFullYear()
                  ? monthName
                  : `${monthName} ${year}`;

              return (
                <View key={key}>
                  <View className="bg-red-600 py-3 px-4 flex-row items-center border-t border-red-700">
                    <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#ffffff">
                      <Path d="M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Z" />
                    </Svg>
                    <Text className="text-white font-bold text-lg ml-2">{label}</Text>
                  </View>

                  {filteredAndGroupedData.data[key].map((egreso, index) => (
                    <View
                      key={egreso.id_egreso || index}
                      style={{
                        flexDirection: "row",
                        alignItems: "center",
                        borderTopWidth: 1,
                        borderTopColor: "#e2e8f0",
                        backgroundColor: index % 2 ? "#ffffff" : "#f8fafc",
                      }}
                    >
                      <Text style={{ flex: 4 }} className="p-3 text-slate-800" numberOfLines={1}>
                        {egreso.nombre_egreso}
                      </Text>
                      <Text style={{ flex: 5 }} className="p-3 text-slate-700" numberOfLines={1}>
                        {egreso.desc_egreso || "-"}
                      </Text>
                      <Text style={{ flex: 2.3 }} className="p-3 text-slate-600 text-center">
                        {formatDateShort(egreso.fecha_egreso)}
                      </Text>
                      <Text style={{ flex: 2.5 }} className="p-3 text-slate-800 font-medium text-center">
                        {currencyFormatter.format(egreso.monto_egreso || 0)}
                      </Text>
                      <Text
                        style={{ flex: 2.2 }}
                        className={`p-3 text-center font-semibold ${egreso.estado === "pagado" ? "text-emerald-600" : "text-amber-600"}`}
                      >
                        {egreso.estado}
                      </Text>
                      <View style={{ flex: 1 }} className="p-3 items-center">
                        <TouchableOpacity onPress={() => onEdit(egreso)}>
                          <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#6366f1">
                            <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                          </Svg>
                        </TouchableOpacity>
                      </View>
                    </View>
                  ))}
                </View>
              );
            })
          ) : (
            <View className="p-8 items-center justify-center bg-white">
              <Text className="text-slate-500 text-center font-medium">
                No hay egresos para mostrar en este periodo.
              </Text>
              <Text className="text-slate-400 text-center text-sm mt-1">
                Intenta con otro mes o ano o agrega un nuevo egreso.
              </Text>
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  );
};

const formatDateShort = (dateString) => {
  if (!dateString) return "-";
  const [year, month, day] = dateString.split("-").map(Number);
  const monthName = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"][month - 1];
  return `${day} ${monthName}`;
};

