  "Abril",
  "Mayo",
  "Junio",
  "Julio",
  "Agosto",
  "Septiembre",
  "Octubre",
  "Noviembre",
  "Diciembre",
];

const TablaIngresos = ({ onEdit, refreshTrigger, dateFilter }) => {
  const [data, setData] = useState([]);
