  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const { data: ingresos, error } = await supabase
        .from("ingresos")
        .select("*")
        .order("fecha_ingreso", { ascending: false });

      if (error) throw error;
      setData(ingresos || []);
    } catch (error) {
      console.error("Error fetching ingresos:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
