  const handlePrintIngreso = async (ingreso) => {
    try {
      if (!ingreso) return;

      const logoConfig = await getTicketLogoDisplaySettings();
      const htmlContent = buildIngresoTicketHtml(
        ingreso,
        currencyFormatter,
        logoConfig,
      );

      setPrinting(true);

      if (Platform.OS === "web") {
        const printWindow = window.open("", "_blank", "width=400,height=700");
        if (!printWindow) {
          notifyError(
            "Se bloqueó la ventana emergente. Permite las ventanas emergentes para imprimir.",
          );
          setPrinting(false);
          return;
        }

        printWindow.document.write(htmlContent);
        printWindow.document.close();
        printWindow.onload = () => {
          printWindow.print();
          setPrinting(false);
        };
        return;
      }

      const { uri } = await Print.printToFileAsync({ html: htmlContent });
      await shareAsync(uri, {
        UTI: ".pdf",
        mimeType: "application/pdf",
        dialogTitle: `Ticket-Ingreso-${getIngresoFolio(ingreso)}.pdf`,
      });
    } catch (error) {
      console.error("Error al imprimir ticket de ingreso:", error);
      notifyError("No se pudo imprimir el ticket.");
    } finally {
      setPrinting(false);
    }
  };

  const handleDelete = async (ingreso) => {
    const ok = await confirm({
      title: "Eliminar ingreso",
      message: `Estas seguro de que deseas eliminar el ingreso "${ingreso.nombre_ingreso}"?`,
      confirmText: "Eliminar",
      type: "destructive",
    });
    if (!ok) return;

    try {
      const { error } = await supabase
        .from("ingresos")
        .delete()
        .eq("id_ingresos", ingreso.id_ingresos);
      if (error) throw error;
      await fetchData();
    } catch (error) {
      console.error("Error deleting ingreso:", error);
      notifyError("No se pudo eliminar el ingreso.");
    }
  };

  const filteredAndGroupedData = useMemo(() => {
    const now = new Date();
    let filtered = data;

    if (dateFilter) {
      filtered = filtered.filter((item) => {
        if (!item.fecha_ingreso) return false;
        const [year, month, day] = item.fecha_ingreso.split("-").map(Number);
        const itemDate = new Date(year, month - 1, day, 12, 0, 0);

        if (dateFilter === "last_month") {
          const oneMonthAgo = new Date(now);
          oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);
          oneMonthAgo.setHours(0, 0, 0, 0);
          return itemDate >= oneMonthAgo;
        }

        if (dateFilter === "3_months_ago") {
          const threeMonthsAgo = new Date(now);
          threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);
          threeMonthsAgo.setHours(0, 0, 0, 0);
          return itemDate >= threeMonthsAgo;
        }

        if (String(dateFilter).startsWith("year-")) {
          return itemDate.getFullYear() === Number(String(dateFilter).split("-")[1]);
        }

        return true;
      });
    }

    if (sortKey) {
      filtered = [...filtered].sort((a, b) => {
        let left = a[sortKey] ?? "";
        let right = b[sortKey] ?? "";
        if (typeof left === "string") left = left.toLowerCase();
        if (typeof right === "string") right = right.toLowerCase();
        if (left < right) return sortDir === "asc" ? -1 : 1;
        if (left > right) return sortDir === "asc" ? 1 : -1;
        return 0;
      });
    }

    const groups = {};
    filtered.forEach((item) => {
      if (!item.fecha_ingreso) return;
      const [year, month] = item.fecha_ingreso.split("-");
      const monthIndex = Number(month) - 1;
      const key = `${year}-${monthIndex}-${MONTH_NAMES[monthIndex]}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(item);
    });

    const keys = Object.keys(groups).sort((a, b) => {
      const [yearA, monthA] = a.split("-").map(Number);
      const [yearB, monthB] = b.split("-").map(Number);
      if (yearA !== yearB) return yearB - yearA;
      return monthB - monthA;
    });

    return { keys, data: groups };
  }, [data, dateFilter, sortDir, sortKey]);

  const onRefresh = async () => {
    setRefreshing(true);
    await fetchData();
    setRefreshing(false);
  };

  return (
    <View className="flex-1">
      <ScrollView
        contentContainerStyle={{ flexGrow: 1 }}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor="#6366f1" />
        }
      >
        <View className="rounded-xl overflow-hidden border border-slate-200 bg-white shadow-sm">
          <View className="bg-slate-100 border-b border-slate-200 flex-row">
            {ingresosHeaders.map((header) => (
              <TouchableOpacity
                key={header.key || header.title}
                style={{ flex: header.flex, alignItems: header.center ? "center" : "flex-start" }}
                className="py-3 px-3 flex-row"
                onPress={() => {
                  if (!header.key) return;
                  if (sortKey === header.key) {
                    setSortDir((current) => (current === "asc" ? "desc" : "asc"));
                  } else {
                    setSortKey(header.key);
                    setSortDir("asc");
                  }
                }}
                disabled={!header.key}
              >
                <Text className="text-slate-800 font-semibold text-xs uppercase tracking-wide">
                  {header.title}
                </Text>
              </TouchableOpacity>
            ))}
          </View>

          {loading ? (
            <View className="p-8 items-center justify-center bg-white">
              <ActivityIndicator size="large" color="#6366f1" />
              <Text className="text-slate-500 text-center font-medium mt-4">
                Cargando ingresos...
              </Text>
            </View>
          ) : filteredAndGroupedData.keys.length > 0 ? (
            filteredAndGroupedData.keys.map((key) => {
              const [year, , monthName] = key.split("-");
              const displayLabel =
                Number(year) === new Date().getFullYear() ? monthName : `${monthName} ${year}`;

              return (
                <View key={key}>
                  <View className="bg-indigo-600 py-3 px-4 flex-row items-center border-t border-indigo-700">
                    <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#ffffff">
                      <Path d="M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Z" />
                    </Svg>
                    <Text className="text-white font-bold text-lg ml-2">{displayLabel}</Text>
                  </View>

                  {filteredAndGroupedData.data[key].map((ingreso, index) => (
                    <View
                      key={ingreso.id_ingresos || index}
                      style={{
                        flexDirection: "row",
                        alignItems: "center",
                        borderTopWidth: 1,
                        borderTopColor: "#e2e8f0",
                        backgroundColor: index % 2 ? "#ffffff" : "#f8fafc",
                      }}
                    >
                      <Text style={{ flex: 4 }} className="p-3 text-slate-800" numberOfLines={1}>
                        {ingreso.nombre_ingreso}
                      </Text>
                      <Text style={{ flex: 5 }} className="p-3 text-slate-700" numberOfLines={1}>
                        {ingreso.desc_ingreso || "-"}
                      </Text>
                      <Text style={{ flex: 2.3 }} className="p-3 text-slate-600 text-center">
                        {formatDateShort(ingreso.fecha_ingreso)}
                      </Text>
                      <Text style={{ flex: 2.5 }} className="p-3 text-slate-800 font-medium text-center">
                        {currencyFormatter.format(ingreso.monto_ingreso || 0)}
                      </Text>
                      <View
                        style={{ flex: 1, flexDirection: "row", justifyContent: "center", gap: 12 }}
                        className="p-3"
                      >
                        <TouchableOpacity onPress={() => handleOpenReprint(ingreso)}>
                          <Svg height="22" viewBox="0 -960 960 960" width="22" fill="#475569">
                            <Path d="M640-640v-120H320v120h-80v-200h480v200h-80Zm-480 80h640-640Zm560 100q17 0 28.5-11.5T760-500q0-17-11.5-28.5T720-540q-17 0-28.5 11.5T680-500q0 17 11.5 28.5T720-460Zm-80 260v-160H320v160h320Zm80 80H240v-160H80v-240q0-51 35-85.5t85-34.5h560q51 0 85.5 34.5T880-520v240H720v160Zm80-240v-160q0-17-11.5-28.5T760-560H200q-17 0-28.5 11.5T160-520v160h80v-80h480v80h80Z" />
                          </Svg>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={() => onEdit(ingreso)}>
                          <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#6366f1">
                            <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                          </Svg>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={() => handleDelete(ingreso)}>
                          <Svg height="20" viewBox="0 -960 960 960" width="20" fill="#dc2626">
                            <Path d="M280-120q-33 0-56.5-23.5T200-200v-520h-40v-80h200v-40h240v40h200v80h-40v520q0 33-23.5 56.5T680-120H280Zm400-600H280v520h400v-520ZM360-280h80v-360h-80v360Zm160 0h80v-360h-80v360ZM280-720v520-520Z" />
                          </Svg>
                        </TouchableOpacity>
                      </View>
                    </View>
                  ))}
                </View>
              );
            })
          ) : (
            <View className="p-8 items-center justify-center bg-white">
              <Text className="text-slate-500 text-center font-medium">
                No hay ingresos registrados.
              </Text>
              <Text className="text-slate-400 text-center text-sm mt-1">
                Agrega un nuevo ingreso para comenzar.
              </Text>
            </View>
          )}
        </View>
      </ScrollView>

      <Modal
        animationType="fade"
        transparent={true}
        visible={reprintModalVisible}
        onRequestClose={() => setReprintModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Detalles de Ingreso</Text>
              <TouchableOpacity onPress={() => setReprintModalVisible(false)}>
                <Svg height="24" viewBox="0 -960 960 960" width="24" fill="#64748b">
                  <Path d="m256-200-56-56 224-224-224-224 56-56 224 224 224-224 56 56-224 224 224 224-56 56-224-224-224 224Z" />
                </Svg>
              </TouchableOpacity>
            </View>

            {selectedIngreso ? (
              <View style={{ gap: 16, alignItems: "center", alignSelf: "stretch" }}>
                <IngresoTicketVirtual
                  ingreso={selectedIngreso}
                  currencyFormatter={currencyFormatter}
                />

                <View style={styles.modalActions}>
                  <TouchableOpacity
                    onPress={() => setReprintModalVisible(false)}
                    style={styles.buttonCancel}
                  >
                    <Text style={styles.buttonCancelText}>Cerrar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    onPress={() => {
                      setReprintModalVisible(false);
                      handlePrintIngreso(selectedIngreso);
                    }}
                    style={[
                      styles.buttonConfirm,
                      printing ? { opacity: 0.7 } : null,
                    ]}
                    disabled={printing}
                  >
                    <View style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
                      <Svg height="16" viewBox="0 -960 960 960" width="16" fill="#ffffff">
                        <Path d="M640-640v-120H320v120h-80v-200h480v200h-80Zm-480 80h640-640Zm560 100q17 0 28.5-11.5T760-500q0-17-11.5-28.5T720-540q-17 0-28.5 11.5T680-500q0 17 11.5 28.5T720-460Zm-80 260v-160H320v160h320Zm80 80H240v-160H80v-240q0-51 35-85.5t85-34.5h560q51 0 85.5 34.5T880-520v240H720v160Zm80-240v-160q0-17-11.5-28.5T760-560H200q-17 0-28.5 11.5T160-520v160h80v-80h480v80h80Z" />
                      </Svg>
                      <Text style={styles.buttonConfirmText}>
                        {printing ? "Imprimiendo..." : "Imprimir"}
                      </Text>
                    </View>
                  </TouchableOpacity>
                </View>
              </View>
            ) : null}
          </View>
        </View>
      </Modal>
    </View>
  );
};

const formatDateShort = (dateString) => {
  if (!dateString) return "-";
  const [, month, day] = dateString.split("-").map(Number);
  const monthName = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"][month - 1];
  return `${day} ${monthName}`;
};

const getIngresoFolio = (ingreso = {}) =>
  `ING-${String(ingreso.id_ingresos || "0000").padStart(4, "0")}`;

