      const pieChartSVG = generatePieChartSVG(
        totalIngresosAnual,
        totalEgresosAnual,
      );

      // Función para generar gráfica de pastel de estudiantes por mes
      const generateStudentsPieChartSVG = (monthlyData) => {
        const width = 600;
        const height = 450;
        const centerX = width / 2;
        const centerY = height / 2 - 20;
        const radius = 120;

        // Obtener datos hasta el mes seleccionado
        const dataWithLabels = monthlyData
          .slice(1, reportMonth + 1)
          .map((item, index) => ({
            label: item.label,
            value: item.value,
            month: index + 1,
          }))
          .filter((item) => item.value > 0); // Solo meses con estudiantes

        const total = dataWithLabels.reduce((sum, item) => sum + item.value, 0);

        if (total === 0) {
          return `
            <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
              <rect width="${width}" height="${height}" fill="#ffffff"/>
              <text 
                x="${centerX}" 
                y="${centerY}" 
                text-anchor="middle" 
                font-size="14" 
                fill="#64748b"
              >
                No hay datos de estudiantes registrados
              </text>
            </svg>
          `;
        }

        // Colores para cada mes
        const colors = [
          "#6366f1",
          "#8b5cf6",
          "#a855f7",
          "#d946ef",
          "#ec4899",
          "#f43f5e",
          "#ef4444",
          "#f97316",
          "#f59e0b",
          "#eab308",
          "#84cc16",
          "#22c55e",
        ];

        let currentAngle = -Math.PI / 2; // Empezar desde arriba (-90 grados)
        let paths = "";
        let legends = "";

        dataWithLabels.forEach((item, index) => {
          const percentage = (item.value / total) * 100;
          const sweepAngle = (item.value / total) * 2 * Math.PI; // Ángulo en radianes
          const color = colors[index % colors.length];

          // Caso especial: si es 100%, dibujar un círculo completo
          if (percentage >= 99.9) {
            paths += `
              <circle
                cx="${centerX}"
                cy="${centerY}"
                r="${radius}"
                fill="${color}"
                stroke="#ffffff"
                stroke-width="2"
              />
            `;
          } else {
            // Punto inicial del arco
            const x1 = centerX + radius * Math.cos(currentAngle);
            const y1 = centerY + radius * Math.sin(currentAngle);

            // Punto final del arco
            const x2 = centerX + radius * Math.cos(currentAngle + sweepAngle);
            const y2 = centerY + radius * Math.sin(currentAngle + sweepAngle);

            // Flag para arcos grandes (más de 180 grados)
            const largeArcFlag = sweepAngle > Math.PI ? 1 : 0;

            // Crear path del segmento
            paths += `
              <path
                d="M ${centerX},${centerY}
                   L ${x1},${y1}
                   A ${radius},${radius} 0 ${largeArcFlag},1 ${x2},${y2}
                   Z"
                fill="${color}"
                stroke="#ffffff"
                stroke-width="2"
              />
            `;
          }

          // Crear leyenda (dos columnas)
          const legendX = index < 6 ? 50 : 320;
          const legendY = 280 + (index % 6) * 25;

          legends += `
            <rect x="${legendX}" y="${legendY}" width="15" height="15" fill="${color}"/>
            <text x="${legendX + 20}" y="${legendY + 12}" font-size="11" fill="#1e293b">
              ${item.label}: ${item.value} (${percentage.toFixed(1)}%)
            </text>
          `;

          currentAngle += sweepAngle;
        });

        return `
          <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <!-- Fondo -->
            <rect width="${width}" height="${height}" fill="#ffffff"/>
            
            <!-- Título -->
            <text 
              x="${centerX}" 
              y="30" 
              text-anchor="middle" 
              font-size="16" 
              font-weight="bold" 
              fill="#1e293b"
            >
              Distribución de Estudiantes
            </text>
            
            <!-- Segmentos del pastel -->
            ${paths}
            
            <!-- Círculo central con total -->
            <circle 
              cx="${centerX}" 
              cy="${centerY}" 
              r="50" 
              fill="#ffffff"
              fill-opacity="0.75"
              stroke="#e2e8f0"
              stroke-width="2"
            />
            <text 
              x="${centerX}" 
              y="${centerY - 5}" 
              text-anchor="middle" 
              font-size="12" 
              fill="#64748b"
            >
              Total
            </text>
            <text 
              x="${centerX}" 
              y="${centerY + 15}" 
              text-anchor="middle" 
              font-size="20" 
              font-weight="bold" 
              fill="#6F09EA"
            >
              ${total}
            </text>
            
            <!-- Leyenda -->
            ${legends}
          </svg>
        `;
      };

      // Generar gráfica de pastel de estudiantes
      const studentsPieChartSVG =
        generateStudentsPieChartSVG(monthlyEstudiantes);

      const html = `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <style>
            body {
              font-family: Arial, sans-serif;
              padding: 20px;
              color: #1e293b;
            }
            .header {
              text-align: center;
              margin-bottom: 30px;
              border-bottom: 3px solid #6F09EA;
              padding-bottom: 15px;
            }
            .header h1 {
              color: #6F09EA;
              margin: 0 0 5px 0;
              font-size: 28px;
            }
            .header p {
              margin: 3px 0;
              color: #64748b;
              font-size: 12px;
            }
            .balance-section {
              display: flex;
              justify-content: space-between;
              margin-bottom: 25px;
              gap: 15px;
            }
            .balance-card {
              flex: 1;
              padding: 15px;
              border-radius: 8px;
              border: 2px solid;
            }
            .balance-card.positive {
              background-color: #f0fdf4;
              border-color: #86efac;
            }
            .balance-card.negative {
              background-color: #fef2f2;
              border-color: #fca5a5;
            }
            .balance-card h3 {
              margin: 0 0 8px 0;
              font-size: 14px;
              color: #64748b;
            }
            .balance-card .amount {
              font-size: 24px;
              font-weight: bold;
              margin: 0;
            }
            .balance-card.positive .amount {
              color: #16a34a;
            }
            .balance-card.negative .amount {
              color: #dc2626;
            }
            .section {
              margin-bottom: 25px;
              page-break-inside: avoid;
            }
            .section h2 {
              color: #6F09EA;
              font-size: 18px;
              margin-bottom: 10px;
              border-bottom: 2px solid #e2e8f0;
              padding-bottom: 5px;
            }
            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 10px;
              page-break-inside: avoid;
            }
            th {
              background-color: #f1f5f9;
              padding: 10px;
              text-align: left;
              font-size: 12px;
              color: #475569;
              border-bottom: 2px solid #cbd5e1;
            }
            td {
              font-size: 12px;
              color: #1e293b;
            }
            .footer {
              margin-top: 30px;
              text-align: center;
              font-size: 10px;
              color: #94a3b8;
              border-top: 1px solid #e2e8f0;
              padding-top: 15px;
            }
            .summary {
              background-color: #f8fafc;
              padding: 15px;
              border-radius: 8px;
              margin-bottom: 20px;
            }
            .summary-row {
              display: flex;
              justify-content: space-between;
              padding: 5px 0;
              font-size: 14px;
            }
            .summary-row.total {
              font-weight: bold;
              font-size: 16px;
              border-top: 2px solid #cbd5e1;
              padding-top: 10px;
              margin-top: 5px;
            }
            .chart-container {
              margin: 20px 0;
              padding: 15px;
              background-color: #ffffff;
              border-radius: 8px;
              border: 1px solid #e2e8f0;
              page-break-inside: avoid;
            }
            .chart-container canvas {
              max-height: 300px;
            }
          </style>
        </head>
        <body>
          <div class="header">
            <p style="margin: 0; font-size: 18px; font-weight: bold; color: #6F09EA;">MQerKAcademy</p>
            <p style="margin: 0; font-size: 12px; color: #64748b; margin-bottom: 10px;">Sistema Fenix Retail</p>
            <h1>Reporte Financiero ${reportYear}</h1>
            <p>Generado el ${currentDate}</p>
            <p>Período: Enero - ${currentMonthName} ${reportYear}</p>
          </div>
          
          <div class="balance-section">
            <div class="balance-card ${balanceAnual >= 0 ? "positive" : "negative"}">
              <h3>Balance Total ${reportYear}</h3>
              <p class="amount">${currencyFormatter.format(balanceAnual)}</p>
            </div>
            <div class="balance-card ${balanceMesActual >= 0 ? "positive" : "negative"}">
              <h3>Balance ${currentMonthName}</h3>
              <p class="amount">${currencyFormatter.format(balanceMesActual)}</p>
            </div>
          </div>
          
          <div class="summary">
            <div class="summary-row">
              <span>Total Ingresos ${reportYear}:</span>
              <span>${currencyFormatter.format(totalIngresosAnual)}</span>
            </div>
            <div class="summary-row">
              <span>Total Egresos ${reportYear}:</span>
              <span>${currencyFormatter.format(totalEgresosAnual)}</span>
            </div>
            <div class="summary-row total">
              <span>Balance Anual:</span>
              <span style="color: ${balanceAnual >= 0 ? "#16a34a" : "#dc2626"}">
                ${currencyFormatter.format(balanceAnual)}
              </span>
            </div>
          </div>
          
          <div class="summary">
            <div class="summary-row">
              <span>Ingresos ${currentMonthName}:</span>
              <span>${currencyFormatter.format(ingresosMesActual)}</span>
            </div>
            <div class="summary-row">
              <span>Egresos ${currentMonthName}:</span>
              <span>${currencyFormatter.format(egresosMesActual)}</span>
            </div>
            <div class="summary-row total">
              <span>Balance ${currentMonthName}:</span>
              <span style="color: ${balanceMesActual >= 0 ? "#16a34a" : "#dc2626"}">
                ${currencyFormatter.format(balanceMesActual)}
              </span>
            </div>
          </div>
          
          <!-- Gráficas -->
          <div class="section">
            <h2>Gráficas Comparativas</h2>
            <div class="chart-container">
              ${ingresosSVG}
            </div>
            <div class="chart-container">
              ${egresosSVG}
            </div>
            <div class="chart-container">
              ${estudiantesSVG}
            </div>
            <div class="chart-container" style="display: flex; justify-content: center;">
              ${pieChartSVG}
            </div>
            <div class="chart-container" style="display: flex; justify-content: center;">
              ${studentsPieChartSVG}
            </div>
          </div>
          
          <div class="section">
            <h2>Desglose de Ingresos ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Monto</th>
                </tr>
              </thead>
              <tbody>
                ${ingresosTable}
              </tbody>
            </table>
          </div>
          
          <div class="section">
            <h2>Desglose de Egresos ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Monto</th>
                </tr>
              </thead>
              <tbody>
                ${egresosTable}
              </tbody>
            </table>
          </div>
          
          <div class="section">
            <h2>Estudiantes Registrados ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Cantidad</th>
                </tr>
              </thead>
              <tbody>
                ${estudiantesTable}
              </tbody>
            </table>
            <div style="margin-top: 15px; padding: 10px; background-color: #f1f5f9; border-radius: 6px;">
              <div style="display: flex; justify-content: space-between; font-weight: bold; color: #6F09EA;">
                <span>Total de Estudiantes Registrados:</span>
                <span>${totalEstudiantesAnual}</span>
              </div>
            </div>
          </div>
          
          <div class="footer">
            <p style="font-weight: bold; color: #6F09EA; margin-bottom: 5px;">MQerKAcademy</p>
            <p>Reporte generado automáticamente por Fenix Retail</p>
            <p>© ${new Date().getFullYear()} MQerKAcademy - Todos los derechos reservados</p>
          </div>
        </body>
        </html>
      `;

      // Generar nombre del archivo PDF
      const yearShort = reportYear.toString().slice(-2); // Últimos 2 dígitos del año
      const monthNameShort = currentMonthName.substring(0, 3); // Primeras 3 letras del mes
      const pdfFileName = `Reporte-FenixRetail_Ene-${monthNameShort}-${yearShort}.pdf`;

      const { uri } = await Print.printToFileAsync({
        html: html,
      });

      // Renombrar el archivo
      const newUri = `${FileSystem.cacheDirectory}${pdfFileName}`;
      await FileSystem.moveAsync({
        from: uri,
        to: newUri,
      });

      console.log("Reporte PDF generado en:", newUri);
      await shareAsync(newUri, {
        UTI: ".pdf",
        mimeType: "application/pdf",
        dialogTitle: pdfFileName,
      });
    } catch (error) {
      console.error("Error al generar reporte PDF:", error);
      notifyError("No se pudo generar el reporte: " + error.message);
    }
  };

  return (
    <View className="flex-1 bg-slate-50">
      <View className="p-4 pb-2">
        <View>
          {/* Header compacto con título, selectores y botón */}
          <View className="flex-row justify-between items-center gap-3 mb-4">
            <Text className="text-2xl font-bold text-slate-800">
              Reporte Anual
            </Text>

            <View className="flex-row gap-2 items-center">
              {/* Selector de Mes */}
              <View style={{ width: 130 }}>
                <Dropdown
                  style={styles_charts.dropdownIngresos}
                  data={monthOptions}
                  labelField="label"
                  valueField="value"
                  placeholder="Mes"
                  value={selectedMonth}
                  onChange={(item) => setSelectedMonth(item.value)}
                />
              </View>
              {/* Selector de Año */}
              <View style={{ width: 100 }}>
                <Dropdown
                  style={[
                    styles_charts.dropdownIngresos,
                    loadingYears && { opacity: 0.5 },
                  ]}
                  containerStyle={loadingYears && { opacity: 0.5 }}
                  data={availableYears}
                  labelField="label"
                  valueField="value"
                  placeholder={loadingYears ? "Año" : "Año"}
                  value={year}
                  onChange={(item) => setYear(item.value)}
                  disable={loadingYears}
                />
              </View>

              {/* Botón PDF */}
              <TouchableOpacity
                onPress={generateReportPDF}
                className="bg-green-600 px-3 py-2 rounded-lg flex-row items-center gap-2"
                disabled={loading}
                style={{ opacity: loading ? 0.5 : 1 }}
              >
                <Svg height="16" width="16" viewBox="0 0 512 512">
                  <Path
                    fill="#ffffff"
                    d="M378.413,0H208.297h-13.182L185.8,9.314L57.02,138.102l-9.314,9.314v13.176v265.514c0,47.36,38.528,85.895,85.896,85.895h244.811c47.353,0,85.881-38.535,85.881-85.895V85.896C464.294,38.528,425.766,0,378.413,0z M432.497,426.105c0,29.877-24.214,54.091-54.084,54.091H133.602c-29.884,0-54.098-24.214-54.098-54.091V160.591h83.716c24.885,0,45.077-20.178,45.077-45.07V31.804h170.116c29.87,0,54.084,24.214,54.084,54.092V426.105z"
                  />
                  <Path
                    fill="#ffffff"
                    d="M171.947,252.785h-28.529c-5.432,0-8.686,3.533-8.686,8.825v73.754c0,6.388,4.204,10.599,10.041,10.599c5.711,0,9.914-4.21,9.914-10.599v-22.406c0-0.545,0.279-0.817,0.824-0.817h16.436c20.095,0,32.188-12.226,32.188-29.612C204.136,264.871,192.182,252.785,171.947,252.785z M170.719,294.888h-15.208c-0.545,0-0.824-0.272-0.824-0.81v-23.23c0-0.545,0.279-0.816,0.824-0.816h15.208c8.42,0,13.447,5.027,13.447,12.498C184.167,290,179.139,294.888,170.719,294.888z"
                  />
                  <Path
                    fill="#ffffff"
                    d="M250.191,252.785h-21.868c-5.432,0-8.686,3.533-8.686,8.825v74.843c0,5.3,3.253,8.693,8.686,8.693h21.868c19.69,0,31.923-6.249,36.81-21.324c1.76-5.3,2.723-11.681,2.723-24.857c0-13.175-0.964-19.557-2.723-24.856C282.113,259.034,269.881,252.785,250.191,252.785z M267.856,316.896c-2.318,7.331-8.965,10.459-18.21,10.459h-9.23c-0.545,0-0.824-0.272-0.824-0.816v-55.146c0-0.545,0.279-0.817,0.824-0.817h9.23c9.245,0,15.892,3.128,18.21,10.46c0.95,3.128,1.62,8.56,1.62,17.93C269.476,308.336,268.805,313.768,267.856,316.896z"
                  />
                  <Path
                    fill="#ffffff"
                    d="M361.167,252.785h-44.812c-5.432,0-8.7,3.533-8.7,8.825v73.754c0,6.388,4.218,10.599,10.055,10.599c5.697,0,9.914-4.21,9.914-10.599v-26.351c0-0.538,0.265-0.81,0.81-0.81h26.086c5.837,0,9.23-3.532,9.23-8.56c0-5.028-3.393-8.553-9.23-8.553h-26.086c-0.545,0-0.81-0.272-0.81-0.817v-19.425c0-0.545,0.265-0.816,0.81-0.816h32.733c5.572,0,9.245-3.666,9.245-8.553C370.411,256.45,366.738,252.785,361.167,252.785z"
                  />
                </Svg>
                <Text className="text-white font-semibold text-sm">
                  Reporte
                </Text>
              </TouchableOpacity>

              {/* Botón Hoy */}
              <TouchableOpacity
                onPress={() => {
                  const currentYear = new Date().getFullYear();
                  const currentMonth = new Date().getMonth() + 1;
                  setYear(currentYear);
                  setSelectedMonth(currentMonth);
                }}
                className="bg-indigo-600 px-3 py-2 rounded-lg"
                disabled={isCurrentMonthAndYear}
                style={{ opacity: isCurrentMonthAndYear ? 0.5 : 1 }}
              >
                <Text className="text-white font-semibold text-sm">Hoy</Text>
              </TouchableOpacity>
            </View>
          </View>

          {/* Balance Cards */}
          <View className={`gap-3 ${isPortrait ? "flex-col" : "flex-row"}`}>
            {loading ? (
              // Skeleton mientras carga
              <>
                <View
                  className={`${isPortrait ? "" : "flex-1"} rounded-xl p-4 border border-slate-200 bg-slate-50`}
                >
                  <Text className="text-sm text-slate-400 mb-1">
                    Balance Total {year}
                  </Text>
                  <View className="flex-row items-center gap-2">
                    <ActivityIndicator size="small" color="#64748b" />
                    <Text className="text-2xl font-extrabold text-slate-300">
                      Cargando...
                    </Text>
                  </View>
                </View>

                {year === new Date().getFullYear() && (
                  <View
                    className={`${isPortrait ? "" : "flex-1"} rounded-xl p-4 border border-slate-200 bg-slate-50`}
                  >
                    <Text className="text-sm text-slate-400 mb-1">
                      Balance{" "}
                      {new Date()
                        .toLocaleString("es-MX", { month: "long" })
                        .charAt(0)
                        .toUpperCase() +
                        new Date()
                          .toLocaleString("es-MX", { month: "long" })
                          .slice(1)}
                    </Text>
                    <View className="flex-row items-center gap-2">
                      <ActivityIndicator size="small" color="#64748b" />
                      <Text className="text-2xl font-extrabold text-slate-300">
                        Cargando...
                      </Text>
                    </View>
                  </View>
                )}
              </>
            ) : (
              // Datos cargados
              <>
                {/* Balance Mes Seleccionado */}
                <View
                  className={`${isPortrait ? "" : "flex-1"} rounded-xl p-4 border ${balanceMesSeleccionado >= 0
                      ? "bg-blue-50 border-blue-200"
                      : "bg-orange-50 border-orange-200"
                    }`}
                >
                  <Text className="text-sm text-slate-600 mb-1">
                    Balance{" "}
                    {monthOptions.find((m) => m.value === selectedMonth)?.label}
                    {isCurrentMonthAndYear && " (Mes Actual)"}
                  </Text>
                  <Text
                    className={`text-3xl font-extrabold ${balanceMesSeleccionado >= 0
                        ? "text-blue-600"
                        : "text-orange-600"
                      }`}
                  >
                    {currencyFormatter.format(balanceMesSeleccionado)}
                  </Text>
                </View>
                {/* Balance Total */}
                <View
                  className={`${isPortrait ? "" : "flex-1"} rounded-xl p-4 border ${balance >= 0
                      ? "bg-green-50 border-green-200"
                      : "bg-red-50 border-red-200"
                    }`}
                >
                  <Text className="text-sm text-slate-600 mb-1">
                    Balance Total {year}
                  </Text>
                  <Text
                    className={`text-3xl font-extrabold ${balance >= 0 ? "text-green-600" : "text-red-600"
                      }`}
                  >
                    {currencyFormatter.format(balance)}
                  </Text>
                </View>
              </>
            )}
          </View>
        </View>
      </View>

      {/* Tab Navigator fuera del ScrollView */}
      {loading ? (
        <View className="flex-1 justify-center items-center">
          <ActivityIndicator size="large" color="#6F09EA" />
          <Text className="text-slate-500 mt-4 text-base">
            Cargando reportes...
          </Text>
        </View>
      ) : (
        <Tab.Navigator
          screenOptions={{
            tabBarActiveTintColor: "#6F09EA",
            tabBarInactiveTintColor: "#64748b",
            tabBarLabelStyle: {
              fontSize: 14,
              fontWeight: "bold",
              textTransform: "none",
            },
            tabBarStyle: {
              backgroundColor: "#ffffff",
              borderTopWidth: 2,
              borderTopColor: "#e2e8f0",
            },
            tabBarIndicatorStyle: {
              backgroundColor: "#6F09EA",
              height: 3,
            },
          }}
        >
          {/* Tab de Finanzas */}
          <Tab.Screen name="Finanzas">
            {() => (
              <ScrollView
                className="flex-1 bg-white"
                contentContainerStyle={{ paddingInline: 16, paddingBlock: 6 }}
                refreshControl={
                  <RefreshControl
                    refreshing={loading}
                    onRefresh={handleRefresh}
                    tintColor="#6F09EA"
                  />
                }
              >
                <View
                  className={`${isPortrait
                      ? "flex-col justify-center items-stretch gap-0"
                      : "flex-row flex-wrap justify-center items-center gap-6"
                    }`}
                >
                  <ChartCard
                    title="Ingresos"
                    total={totalIngresos}
                    data={chartIngresos}
                    unit="$"
                    isPortrait={isPortrait}
