                  />
                </View>
              </ScrollView>
            )}
          </Tab.Screen>

          {/* Tab de Estudiantes */}
          <Tab.Screen name="Estudiantes">
            {() => (
              <ScrollView
                className="flex-1 bg-white"
                contentContainerStyle={{ paddingInline: 16, paddingBlock: 6 }}
