                  >
                    <ChartCard
                      title="Estudiantes Registrados"
                      total={totalEstudiantes}
                      data={chartEstudiantes}
                      unit=""
                      isPortrait={isPortrait}
                      loading={loading}
                      totalMesActual={totalEstudiantesMesSeleccionado}
                      monthName={
                        monthOptions.find((m) => m.value === selectedMonth)
                          ?.label
