        ${ticketBranding.addressLine}
      </div>
      <div class="text-center" style="font-size: 9px; color: #334155;">
        ${ticketBranding.locationLine}
      </div>
      <div class="text-center" style="font-size: 9px; color: #334155;">
        ${ticketBranding.contactLine}
      </div>
      <div class="text-center" style="font-size: 9px; color: #475569; margin-top: 4px;">
        ${today.toLocaleString("es-MX")}
      </div>

      <div class="dashed-line"></div>

      <!-- Folio y Referencia -->
      <div style="font-size: 10px; color: #334155;">
        <div><span class="bold">Folio del Ticket:</span> ${folio}</div>
        <div><span class="bold">Token/Ref:</span> ${txn.referencia || "Sin referencia"}</div>
      </div>

      <div class="dashed-line"></div>

      <!-- Cliente -->
      <div style="font-size: 10px; color: #334155;">
        <div class="bold" style="font-size: 9px; color: #475569; margin-bottom: 2px;">CLIENTE</div>
        <div class="bold" style="color: #000000; font-size: 11px;">${alumno.nombre_alumno || "No especificado"}</div>
        <div>${alumno.direccion_alumno || "No especificada"}</div>
        <div>Grupo: ${txn.grupo_alumno || alumno.grupo || "No especificado"}</div>
      </div>

      <div class="dashed-line"></div>

      <!-- Detalles -->
      <div style="font-size: 10px; color: #334155;">
        <div class="bold" style="font-size: 9px; color: #475569; margin-bottom: 2px;">DETALLES DE CURSO</div>
        <div class="flex-row">
          <span style="flex: 1; margin-right: 8px;">${curso.nombre_curso || "Sin curso"}</span>
          <span class="bold">${currencyFormatter.format(total)}</span>
        </div>
      </div>

      <div class="dashed-line"></div>

      <!-- Desglose de Pagos -->
      <div style="font-size: 10.5px; color: #334155;">
        <div class="flex-row">
          <span>Anticipo:</span>
          <span style="font-weight: 600;">- ${currencyFormatter.format(anticipo)}</span>
        </div>
        ${anticipo > 0 ? `
        <div class="flex-row" style="color: #ef4444;">
          <span class="bold">Pendiente:</span>
          <span class="bold">${currencyFormatter.format(pendiente)}</span>
        </div>` : ""}
        <div class="flex-row" style="margin-top: 4px; font-size: 11.5px;">
          <span class="bold">Total a Pagar:</span>
          <span class="bold" style="color: #6F09EA;">${currencyFormatter.format(total)}</span>
        </div>
      </div>

      <div class="dashed-line"></div>

      <!-- Términos e información del Ticket -->
      <div class="text-center" style="font-size: 9px; display: flex; flex-direction: column; gap: 3px;">
        <div class="bold">*CONSERVE ESTE COMPROBANTE*</div>
        <div class="bold" style="color: #334155;">PAGO REALIZADO CON EXITO</div>
        <div style="font-size: 7.5px; color: #475569; line-height: 10px; margin: 2px 0;">
          NO HAY DEVOLUCION DEL PAGO POR CUALQUIER SERVICIO PRESTADO EN NUESTRA INSTITUCIÓN
