import React, { useState, useMemo } from "react";
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  ActivityIndicator,
  Pressable,
  StyleSheet,
  RefreshControl,
} from "react-native";
import Svg, { Path } from "react-native-svg";

const TablaVentasPendientes = ({
  data,
  query,
  isRefetching,
  onRefresh,
  onReprint,
  onRowClick, // Nueva prop
  selectedYear, // Año seleccionado para filtrar
}) => {
  const [sortKey, setSortKey] = useState("id_transaction");
  const [sortDir, setSortDir] = useState("desc");

  const currencyFormatter = new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  });

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const arr = data.filter((r) => {
      // Filtrar por año si está definido
      if (selectedYear && r.fecha_transaction) {
        // Parsear año directamente del string para evitar timezone offsets
        const dateStr = r.fecha_transaction.split("T")[0]; // "YYYY-MM-DD"
        const [yearStr] = dateStr.split("-");
        const transactionYear = parseInt(yearStr, 10);
        if (transactionYear !== selectedYear) return false;
      }

      if (!q) return true;

      // Búsqueda por nombre del alumno
      if (
        String(r.nombre_alumno || "")
          .toLowerCase()
          .includes(q)
      )
        return true;

      // Búsqueda por nombre del curso
      if (
        String(r.nombre_curso || "")
          .toLowerCase()
          .includes(q)
      )
        return true;

      // Búsqueda mejorada por grupo (matutino, vespertino, etc.)
      const grupoStr = String(r.grupo || "").toLowerCase();
      if (grupoStr.includes(q)) return true;

      // Búsqueda por monto pendiente (número exacto o parcial)
      if (String(r.monto_pendiente || "").includes(q)) return true;

      // Búsqueda por fecha en múltiples formatos
      if (r.fecha_transaction) {
        const dateStr = r.fecha_transaction.split("T")[0]; // "YYYY-MM-DD"
        const [year, month, day] = dateStr.split("-");

        // Nombres de meses completos y abreviados
        const monthNames = [
          "enero",
          "febrero",
          "marzo",
          "abril",
          "mayo",
          "junio",
          "julio",
          "agosto",
          "septiembre",
          "octubre",
          "noviembre",
          "diciembre",
        ];
        const monthNamesShort = [
          "ene",
          "feb",
          "mar",
          "abr",
          "may",
          "jun",
          "jul",
          "ago",
          "sep",
          "oct",
          "nov",
          "dic",
        ];
        const monthIndex = parseInt(month, 10) - 1;
        const monthName = monthNames[monthIndex] || "";
        const monthNameShort = monthNamesShort[monthIndex] || "";

        // Formato ISO: "2024-12-15"
        if (dateStr.includes(q)) return true;

        // Formato DD/MM/YYYY: "15/12/2024"
        const formatDDMMYYYY = `${day}/${month}/${year}`;
        if (formatDDMMYYYY.includes(q)) return true;

        // Formato DD-MM-YYYY: "15-12-2024"
        const formatDDMMYYYY2 = `${day}-${month}-${year}`;
        if (formatDDMMYYYY2.includes(q)) return true;

        // Búsqueda por día, mes o año individual
        if (day.includes(q) || month.includes(q) || year.includes(q))
          return true;

        // Búsqueda por nombre del mes
        if (monthName.includes(q)) return true;

        // Búsqueda por nombre del mes abreviado
        if (monthNameShort.includes(q)) return true;

        // Formatos naturales: "12 de diciembre", "12 diciembre", "12 dic", "12 de dic"
        const dayNum = parseInt(day, 10); // Sin ceros a la izquierda

        // "12 de diciembre", "12 de dic"
        if (
          q.includes(`${dayNum} de ${monthName}`) ||
          q.includes(`${dayNum} de ${monthNameShort}`)
        )
          return true;

        // "12 diciembre", "12 dic"
        if (
          q.includes(`${dayNum} ${monthName}`) ||
          q.includes(`${dayNum} ${monthNameShort}`)
        )
          return true;

        // "diciembre 12", "dic 12"
        if (
          q.includes(`${monthName} ${dayNum}`) ||
          q.includes(`${monthNameShort} ${dayNum}`)
        )
          return true;

        // Construir las variantes de fecha para comparar
        const dateVariants = [
          `${dayNum} de ${monthName}`, // "12 de diciembre"
          `${dayNum} ${monthName}`, // "12 diciembre"
          `${dayNum} de ${monthNameShort}`, // "12 de dic"
          `${dayNum} ${monthNameShort}`, // "12 dic"
          `${monthName} ${dayNum}`, // "diciembre 12"
          `${monthNameShort} ${dayNum}`, // "dic 12"
          `${day} de ${monthName}`, // "12 de diciembre" (con cero)
          `${day} ${monthName}`, // "12 diciembre" (con cero)
          `${day} de ${monthNameShort}`, // "12 de dic" (con cero)
          `${day} ${monthNameShort}`, // "12 dic" (con cero)
        ];

        // Verificar si alguna variante coincide
        if (dateVariants.some((variant) => variant.includes(q))) return true;
      }

      return false;
    });
    const sorted = [...arr].sort((a, b) => {
      let va = a[sortKey] ?? "";
      let vb = b[sortKey] ?? "";
      if (typeof va === "string") va = va.toLowerCase();
      if (typeof vb === "string") vb = vb.toLowerCase();

      // Comparación principal por la columna seleccionada
      if (va < vb) return sortDir === "asc" ? -1 : 1;
      if (va > vb) return sortDir === "asc" ? 1 : -1;

      // Si estamos ordenando por monto_pendiente, usar fecha como criterio secundario
      if (sortKey === "monto_pendiente") {
        const fechaA = a.fecha_transaction ?? "";
        const fechaB = b.fecha_transaction ?? "";

        if (fechaA !== fechaB) {
          // Ordenar por fecha según la dirección del sort principal
          if (sortDir === "asc") {
            return fechaA.localeCompare(fechaB); // Ascendente: fechas antiguas primero
          } else {
            return fechaB.localeCompare(fechaA); // Descendente: fechas recientes primero
          }
        }

        // Si las fechas también son iguales, usar id_transaccion como tercer criterio
        const idA = a.id_transaccion ?? 0;
        const idB = b.id_transaccion ?? 0;
        return sortDir === "asc" ? idA - idB : idB - idA;
      }

      // Para otras columnas, usar fecha como criterio secundario
      const fechaA = a.fecha_transaction ?? "";
      const fechaB = b.fecha_transaction ?? "";

      if (fechaA !== fechaB) {
        // Ordenar por fecha según la dirección del sort principal
        if (sortDir === "asc") {
          return fechaA.localeCompare(fechaB); // Ascendente: fechas antiguas primero
        } else {
          return fechaB.localeCompare(fechaA); // Descendente: fechas recientes primero
        }
      }

      // Si las fechas también son iguales, usar id_transaccion como criterio terciario
      const idA = a.id_transaccion ?? 0;
      const idB = b.id_transaccion ?? 0;
      // Ordenar por ID según la dirección del sort principal
      return sortDir === "asc" ? idA - idB : idB - idA;
    });
    return sorted;
  }, [data, query, sortKey, sortDir, selectedYear]);

  // Agrupar por año o por mes según el filtro seleccionado
  const groupedData = useMemo(() => {
    const MONTH_NAMES = [
      "Enero",
      "Febrero",
      "Marzo",
      "Abril",
      "Mayo",
      "Junio",
      "Julio",
      "Agosto",
      "Septiembre",
      "Octubre",
      "Noviembre",
      "Diciembre",
    ];

    if (selectedYear === null) {
      // Agrupar por año cuando se selecciona "Todos"
      const groups = filtered.reduce((acc, alumno) => {
        let year = "Sin fecha";
        if (alumno.fecha_transaction) {
          const dateStr = alumno.fecha_transaction.split("T")[0];
          year = String(dateStr.split("-")[0]);
        }

        if (!acc[year]) acc[year] = [];
        acc[year].push(alumno);
        return acc;
      }, {});

      const sortedYears = Object.keys(groups).sort((a, b) => {
        if (a === "Sin fecha") return 1;
        if (b === "Sin fecha") return -1;
        return b - a;
      });

      return { grouped: true, type: "year", keys: sortedYears, data: groups };
    } else {
      // Agrupar por mes cuando se selecciona un año específico
      const groups = filtered.reduce((acc, alumno) => {
        if (alumno.fecha_transaction) {
          const dateStr = alumno.fecha_transaction.split("T")[0]; // "YYYY-MM-DD"
          const [year, month, day] = dateStr.split("-").map(Number);

          const mesIndex = month - 1; // 0-indexed
          const mes = MONTH_NAMES[mesIndex] || "Desconocido";
          const mesNumero = mesIndex;

          const key = `${mesNumero}-${mes}`;
          if (!acc[key]) acc[key] = [];
          acc[key].push(alumno);
        }
        return acc;
      }, {});

      const sortedMonths = Object.keys(groups).sort((a, b) => {
        const numA = parseInt(a.split("-")[0]);
        const numB = parseInt(b.split("-")[0]);
        return numB - numA;
      });

      return { grouped: true, type: "month", keys: sortedMonths, data: groups };
    }
  }, [filtered, selectedYear]);

  const SortHeader = ({ label, k, flex = 1, center }) => (
    <Pressable
      onPress={() => {
        if (!k) return;
        setSortKey(k);
        setSortDir((d) =>
          sortKey === k ? (d === "asc" ? "desc" : "asc") : "asc",
        );
      }}
      className="py-3 px-3"
      style={{ flex, alignItems: center ? "center" : "flex-start" }}
      android_ripple={{ color: "rgba(0,0,0,0.05)" }}
    >
      <View className="flex-row items-center gap-1">
        <Text className="text-slate-800 font-semibold text-xs sm:text-sm uppercase tracking-wide">
          {label}
        </Text>
        {sortKey === k && (
          <Svg width={12} height={12} viewBox="0 -960 960 960" fill="#334155">
            {sortDir === "asc" ? (
              <Path d="M480-680 240-440h480L480-680Z" />
            ) : (
              <Path d="M240-520h480L480-280 240-520Z" />
            )}
          </Svg>
        )}
      </View>
    </Pressable>
  );

  return (
    <View className="px-6 flex-1">
      <ScrollView
        contentContainerStyle={{ flexGrow: 1, paddingBottom: 16 }}
        refreshControl={
          <RefreshControl
            refreshing={isRefetching}
            onRefresh={onRefresh}
            tintColor="#6F09EA"
          />
        }
      >
        <View className="rounded-none overflow-hidden border border-slate-200 bg-white shadow-sm">
          <View className="bg-slate-100 border-b border-slate-200 flex-row">
            <SortHeader label="Curso" k="curso_asignado" flex={3} />
            <SortHeader label="Nombre" k="nombre_estudiante" flex={3} />
            <SortHeader label="Pendiente" k="monto_pendiente" flex={1.5} />
            <SortHeader label="Fecha" k="fecha_transaction" flex={1.5} />
            <SortHeader label="Grupo" k="grupo" flex={1.5} />
            <SortHeader label="" k={null} flex={1} center />
          </View>
          {filtered.length > 0 ? (
            groupedData.grouped ? (
              // Vista agrupada por años o meses
              groupedData.keys.map((key) => {
                const displayLabel =
                  groupedData.type === "month"
                    ? key.split("-")[1].charAt(0).toUpperCase() +
                    key.split("-")[1].slice(1)
                    : key;
                const icon =
                  groupedData.type === "month"
                    ? "M480-80q-83 0-156-31.5T197-197q-54-54-85.5-127T80-480q0-83 31.5-156T197-763q54-54 127-85.5T480-880q83 0 156 31.5T763-763q54 54 85.5 127T880-480q0 83-31.5 156T763-197q-54 54-127 85.5T480-80Zm0-80q134 0 227-93t93-227q0-134-93-227t-227-93q-134 0-227 93t-93 227q0 134 93 227t227 93Zm0-320Zm0 200q17 0 28.5-11.5T520-320v-160q0-17-11.5-28.5T480-520q-17 0-28.5 11.5T440-480v160q0 17 11.5 28.5T480-280Zm0-320q17 0 28.5-11.5T520-640q0-17-11.5-28.5T480-680q-17 0-28.5 11.5T440-640q0 17 11.5 28.5T480-600Z"
                    : "M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Zm0-480h560v-80H200v80Zm0 0v-80 80Z";

                return (
                  <View key={key}>
                    {/* Header del año o mes */}
                    <View className="bg-indigo-600 py-3 px-4 flex-row items-center border-t border-indigo-700">
                      <Svg
                        height="20"
                        viewBox="0 -960 960 960"
                        width="20"
                        fill="#ffffff"
                      >
                        <Path d={icon} />
                      </Svg>
                      <Text className="text-white font-bold text-lg ml-2">
                        {displayLabel}
                      </Text>
                      <View className="flex-1" />
                      <View className="bg-white/20 px-3 py-1 rounded-full">
                        <Text className="text-white text-sm font-semibold">
                          {groupedData.data[key].length}{" "}
                          {groupedData.data[key].length === 1
                            ? "transacción"
                            : "transacciones"}
                        </Text>
                      </View>
                    </View>
                    {/* Transacciones del grupo */}
                    {groupedData.data[key].map((alumno, index) => {
                      const fecha = alumno.fecha_transaction
                        ? new Date(alumno.fecha_transaction)
                        : null;
                      const añoActual = new Date().getFullYear();
                      const esAñoActual = fecha
                        ? fecha.getFullYear() === añoActual
                        : true;

                      return (
                        <View
                          key={alumno.id_transaccion || `\$\{key\}-\$\{index\}`}
                          className={`flex-row items-center border-t ${esAñoActual
                              ? `border-slate-200 ${index % 2 ? "bg-white" : "bg-slate-50"}`
                              : "border-orange-200 bg-orange-50/30"
                            }`}
                        >
                          <TouchableOpacity
                            style={{ flexDirection: "row", flex: 11.5 }}
                            onPress={() => onRowClick && onRowClick(alumno)}
                          >
                            <Text
                              style={{ flex: 3 }}
                              className={`p-3 ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                              numberOfLines={2}
                            >
                              {alumno.nombre_curso}
                            </Text>
                            <Text
                              style={{ flex: 3 }}
                              className={`p-3 ${esAñoActual ? "text-slate-800" : "text-slate-700"}`}
                              numberOfLines={1}
                            >
                              {alumno.nombre_alumno}
                            </Text>
                            <Text
                              style={{ flex: 1.5 }}
                              className={`p-3 font-medium ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                            >
                              {currencyFormatter.format(
                                alumno.monto_pendiente || 0,
                              )}
                            </Text>
                            <View style={{ flex: 1.5 }} className="p-3">
                              {alumno.fecha_transaction ? (
                                (() => {
                                  // Parsear string YYYY-MM-DD directamente
                                  const dateStr =
                                    alumno.fecha_transaction.split("T")[0];
                                  const [year, month, day] = dateStr
                                    .split("-")
                                    .map(Number);

                                  const monthsShort = [
                                    "ene",
                                    "feb",
                                    "mar",
                                    "abr",
                                    "may",
                                    "jun",
                                    "jul",
                                    "ago",
                                    "sep",
                                    "oct",
                                    "nov",
                                    "dic",
                                  ];

                                  const monthName =
                                    monthsShort[month - 1] || "???";
                                  const diaMes = `${day} ${monthName}`;

                                  return (
                                    <Text
                                      className={
                                        esAñoActual
                                          ? "text-slate-700"
                                          : "text-slate-600"
                                      }
                                      numberOfLines={1}
                                    >
                                      {diaMes}
                                    </Text>
                                  );
                                })()
                              ) : (
                                <Text className="text-slate-400">N/A</Text>
                              )}
                            </View>
                            <Text
                              style={{ flex: 1.5, marginLeft: 0 }}
                              className={`p-3 ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                              numberOfLines={1}
                            >
                              {alumno.grupo}
                            </Text>
                          </TouchableOpacity>
                          <View
                            style={{ flex: 1 }}
                            className="p-3 flex-row justify-center items-center"
                          >
                            <TouchableOpacity onPress={() => onReprint(alumno)}>
                              <Svg
                                height="22"
                                viewBox="0 -960 960 960"
                                width="22"
                                fill="#475569"
                              >
                                <Path d="M640-640v-120H320v120h-80v-200h480v200h-80Zm-480 80h640-640Zm560 100q17 0 28.5-11.5T760-500q0-17-11.5-28.5T720-540q-17 0-28.5 11.5T680-500q0 17 11.5 28.5T720-460Zm-80 260v-160H320v160h320Zm80 80H240v-160H80v-240q0-51 35-85.5t85-34.5h560q51 0 85.5 34.5T880-520v240H720v160Zm80-240v-160q0-17-11.5-28.5T760-560H200q-17 0-28.5 11.5T160-520v160h80v-80h480v80h80Z" />
                              </Svg>
                            </TouchableOpacity>
                          </View>
                        </View>
                      );
                    })}
                  </View>
                );
              })
            ) : (
              // Vista normal (año específico seleccionado)
              filtered.map((alumno, index) => {
                // Determinar si la transacción es del año actual
                const fecha = alumno.fecha_transaction
                  ? new Date(alumno.fecha_transaction)
                  : null;
                const añoActual = new Date().getFullYear();
                const esAñoActual = fecha
                  ? fecha.getFullYear() === añoActual
                  : true;

                return (
                  <View
                    key={alumno.id_transaccion || index}
                    className={`flex-row items-center border-t ${esAñoActual
                        ? `border-slate-200 ${index % 2 ? "bg-white" : "bg-slate-50"}`
                        : "border-orange-200 bg-orange-50/30"
                      }`}
                  >
                    <TouchableOpacity
                      style={{ flexDirection: "row", flex: 11.5 }}
                      onPress={() => onRowClick && onRowClick(alumno)}
                    >
                      <Text
                        style={{ flex: 3 }}
                        className={`p-3 ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                        numberOfLines={2}
                      >
                        {alumno.nombre_curso}
                      </Text>
                      <Text
                        style={{ flex: 3 }}
                        className={`p-3 ${esAñoActual ? "text-slate-800" : "text-slate-700"}`}
                        numberOfLines={1}
                      >
                        {alumno.nombre_alumno}
                      </Text>
                      <Text
                        style={{ flex: 1.5 }}
                        className={`p-3 font-medium ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                      >
                        {currencyFormatter.format(alumno.monto_pendiente || 0)}
                      </Text>
                      <View style={{ flex: 1.5 }} className="p-3">
                        {alumno.fecha_transaction ? (
                          (() => {
                            // Parsear string YYYY-MM-DD directamente
                            const dateStr =
                              alumno.fecha_transaction.split("T")[0];
                            const [year, month, day] = dateStr
                              .split("-")
                              .map(Number);

                            const monthsShort = [
                              "ene",
                              "feb",
                              "mar",
                              "abr",
                              "may",
                              "jun",
                              "jul",
                              "ago",
                              "sep",
                              "oct",
                              "nov",
                              "dic",
                            ];

                            const monthName = monthsShort[month - 1] || "???";
                            const diaMes = `${day} ${monthName}`;

                            const añoActual = new Date().getFullYear();
                            const esAñoActual = year === añoActual;

                            return (
                              <Text
                                className={
                                  esAñoActual
                                    ? "text-slate-700"
                                    : "text-slate-600"
                                }
                                numberOfLines={1}
                              >
                                {diaMes}
                              </Text>
                            );
                          })()
                        ) : (
                          <Text className="text-slate-400">N/A</Text>
                        )}
                      </View>
                      <Text
                        style={{ flex: 1.5, marginLeft: 0 }}
                        className={`p-3 ${esAñoActual ? "text-slate-700" : "text-slate-600"}`}
                        numberOfLines={1}
                      >
                        {alumno.grupo}
                      </Text>
                    </TouchableOpacity>
                    <View
                      style={{ flex: 1 }}
                      className="p-3 flex-row justify-center items-center"
                    >
                      <TouchableOpacity onPress={() => onReprint(alumno)}>
                        <Svg
                          height="22"
                          viewBox="0 -960 960 960"
                          width="22"
                          fill="#475569"
                        >
                          <Path d="M640-640v-120H320v120h-80v-200h480v200h-80Zm-480 80h640-640Zm560 100q17 0 28.5-11.5T760-500q0-17-11.5-28.5T720-540q-17 0-28.5 11.5T680-500q0 17 11.5 28.5T720-460Zm-80 260v-160H320v160h320Zm80 80H240v-160H80v-240q0-51 35-85.5t85-34.5h560q51 0 85.5 34.5T880-520v240H720v160Zm80-240v-160q0-17-11.5-28.5T760-560H200q-17 0-28.5 11.5T160-520v160h80v-80h480v80h80Z" />
                        </Svg>
                      </TouchableOpacity>
                    </View>
                  </View>
                );
              })
            )
          ) : (
            <View className="p-8 items-center justify-center bg-white">
              <Text className="text-slate-500 text-center font-medium">
                {query
                  ? "No se encontraron resultados para tu búsqueda."
                  : "Aún no hay ventas con adeudos registradas."}
              </Text>
              <Text className="text-slate-400 text-center text-sm mt-1">
                {query
                  ? "Intenta con otras palabras clave."
                  : "¡Todo está al día!"}
              </Text>
            </View>
          )}
        </View>
      </ScrollView>
      {isRefetching && (
        <View
          style={StyleSheet.absoluteFill}
          className="absolute inset-0 bg-white/50 flex items-center justify-center rounded-xl"
        >
          <ActivityIndicator size="large" color="#6F09EA" />
        </View>
      )}
    </View>
  );
};


