            </>
          )}
        </View>
        {freq && form.curso_id && (
          <Text style={s.freqNote}>⟳ Frecuencia: {freq.replace("Pago ", "")}</Text>
        )}
      </View>

      {form.incentivo_premium > 0 && (
        <Row label="Incentivo Premium:"
          value={`- ${fmt.format(form.importe - totalConIncentivo)}`}
          ls={s.amber} vs={s.amber} />
      )}

      <View style={s.sep} />
      <Row
        label={full ? "Pago completo:" : "Anticipo (pago hoy):"}
        value={`- ${fmt.format(paid)}`}
        vs={{ fontWeight: "700" }}
      />
      <View style={s.sep} />

      {!full && form.curso_id && paid > 0 && (
        <Row label="Pendiente por pagar:" value={fmt.format(due)}
          ls={s.red} vs={[s.red, { fontWeight: "700", fontSize: 16 }]} />
