          })
          .eq("id_alumno", finalIdAlumno);

        if (updateStudentError) console.error("Error actualizando alumno con transacción/curso:", updateStudentError);
      }

      // Registrar el anticipo como ingreso en el momento de la venta (dinero cobrado en caja).
      // Así el flujo cuadra: anticipo (venta) + abonos (pagos posteriores) = total.
      // Si el cliente abandona, el anticipo ya quedó registrado y solo se cancela el pendiente.
      const anticipoCobrado = Number(form.anticipo) || 0;
      if (anticipoCobrado > 0) {
        const { error: ingresoAnticipoError } = await supabase
          .from("ingresos")
          .insert([
            buildIngresoPayload({
              amount: anticipoCobrado,
              courseName: selectedCursoInfo?.label,
              studentName: form.nombre_cliente?.trim(),
            }),
          ]);

        if (ingresoAnticipoError) {
          console.error(
            "Error registrando el anticipo como ingreso:",
            ingresoAnticipoError,
          );
          notifyError(
            "La venta se guardó, pero no se pudo registrar el anticipo en finanzas. Regístralo manualmente para evitar descuadres.",
          );
        }
      }

      await printToFile(generatedFolio);

      Keyboard.dismiss();
      await notifySuccess(
        "La venta se ha guardado con éxito.",
        "Venta Registrada",
      );
      onFormClose();
    } catch (error) {
      console.error("Error al registrar la venta:", error);
      notifyError("No se pudo registrar la venta. Inténtalo de nuevo.");
    } finally {
      setIsSaving(false);
    }
  }, [
    form,
    isFormValid,
    incentivoEnPorcentaje,
    totalFinal,
    totalConIncentivo,
    onFormClose,
    isNewStudent,
    selectedCursoInfo,
  ]);

  return {
    isLandscape,
    form,
    setForm,
    cursos,
    estudiantes,
    gruposDB,
    loadingCursos,
    loadingEstudiantes,
    loadingGrupos,
    incentivoEnPorcentaje,
    isSaving,
    is_incentivo_active,
    isDescripcionManual,
    setIsDescripcionManual,
    showCustomDireccion,
    setShowCustomDireccion,
    showCustomGrupo,
    setShowCustomGrupo,
    isNewStudent,
    setIsNewStudent,
    defineFechaLimite,
    setDefineFechaLimite,
    liveHoras,
    setLiveHoras,
    liveAnticipo,
    setLiveAnticipo,
    liveIncentivo,
    setLiveIncentivo,
    dateParts,
    setDateParts,
    monthInputRef,
    yearInputRef,
    handleClearForm,
    handleCursoChange,
    handleCursoQuantityChange,
    handleDirectAnticipoChange,
    handleDirectIncentivoChange,
    stopCounter,
    handleIncentivoPress,
    handleIncentivoDeactivation,
    toggleIncentivoTipo,
    totalFinal,
    pendienteSinIncentivo,
    totalConIncentivo,
    isAnticipoDisabled,
    isPagoCompleto,
    formattedFechaLimite,
    is_incentivo_disabled,
    selectedCursoInfo,
    handleDatePartChange,
    handleDateBlur,
    isFormValid,
    maxAnticipoPosible,
    handleRegisterSale,
    intervalRef,
  };
}

import React from "react";
