function useConfirmationContext() {
  const context = useContext(ConfirmationContext);
  if (!context) {
    throw new Error(
      "useConfirm/useNotify must be used within a ConfirmationProvider",
    );
  }
  return context;
}

// Modal de confirmación (dos botones). Devuelve una promesa que resuelve true/false.
// Uso: const confirm = useConfirm(); const ok = await confirm({ title, message });
export function useConfirm() {
  return useConfirmationContext().confirm;
}

// Modales de aviso (un solo botón) con diseño de la app.
// Uso: const { notifySuccess, notifyError, notify } = useNotify();
//      await notifySuccess("Datos guardados correctamente");
//      await notifyError("No se pudo guardar");
//      await notify({ type: "warning", title: "Atención", message: "..." });
export function useNotify() {
  const { notify, notifySuccess, notifyError } = useConfirmationContext();
  return { notify, notifySuccess, notifyError };
}

