const mergeSetting = (defaults, value) => {
  if (!value || typeof value !== "object") {
    return { ...defaults };
  }

  return {
    ...defaults,
    ...value,
    instructions: Array.isArray(value.instructions)
      ? value.instructions
      : defaults.instructions,
    locationLines: Array.isArray(value.locationLines)
      ? value.locationLines
      : defaults.locationLines,
    documents: Array.isArray(value.documents)
      ? value.documents
      : defaults.documents,
  };
};

export const loadAppSetting = async (key, defaults) => {
  const { data, error } = await supabase
    .from("app_settings")
    .select("value")
    .eq("key", key)
    .maybeSingle();

  if (error) {
    throw error;
  }

  if (!defaults) {
    return data?.value ?? null;
  }

  if (key === APP_SETTING_KEYS.paymentContent) {
    return mergeSetting(defaults, data?.value);
  }

  return {
    ...defaults,
    ...(data?.value && typeof data.value === "object" ? data.value : {}),
  };
};

export const saveAppSetting = async (key, value) => {
  const { error } = await supabase.from("app_settings").upsert({ key, value });

  if (error) {
    throw error;
  }
};

// Caché multi-capa para catálogos y tarifarios:
// 1. Memoria (instantáneo, se pierde al recargar)
// 2. AsyncStorage (persiste entre sesiones)
// 3. Precarga de imágenes (Image.prefetch)
// 4. Lazy loading por ventana visible

import AsyncStorage from "@react-native-async-storage/async-storage";
import { Image } from "react-native";

const MEMORY_CACHE = {
  Catalogos: null,
  Tarifarios: null,
};

const STORAGE_KEY = "fenix_catalog_cache";
const CACHE_TTL = 1000 * 60 * 30; // 30 minutos

// --- Memoria ---
export const getCachedFiles = (bucket) => MEMORY_CACHE[bucket];

export const setCachedFiles = (bucket, files) => {
  MEMORY_CACHE[bucket] = files;
};

export const invalidateCatalogCache = (bucket) => {
  if (bucket) {
    MEMORY_CACHE[bucket] = null;
  } else {
    MEMORY_CACHE.Catalogos = null;
    MEMORY_CACHE.Tarifarios = null;
  }
  // También limpiar AsyncStorage
  clearStorageCache();
};

// --- AsyncStorage (persistencia) ---
const loadFromStorage = async () => {
  try {
    const raw = await AsyncStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    // Verificar TTL
    if (Date.now() - parsed.timestamp > CACHE_TTL) {
      await AsyncStorage.removeItem(STORAGE_KEY);
      return null;
    }
    return parsed.data;
  } catch {
    return null;
  }
};

const saveToStorage = async (data) => {
  try {
    await AsyncStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ data, timestamp: Date.now() })
    );
  } catch {
    // Silenciar errores de AsyncStorage
  }
};

const clearStorageCache = async () => {
  try {
    await AsyncStorage.removeItem(STORAGE_KEY);
  } catch {
    // Silenciar
  }
};

// --- Carga híbrida (memoria → storage → red) ---
export const loadCatalogData = async (fetchFn) => {
  // 1. Si ya está en memoria, revalidar en background
  const memCache = MEMORY_CACHE.Catalogos && MEMORY_CACHE.Tarifarios;
  if (memCache) {
    // Revalidar en background sin bloquear
    revalidateInBackground(fetchFn);
    return { fromCache: true, immediate: true };
  }

  // 2. Intentar cargar desde AsyncStorage
  const stored = await loadFromStorage();
  if (stored) {
    MEMORY_CACHE.Catalogos = stored.Catalogos;
    MEMORY_CACHE.Tarifarios = stored.Tarifarios;
    // Revalidar en background
    revalidateInBackground(fetchFn);
    return { fromCache: true, immediate: true };
  }

  // 3. Cargar desde red (primera vez)
  await fetchFn();
  return { fromCache: false, immediate: false };
};

const revalidateInBackground = async (fetchFn) => {
  try {
    await fetchFn();
  } catch {
    // Silenciar errores de revalidación
  }
};

// --- Precarga de imágenes ---
const PREFETCH_AHEAD = 2; // Precargar las siguientes 2 imágenes

export const prefetchImages = (files, currentIndex) => {
  if (!files || files.length === 0) return;

  const start = Math.max(0, currentIndex);
  const end = Math.min(files.length, currentIndex + PREFETCH_AHEAD + 1);

  for (let i = start; i < end; i++) {
    const file = files[i];
    if (file && !file.isPdf && file.uri) {
      Image.prefetch(file.uri).catch(() => {});
    }
  }
};

// Precargar todas las miniaturas de golpe (para thumbnails pequeños)
export const prefetchAllThumbnails = (files) => {
  if (!files) return;
  files.forEach((file) => {
    if (file && !file.isPdf && file.uri) {
      Image.prefetch(file.uri).catch(() => {});
    }
  });
};

// --- Lazy loading: determinar qué imágenes mostrar ---
export const getVisibleRange = (totalItems, currentIndex, windowSize = 3) => {
  const half = Math.floor(windowSize / 2);
  const start = Math.max(0, currentIndex - half);
  const end = Math.min(totalItems, currentIndex + half + 1);
  return { start, end };
};

const toSafeNumber = (value) => {
  const numericValue = Number(value);
  return Number.isFinite(numericValue) ? numericValue : 0;
};

export const getCurrentDateString = () => {
  const today = new Date();
  const year = today.getFullYear();
  const month = String(today.getMonth() + 1).padStart(2, "0");
  const day = String(today.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

export const getPaidAmount = (transaction = {}) => {
  const total = toSafeNumber(transaction.total);
  const pendiente = toSafeNumber(transaction.pendiente);
  return Math.max(total - pendiente, 0);
};

export const buildTransactionPaymentUpdate = (transaction = {}, paymentAmount) => {
  const pendienteActual = toSafeNumber(transaction.pendiente);
  const anticipoActual = toSafeNumber(transaction.anticipo);
  const totalActual = toSafeNumber(transaction.total);
  const appliedAmount = Math.min(Math.max(toSafeNumber(paymentAmount), 0), pendienteActual);
  const newPendiente = Math.max(pendienteActual - appliedAmount, 0);
  const newAnticipo = anticipoActual; // El anticipo original de la transacción no se altera por nuevos abonos
  const shouldRecognizeIncome = appliedAmount > 0;

  return {
    appliedAmount,
    newPendiente,
    newAnticipo,
    shouldRecognizeIncome,
    recognizedAmount: appliedAmount, // Reconocemos únicamente el monto abonado en este pago
  };
};

