const CustomDrawerContent = ({
  isCollapsed = false,
  onToggleCollapse,
  ...props
}) => {
  const { state, descriptors, navigation, ...rest } = props;
  const { width } = useWindowDimensions();
  const isDesktop = width >= 1200;
  const isTablet = width >= 768 && width < 1200;
  const confirm = useConfirm();

  const filteredRoutes = state.routes.filter(
    (item) => item.name !== "LogOut" && item.name !== "Configuración",
  );
  const isConfigActive = state.routes[state.index]?.name === "Configuración";
  const activeRouteIndex = filteredRoutes.findIndex(
    (route) => route.key === state.routes[state.index]?.key,
  );

  const newState = {
    ...state,
    routes: filteredRoutes,
    index: activeRouteIndex >= 0 ? activeRouteIndex : 0,
  };

  const confirmSignOut = async () => {
    const isConfirmed = await confirm({
      title: "Cerrar sesión",
      message: "¿Seguro que deseas cerrar la sesión actual?",
      confirmText: "Cerrar sesión",
      cancelText: "Cancelar",
      type: "destructive",
    });

    if (isConfirmed) {
      try {
        await supabase.auth.signOut();
      } catch (e) {
        console.error("Sign out error", e);
      }
    }
  };

  const renderCollapseToggle = () => {
    if (!isDesktop) return null;

    return (
      <View
        style={{
          paddingHorizontal: isCollapsed ? 6 : 14,
          paddingTop: 10,
          paddingBottom: isCollapsed ? 8 : 12,
          alignItems: isCollapsed ? "center" : "flex-end",
        }}
      >
        <Pressable
          onPress={onToggleCollapse}
          style={{
            width: 40,
            height: 40,
            borderRadius: 12,
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: "#eef2ff",
            borderWidth: 1,
            borderColor: "#dbeafe",
          }}
        >
          <Svg
            height="18"
            viewBox="0 -960 960 960"
            width="18"
            fill="#4338ca"
          >
            {isCollapsed ? (
              <Path d="m321-80-71-71 329-329-329-329 71-71 400 400-400 400Z" />
            ) : (
              <Path d="M400-80 0-480l400-400 71 71-278 278h687v102H193l278 278-71 71Z" />
            )}
          </Svg>
        </Pressable>
      </View>
