const INITIAL_CONFIG = {
  visible: false,
  title: "",
  message: "",
  confirmText: "Aceptar",
  cancelText: "Cancelar",
  type: "default",
  showCancel: true,
  resolve: null,
};

export default function ConfirmationProvider({ children }) {
  const [config, setConfig] = useState(INITIAL_CONFIG);

  // Modal de confirmación (dos botones). Resuelve true/false.
  const confirm = useCallback((options = {}) => {
    return new Promise((resolve) => {
      setConfig({
        visible: true,
        title: options.title || "Confirmar acción",
        message: options.message || "¿Estás seguro?",
        confirmText: options.confirmText || "Confirmar",
        cancelText: options.cancelText || "Cancelar",
        type: options.type || "default",
        showCancel: options.showCancel !== false,
        resolve,
      });
    });
  }, []);

  // Modal de aviso (un solo botón): éxito, error, advertencia o info.
  // Resuelve cuando el usuario lo cierra.
  const notify = useCallback((options = {}) => {
    return new Promise((resolve) => {
      setConfig({
        visible: true,
        title: options.title || "",
        message: options.message || "",
        confirmText: options.confirmText || "Aceptar",
        cancelText: "",
        type: options.type || "success",
        showCancel: false,
        resolve,
      });
    });
  }, []);

  // Atajos cómodos
  const notifySuccess = useCallback(
    (message, title = "Éxito") => notify({ type: "success", title, message }),
    [notify],
  );
  const notifyError = useCallback(
    (message, title = "Error") => notify({ type: "error", title, message }),
    [notify],
  );

  const close = (result) => {
    if (config.resolve) {
      config.resolve(result);
    }
    setConfig((prev) => ({ ...prev, visible: false, resolve: null }));
  };

  const handleCancel = () => close(false);
  const handleConfirm = () => close(true);

  const palette = TYPE_STYLES[config.type] || TYPE_STYLES.default;
  const iconPath = ICON_PATHS[config.type] || ICON_PATHS.default;

  const value = useMemo(
    () => ({ confirm, notify, notifySuccess, notifyError }),
    [confirm, notify, notifySuccess, notifyError],
  );

  return (
    <ConfirmationContext.Provider value={value}>
      {children}
      <Modal
        visible={config.visible}
        transparent={true}
        animationType="fade"
        onRequestClose={handleCancel}
      >
        <Pressable style={styles.overlay} onPress={handleCancel}>
          <Pressable style={styles.card} onPress={(e) => e.stopPropagation()}>
            <View style={styles.header}>
              <View style={[styles.iconContainer, { backgroundColor: palette.iconBg }]}>
                <Svg height="24" viewBox="0 -960 960 960" width="24" fill={palette.icon}>
                  <Path d={iconPath} />
                </Svg>
              </View>
              {!!config.title && <Text style={styles.title}>{config.title}</Text>}
            </View>

            {!!config.message && <Text style={styles.message}>{config.message}</Text>}

            <View style={styles.buttonRow}>
              {config.showCancel && (
                <TouchableOpacity
                  onPress={handleCancel}
                  style={[styles.button, styles.cancelButton]}
                  activeOpacity={0.7}
                >
                  <Text style={styles.cancelButtonText}>{config.cancelText}</Text>
                </TouchableOpacity>
              )}
              <TouchableOpacity
                onPress={handleConfirm}
                style={[styles.button, { backgroundColor: palette.button }]}
                activeOpacity={0.7}
              >
                <Text style={styles.confirmButtonText}>{config.confirmText}</Text>
              </TouchableOpacity>
            </View>
          </Pressable>
        </Pressable>
      </Modal>
    </ConfirmationContext.Provider>
  );
}

