const styles = StyleSheet.create({});

import { useState } from "react";
import {
  View,
  Text,
  TextInput,
  Pressable,
  Platform,
  Keyboard,
  StyleSheet,
} from "react-native";
import * as Linking from "expo-linking";
import { supabase } from "../lib/supabase";
import HeaderAdmin from "../components/HeaderAdmin";
import { LinearGradient } from "expo-linear-gradient";

const MIN_PASSWORD_LENGTH = 6;

export default function RegisterScreen({ navigation }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [infoMsg, setInfoMsg] = useState("");
  const [resending, setResending] = useState(false);

  const allowedDomains = (process.env.EXPO_PUBLIC_AUTH_ALLOWED_DOMAINS || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const allowedEmails = (process.env.EXPO_PUBLIC_AUTH_ALLOWED_EMAILS || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const emailAllowed = (value) => {
    if (!value) return false;
    const lower = value.toLowerCase();
    if (allowedEmails.length > 0) return allowedEmails.includes(lower);
    if (allowedDomains.length === 0) return true;
    const domain = value.split("@")[1]?.toLowerCase();
    return !!domain && allowedDomains.includes(domain);
  };

  const onRegister = async () => {
    setErrorMsg("");
    setInfoMsg("");
    if (!email) return setErrorMsg("Ingresa tu correo.");
    if (!password) return setErrorMsg("Ingresa una contraseña.");
    if (password.length < MIN_PASSWORD_LENGTH) {
      return setErrorMsg(
        `La contraseña debe tener al menos ${MIN_PASSWORD_LENGTH} caracteres.`,
      );
    }
    if (!fullName) return setErrorMsg("Ingresa tu nombre.");
    if (!emailAllowed(email))
      return setErrorMsg("Este correo no está autorizado.");

    try {
      setSubmitting(true);
      const redirectTo =
        Platform.OS === "web" && typeof window !== "undefined"
          ? window.location.origin
          : Linking.createURL("/");
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { full_name: fullName },
          emailRedirectTo: redirectTo,
        },
      });
      if (error) {
        const msg = String(error.message || "").toLowerCase();
        if (msg.includes("signups not allowed")) {
          setErrorMsg("Acceso privado: los registros están deshabilitados.");
        } else if (msg.includes("user already registered")) {
          setErrorMsg("Este correo ya está registrado.");
        } else if (msg.includes("password") || msg.includes("weak")) {
          setErrorMsg(
            `La contraseña debe tener al menos ${MIN_PASSWORD_LENGTH} caracteres.`,
          );
        } else {
          setErrorMsg("No se pudo completar el registro.");
        }
      } else {
        if (!data?.user?.email_confirmed_at) {
          setInfoMsg(
            "Te enviamos un correo de verificación. Confirma para poder iniciar sesión.",
          );
        } else {
          setInfoMsg("Registro exitoso. Ya puedes iniciar sesión.");
        }
      }
    } finally {
      setSubmitting(false);
    }
  };

  const onResend = async () => {
    setErrorMsg("");
    setInfoMsg("");
    if (!email) return setErrorMsg("Ingresa tu correo para reenviar.");
    try {
      setResending(true);
      const { error } = await supabase.auth.resend({ type: "signup", email });
      if (error) {
        const msg = String(error.message || "").toLowerCase();
        if (error.status === 429 || msg.includes("retry")) {
          setErrorMsg("Demasiados intentos. Reintenta en unos segundos.");
        } else {
          setErrorMsg("No se pudo reenviar el correo.");
        }
        console.error("Resend verification error:", error);
      } else {
        setInfoMsg(
          "Correo de verificación reenviado. Revisa tu bandeja y spam.",
        );
      }
    } finally {
      setResending(false);
    }
  };

  return (
      <View style={{ flex: 1 }}>
        <HeaderAdmin
          logoSource={require("../assets/MQerK_logo.png")}
          onLogoPress={() => {}}
          title="Fenix Retail"
          showActions={false}
        />
        <View
          style={{
            flexGrow: 1,
            justifyContent: "center",
            alignItems: "center",
            paddingHorizontal: 16,
            paddingVertical: 24,
          }}
        >
          {renderForm()}
        </View>
      </View>
  );

  function renderForm() {
    return (
      <View style={styles.card}>
        <Text style={styles.title}>Regístrate</Text>
        <Text style={styles.subtitle}>Crea tu cuenta para continuar</Text>

        <View style={styles.formGap}>
          <Text style={styles.label}>Nombre completo</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={fullName}
            onChangeText={setFullName}
            placeholder="Tu nombre"
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Text style={styles.label}>Correo</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={email}
            onChangeText={setEmail}
            placeholder="tucorreo@dominio.com"
            autoCapitalize="none"
            keyboardType="email-address"
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Text style={styles.label}>Contraseña</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={password}
            onChangeText={setPassword}
            placeholder="Tu contraseña"
            autoCapitalize="none"
            secureTextEntry
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Pressable
            onPress={onRegister}
            disabled={submitting}
            style={[
              styles.button,
              submitting ? styles.buttonDisabled : styles.buttonPrimary,
            ]}
            hitSlop={10}
            android_ripple={{ color: "rgba(255,255,255,0.15)" }}
          >
            <Text style={styles.buttonText}>
              {submitting ? "Creando…" : "Crear cuenta"}
            </Text>
          </Pressable>
          {!!errorMsg && <Text style={styles.errorText}>{errorMsg}</Text>}
          {!!infoMsg && <Text style={styles.infoText}>{infoMsg}</Text>}
          <View style={styles.footer}>
            <Text style={styles.footerText}>¿No te llegó el correo?</Text>
            <Pressable
              onPress={onResend}
              disabled={resending}
              style={styles.resendButton}
              hitSlop={8}
              android_ripple={{ color: "rgba(0,0,0,0.05)" }}
            >
              <Text
                style={[
                  styles.resendText,
                  resending && styles.resendTextDisabled,
                ]}
              >
                {resending ? "Reenviando…" : "Reenviar verificación"}
              </Text>
            </Pressable>
          </View>
        </View>

        <View style={styles.loginLinkContainer}>
          <Text style={styles.loginLinkText}>
            ¿Ya tienes cuenta?{" "}
            <Text
              style={styles.loginLinkAction}
              onPress={() => navigation?.navigate("Login")}
            >
              Inicia sesión
            </Text>
          </Text>
        </View>
      </View>
    );
  }
}

const styles = StyleSheet.create({
  card: {
    width: 520,
    backgroundColor: "#ffffff",
    borderRadius: 16,
    padding: 20,
    ...(Platform.OS === "web"
      ? {
          boxShadow: "0px 10px 15px rgba(0, 0, 0, 0.1)",
        }
      : {
          shadowColor: "#000",
          shadowOffset: { width: 0, height: 10 },
