import { useState, useCallback, useEffect } from 'react'
import { supabase } from './lib/supabase'
import SearchBar from './components/SearchBar'
import TransactionTable from './components/TransactionTable'
import TicketPreview from './components/TicketPreview'
import SizeSelector from './components/SizeSelector'
import Login from './components/Login'
import './App.css'

export default function App() {
  const [query, setQuery] = useState('')
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [selected, setSelected] = useState(null)
  const [ticketSize, setTicketSize] = useState(80)
  const [session, setSession] = useState(null)
  const [showPendingOnly, setShowPendingOnly] = useState(true)
  const [theme, setTheme] = useState(() => {
    const saved = localStorage.getItem('theme')
    if (saved) return saved
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
  })

  const handleSearch = useCallback(async () => {
    setLoading(true)
    setError(null)
    setSelected(null)

    let queryBuilder = supabase
      .from('transacciones')
      .select(`
        id_transaccion,
        monto,
        fecha_transaction,
        referencia,
        alumno_id,
        curso_id,
        metodo_id,
        incentivo_premium,
        pendiente,
        total,
        anticipo,
        alumnos!fk_transacciones_alumno ( id_alumno, nombre_alumno, grupo ),
        cursos!fk_transacciones_curso ( id_curso, nombre_curso ),
        metodo_transferencia!fk_transacciones_metodo ( id_metodo, titular, banco, numero_tarjetaclabe )
      `)

    if (showPendingOnly) {
      queryBuilder = queryBuilder.gt('pendiente', 0)
    }

    const { data: rows, error: err } = await queryBuilder
      .order('fecha_transaction', { ascending: false })
      .limit(200)

    if (err) {
      setError(`Error al obtener datos: ${err.message}`)
      setData(null)
    } else {
      setData(rows)
      if (rows && rows.length > 0) {
        setSelected(rows[0])
      }
    }

    setLoading(false)
  }, [showPendingOnly])

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme)
    localStorage.setItem('theme', theme)
  }, [theme])

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: currentSession } }) => {
      setSession(currentSession)
    })

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session)
    })

    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => { 
    if (session) {
      handleSearch() 
    }
  }, [session, showPendingOnly, handleSearch])

  const handleSizeChange = (size) => {
    setTicketSize(size)
    // Keep selected, just re-render preview
  }

  return (
    <div className="app-layout">
      {/* ── Header ──────────────────────────────── */}
      <header className="app-header">
        <div className="header-brand">
          <div className="brand-icon">
            <svg viewBox="0 96 960 960" fill="currentColor" width="22" height="22">
              <path d="M168 936q-29.7 0-50.85-21.15Q96 893.7 96 864V693q0-12.75 8.675-21.375Q113.35 663 126.1 663q20.9 0 35.4-14.625Q176 633.75 176 613q0-20.75-14.5-35.375T126.1 563q-12.75 0-21.425-8.625Q96 545.75 96 533V360q0-29 21-50.5T168 288h625q29.7 0 50.85 21.5Q865 331 865 360v173q0 12.75-8.675 21.375Q847.65 563 834.9 563q-20.9 0-35.4 14.625Q785 592.25 785 613q0 20.75 14.5 35.375T834.9 663q12.75 0 21.425 8.625Q865 680.25 865 693v171q0 29.7-21.15 50.85Q822.7 936 793 936H168Z"/>
            </svg>
          </div>
          <div>
            <h1 className="brand-name">FR Tickets</h1>
            <p className="brand-sub">Fenix Retail — Generador de Comprobantes</p>
          </div>
        </div>
        <div className="header-actions">
          <button 
            className="btn-theme" 
            onClick={() => setTheme(prev => prev === 'dark' ? 'light' : 'dark')}
            title={`Cambiar a modo ${theme === 'dark' ? 'claro' : 'oscuro'}`}
          >
            {theme === 'dark' ? (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" width="18" height="18">
                <circle cx="12" cy="12" r="5"></circle>
                <line x1="12" y1="1" x2="12" y2="3"></line>
                <line x1="12" y1="21" x2="12" y2="23"></line>
                <line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line>
                <line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line>
                <line x1="1" y1="12" x2="3" y2="12"></line>
                <line x1="21" y1="12" x2="23" y2="12"></line>
                <line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line>
                <line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line>
              </svg>
            ) : (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" width="18" height="18">
                <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path>
              </svg>
            )}
          </button>
          {session && (
            <div className="header-actions-auth">
              <div className="header-badge">
                <span className="dot-live" />
                Conectado
              </div>
              <button className="btn-logout" onClick={() => supabase.auth.signOut()}>
                <svg viewBox="0 96 960 960" fill="currentColor" width="16" height="16">
                  <path d="M200 956q-33 0-56.5-23.5T120 876V276q0-33 23.5-56.5T200 196h280v80H200v600h280v80H200Zm440-160-55-58 102-102H360v-80h327L585 354l55-58 200 200-200 200Z"/>
                </svg>
                Salir
              </button>
            </div>
          )}
        </div>
      </header>

      {/* ── Main ────────────────────────────────── */}
      {!session ? (
        <Login />
      ) : (
        <main className="app-main">
          {/* Left panel: search + table */}
          <section className="panel panel-left">
            <div className="panel-title">
              <svg viewBox="0 96 960 960" fill="currentColor" width="18" height="18">
                <path d="M200 856v-556h-64v-80h624v80h-64v556H200Zm80-80h400V300H280v476Zm120-180h160v-76h-160v76Zm0-156h160v-80h-160v80ZM280 776V300v476Z"/>
              </svg>
              Transacciones
            </div>
            <SearchBar
              value={query}
              onChange={setQuery}
              onSearch={handleSearch}
              loading={loading}
            />
            {error && (
              <div className="error-banner">
                <svg viewBox="0 96 960 960" fill="currentColor" width="18" height="18">
                  <path d="M480 936q-83 0-156-31.5T197 823q-54-54-85.5-127T80 540q0-83 31.5-156T197 257q54-54 127-85.5T480 140q83 0 156 31.5T763 257q54 54 85.5 127T880 540q0 83-31.5 156T763 823q-54 54-127 85.5T480 936Zm-40-360h80V416h-80v160Zm40 180q17 0 28.5-11.5T520 716q0-17-11.5-28.5T480 676q-17 0-28.5 11.5T440 716q0 17 11.5 28.5T480 756Z"/>
                </svg>
                {error}
              </div>
            )}
            <TransactionTable
              data={data}
              loading={loading}
              query={query}
              onSelect={setSelected}
              selected={selected}
              showPendingOnly={showPendingOnly}
              setShowPendingOnly={setShowPendingOnly}
            />
          </section>

          {/* Right panel: ticket */}
          <section className="panel panel-right">
            <div className="panel-title">
              <svg viewBox="0 96 960 960" fill="currentColor" width="18" height="18">
                <path d="M168 936q-29.7 0-50.85-21.15Q96 893.7 96 864V693q0-12.75 8.675-21.375Q113.35 663 126.1 663q20.9 0 35.4-14.625Q176 633.75 176 613q0-20.75-14.5-35.375T126.1 563q-12.75 0-21.425-8.625Q96 545.75 96 533V360q0-29 21-50.5T168 288h625q29.7 0 50.85 21.5Q865 331 865 360v173q0 12.75-8.675 21.375Q847.65 563 834.9 563q-20.9 0-35.4 14.625Q785 592.25 785 613q0 20.75 14.5 35.375T834.9 663q12.75 0 21.425 8.625Q865 680.25 865 693v171q0 29.7-21.15 50.85Q822.7 936 793 936H168Z"/>
              </svg>
              Vista Previa del Ticket
            </div>
            <SizeSelector value={ticketSize} onChange={handleSizeChange} />
            <TicketPreview transaction={selected} size={ticketSize} />
          </section>
        </main>
      )}
    </div>
  )
}

import "react-native-gesture-handler";
import { View, ActivityIndicator, Platform, LogBox } from "react-native";
import React from "react";
import "./global.css";

import AppScreens from "./navigation/AppScreens";

// Silenciar advertencias específicas de RN Web de terceros (no corregibles desde nuestro código)
if (Platform.OS === "web") {
  LogBox.ignoreLogs([
    "props.pointerEvents is deprecated",
    "TouchableWithoutFeedback is deprecated",
    "@supabase/gotrue-js: Navigator LockManager returned a null lock",
    "LockManager returned a null lock",
    "tintColor is deprecated",
    "shadow* style props are deprecated",
  ]);
  const originalWarn = console.warn;
  console.warn = (...args) => {
    try {
      const msg = typeof args[0] === "string" ? args[0] : "";
      if (
        msg.includes("props.pointerEvents is deprecated") ||
        msg.includes("TouchableWithoutFeedback is deprecated") ||
        msg.includes(
          "@supabase/gotrue-js: Navigator LockManager returned a null lock",
        ) ||
        msg.includes("LockManager returned a null lock") ||
        msg.includes("tintColor is deprecated") ||
        msg.includes("shadow* style props are deprecated")
      ) {
        return;
      }
    } catch {}
    originalWarn(...args);
  };
}

export default AppScreens;

export const currencyFormatter = new Intl.NumberFormat("es-MX", {
  style: "currency",
  currency: "MXN",
});
export const monthsShort = [
  "ene", "feb", "mar", "abr", "may", "jun",
  "jul", "ago", "sep", "oct", "nov", "dic",
];
export const monthsLong = [
  "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
  "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre",
];

import { registerRootComponent } from "expo";
import "./global.css";
import React from "react";
import { NavigationContainer } from "@react-navigation/native";
import { TouchableWithoutFeedback, Keyboard, Platform, View, ActivityIndicator } from "react-native";

if (Platform.OS === 'web') {
  const ReactDOM = require('react-dom');
  if (!ReactDOM.findDOMNode) {
    ReactDOM.findDOMNode = (node) => node;
  }
}
import AsyncStorage from "@react-native-async-storage/async-storage";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import App from "./App";
import AuthProvider from "./providers/auth-provider";
import { SplashScreenController } from "./components/splash-screen-controller";
import LoginScreen from "./screens/Login";
import RegisterScreen from "./screens/Register";
import { useAuthContext } from "./hooks/use-auth-context";
import { SafeAreaProvider, SafeAreaView } from "react-native-safe-area-context";
import ConfirmationProvider from "./providers/confirmation-provider";
import { LinearGradient } from "expo-linear-gradient";

const Stack = createNativeStackNavigator();

const NAV_STATE_KEY = "NAVIGATION_STATE_V1";

function RootNavigator() {
  const { isLoggedIn, profile, isLoading } = useAuthContext();
  const [initialNavigationState, setInitialNavigationState] = React.useState();
  const [isNavigationStateReady, setIsNavigationStateReady] = React.useState(
    Platform.OS !== "web",
  );

  React.useEffect(() => {
    let isMounted = true;

    const restoreNavigationState = async () => {
      if (Platform.OS !== "web") {
        if (isMounted) setIsNavigationStateReady(true);
        return;
      }

      if (isLoading) return;

      if (!isLoggedIn) {
        if (isMounted) {
          setInitialNavigationState(undefined);
          setIsNavigationStateReady(true);
        }
        return;
      }

      try {
        const savedState = await AsyncStorage.getItem(NAV_STATE_KEY);
        if (!isMounted) return;

        setInitialNavigationState(
          savedState ? JSON.parse(savedState) : undefined,
        );
      } catch {
        if (!isMounted) return;
        setInitialNavigationState(undefined);
      } finally {
        if (isMounted) setIsNavigationStateReady(true);
      }
    };

    setIsNavigationStateReady(Platform.OS !== "web" ? true : false);
    restoreNavigationState();

    return () => {
      isMounted = false;
    };
  }, [isLoading, isLoggedIn]);

  if (isLoading || !isNavigationStateReady) {
    return (
      <SafeAreaProvider>
        <LinearGradient
          colors={["#3d18c3", "#4816bf"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 0 }}
          style={{ flex: 1 }}
        >
          <SafeAreaView style={{ flex: 1 }}>
            <View
              style={{
                flex: 1,
                justifyContent: "center",
                alignItems: "center",
                backgroundColor: "#4816bf",
              }}
            >
              <ActivityIndicator size="large" color="#ffffff" />
            </View>
          </SafeAreaView>
        </LinearGradient>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <LinearGradient
        colors={["#3d18c3", "#4816bf"]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 0 }}
        style={{ flex: 1 }}
      >
        <TouchableWithoutFeedback
          onPress={Platform.OS !== "web" ? () => Keyboard.dismiss() : null}
        >
          <SafeAreaView style={{ flex: 1 }}>
            <NavigationContainer
              onStateChange={(state) =>
                AsyncStorage.setItem(
                  NAV_STATE_KEY,
                  JSON.stringify(state),
                ).catch(() => {})
              }
              initialState={initialNavigationState}
            >
              <Stack.Navigator screenOptions={{ headerShown: false }}>
                {isLoading ? (
                  <Stack.Screen name="Loading" options={{ headerShown: false }}>
                    {() => (
                      <View style={{ flex: 1, justifyContent: "center", alignItems: "center", backgroundColor: "#4816bf" }}>
                        <ActivityIndicator size="large" color="#ffffff" />
                      </View>
                    )}
                  </Stack.Screen>
                ) : !isLoggedIn ? (
                  <>
                    <Stack.Screen name="Login" component={LoginScreen} />
                    <Stack.Screen name="Register" component={RegisterScreen} />
                  </>
                ) : (
                  <Stack.Screen name="Main" component={App} />
                )}
              </Stack.Navigator>
            </NavigationContainer>
          </SafeAreaView>
        </TouchableWithoutFeedback>
      </LinearGradient>
    </SafeAreaProvider>
  );
}

function Root() {
  return (
    <AuthProvider>
      <ConfirmationProvider>
        <SplashScreenController />
        <RootNavigator />
      </ConfirmationProvider>
    </AuthProvider>
  );
}

registerRootComponent(Root);

import Stripe from 'https://esm.sh/stripe@16.12.0?target=deno';
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';

const STRIPE_SECRET = Deno.env.get('STRIPE_SECRET_KEY');
const stripe = new Stripe(STRIPE_SECRET!, {
  apiVersion: '2024-06-20',
  httpClient: Stripe.createFetchHttpClient(),
});

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers':
    'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json', ...corsHeaders },
  });

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { status: 200, headers: corsHeaders });
  }

  if (req.method !== 'POST') return json({ error: 'Method Not Allowed' }, 405);

  try {
    const { amount, currency = 'mxn', description = 'Pago MQerK', success_url, cancel_url } = await req.json();
    if (!amount || !success_url || !cancel_url) {
      return json({ error: 'Missing fields' }, 400);
    }

    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency,
            product_data: { name: description },
            unit_amount: amount,
          },
          quantity: 1,
        },
      ],
      success_url,
      cancel_url,
    });

    return json({ id: session.id, url: session.url }, 200);
  } catch (e) {
    console.error(e);
    return json({ error: 'Internal error' }, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

const admin = createClient(supabaseUrl, serviceRoleKey);
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: {
      "Content-Type": "application/json",
      ...corsHeaders,
    },
  });

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", {
      status: 200,
      headers: corsHeaders,
    });
  }

  if (req.method !== "POST") {
    return json({ error: "Method Not Allowed" }, 405);
  }

  if (!supabaseUrl || !serviceRoleKey) {
    return json(
      { error: "Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY" },
      500,
    );
  }

  try {
    const authHeader = req.headers.get("Authorization");
    const accessToken = authHeader?.replace(/^Bearer\s+/i, "").trim();

    if (!accessToken) {
      return json({ error: "Unauthorized" }, 401);
    }

    const {
      data: { user },
      error: authError,
    } = await admin.auth.getUser(accessToken);

    if (authError || !user) {
      return json({ error: "Unauthorized" }, 401);
    }

    const { bucketName, isPublic = true, fileSizeLimit, allowedMimeTypes } =
      await req.json();

    if (!bucketName || typeof bucketName !== "string") {
      return json({ error: "bucketName is required" }, 400);
    }

    const { data: existingBucket, error: getBucketError } =
      await admin.storage.getBucket(bucketName);

    if (getBucketError && !/not found/i.test(getBucketError.message || "")) {
      throw getBucketError;
    }

    if (!existingBucket) {
      const { error: createError } = await admin.storage.createBucket(bucketName, {
        public: Boolean(isPublic),
        fileSizeLimit,
        allowedMimeTypes,
      });

      if (createError && !/already exists/i.test(createError.message || "")) {
        throw createError;
      }
    } else if (existingBucket.public !== Boolean(isPublic)) {
      const { error: updateError } = await admin.storage.updateBucket(bucketName, {
        public: Boolean(isPublic),
        fileSizeLimit: fileSizeLimit ?? existingBucket.file_size_limit ?? undefined,
        allowedMimeTypes:
          allowedMimeTypes ?? existingBucket.allowed_mime_types ?? undefined,
      });

      if (updateError) {
        throw updateError;
      }
    }

    return json({
      ok: true,
      bucketName,
      existed: Boolean(existingBucket),
    });
  } catch (error) {
    console.error("ensure-storage-bucket error", error);
    return json(
      { error: error instanceof Error ? error.message : "Internal error" },
      500,
    );
  }
});

import Stripe from 'https://esm.sh/stripe@16.12.0?target=deno';
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';

const STRIPE_SECRET = Deno.env.get('STRIPE_SECRET_KEY');
const STRIPE_WEBHOOK_SECRET = Deno.env.get('STRIPE_WEBHOOK_SECRET');
const stripe = new Stripe(STRIPE_SECRET!, {
  apiVersion: '2024-06-20',
  httpClient: Stripe.createFetchHttpClient(),
});

serve(async (req) => {
  if (req.method !== 'POST') return new Response('Method Not Allowed', { status: 405 });
  try {
    const rawBody = await req.text();
    const sig = req.headers.get('stripe-signature');
    let event: Stripe.Event;

    if (!sig || !STRIPE_WEBHOOK_SECRET) {
      return new Response('Webhook signature missing', { status: 400 });
    }

    event = await stripe.webhooks.constructEventAsync(rawBody, sig, STRIPE_WEBHOOK_SECRET);

    switch (event.type) {
      case 'checkout.session.completed':
        // TODO: persist the payment with Supabase client (service role)
        break;
      default:
        break;
    }

    return new Response(JSON.stringify({ received: true }), { status: 200, headers: { 'Content-Type': 'application/json' } });
  } catch (e) {
    console.error(e);
    return new Response(JSON.stringify({ error: 'Internal error' }), { status: 500 });
  }
});

