/**
 * HeaderAdmin (React Native / Expo)
 * - Diseño inspirado en el header web proporcionado
 * - Sin dependencias de react-router-dom ni contextos externos
 * - Controlado por props para integrar con tu navegación y datos reales
 *
 * Props:
 * - title?: string
 * - subtitle?: string
 * - logoSource?: ImageSourcePropType
 * - onLogoPress?: () => void
 * - unreadCount?: number
 * - notifications?: Array<{ id: string|number, message: string, meta?: any }>
 * - onNotificationPress?: (n) => void
 * - onMarkAllAsRead?: () => void
 * - adminProfile?: { name?: string, email?: string, role?: string, avatar?: string, lastLogin?: string|number }
 * - onLogout?: () => void
 * - onNavigateToSettings?: () => void
 */
function HeaderAdmin({
  title = "Fenix Retail",
  subtitle = "",
  logoSource,
  onLogoPress,
  showMenuButton = false,
  onMenuPress,
  unreadCount = 0,
  notifications = [],
  onNotificationPress,
  onMarkAllAsRead,
  adminProfile,
  onLogout,
  onNavigateToSettings,
  showActions = true,
  sizeVariant = "default", // 'default' | 'login' | 'loginXL'
}) {
  const { width } = useWindowDimensions();
  const isSmall = width < 640; // móvil
  const isTablet = width >= 640 && width < 1024; // tablet (iPad Mini ~768)
  const scale =
    sizeVariant === "login" ? 1.15 : sizeVariant === "loginXL" ? 1.35 : 1;
  const avatarSize = Math.round((isSmall ? 44 : isTablet ? 52 : 56) * scale);

  const [profileMenuVisible, setProfileMenuVisible] = useState(false);

  const getInitials = (name) => {
    const parts = String(name).trim().split(/\s+/);
    return parts.length >= 2
      ? `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase()
      : parts[0].slice(0, 2).toUpperCase();
  };

  return (
    <LinearGradient
      colors={["#3d18c3", "#4816bf"]}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 0 }}
      className={``}
      style={{
        paddingTop:
          sizeVariant === "login"
            ? 24
            : sizeVariant === "loginXL"
              ? 32
              : undefined,
        paddingBottom:
          sizeVariant === "login"
            ? 24
            : sizeVariant === "loginXL"
              ? 32
              : undefined,
      }}
    >
      <View
        className={`flex-row justify-between relative ${onLogout ? "py-2" : "py-0"} ${Platform.OS === "web" ? "items-center" : ""}`}
        style={{
          paddingLeft: isSmall ? 12 : 18,
          paddingRight: isSmall ? 12 : 18,
        }}
      >
        {/* Zona izquierda: menú + logo */}
        <View
          className={`flex-row items-center`}
          style={{ gap: isSmall ? 8 : 12, minWidth: isSmall ? 104 : 132 }}
        >
          {showMenuButton && (
            <Pressable
              onPress={onMenuPress}
              hitSlop={12}
              style={{
                width: isSmall ? 40 : 46,
                height: isSmall ? 40 : 46,
                borderRadius: 999,
                alignItems: "center",
                justifyContent: "center",
                backgroundColor: "rgba(255,255,255,0.12)",
                borderWidth: 1,
                borderColor: "rgba(255,255,255,0.16)",
                marginLeft: isSmall ? 0 : 2,
              }}
              android_ripple={{
                color: "rgba(255,255,255,0.2)",
                borderless: false,
              }}
              accessibilityLabel="Abrir menú"
            >
              <Svg
                width={isSmall ? 22 : 24}
                height={isSmall ? 22 : 24}
                viewBox="0 -960 960 960"
