  error,
  autoCorrect,
  textContentType,
  disabled, // AÃƒÂ±adido para controlar la editabilidad
  ...rest
}) {
  return (
    <View className="w-full mb-2">
      {customLabel ? (
        customLabel
      ) : (
        <Text className="text-slate-700 text-xs font-semibold mb-1 uppercase tracking-wide">
          {label}
        </Text>
      )}
      <View>
        <TextInput
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          keyboardType={keyboardType}
          autoCapitalize={autoCapitalize}
          autoComplete={autoComplete}
          autoCorrect={autoCorrect}
          secureTextEntry={secureTextEntry}
          textContentType={textContentType}
          placeholderTextColor="#9ca3af"
          className={`border border-slate-300 rounded-xl px-4 py-3 text-slate-900 ${disabled ? "bg-slate-100 opacity-60" : "bg-white"}`}
          editable={!disabled} // Controla si el TextInput es editable
          {...rest}
        />
        {!!error && (
          <Text className="text-red-600 text-xs mt-1 absolute -bottom-4 left-1">
            {error}
          </Text>
        )}
      </View>
    </View>
  );
}

const COMMON_DOMAINS = [
  "gmail.com",
  "hotmail.com",
  "outlook.com",
  "yahoo.com",
  "icloud.com",
];

const MUNICIPIOS = [
  { label: "San Juan Bautista Tuxtepec", value: "San Juan Bautista Tuxtepec" },
  {
    label: "San Juan Bautista Valle Nacional",
    value: "San Juan Bautista Valle Nacional",
  },
  { label: "Santa MarÃƒÂ­a Jacatepec", value: "Santa MarÃƒÂ­a Jacatepec" },
  { label: "San JosÃƒÂ© Chiltepec", value: "San JosÃƒÂ© Chiltepec" },
  { label: "Ayotzintepec", value: "Ayotzintepec" },
  { label: "Loma Bonita", value: "Loma Bonita" },
  { label: "San Lucas OjitlÃƒÂ¡n", value: "San Lucas OjitlÃƒÂ¡n" },
  { label: "Otro", value: "Otro" },
];

export default function RegistroAsesor({
  asesorToEdit,
  onFormClose,
  viewOnly = false,
}) {
  const { width, height } = useWindowDimensions();
  const isSmall = width < 640;
  const isLandscape = width > height && Platform.OS !== "web";
  const isTablet = width >= 640 && width < 1024;
  // Anclar el contenido arriba; en tablets solo damos un poco mÃƒÂ¡s de padding top
  const contentStyle = {
    padding: 16,
    paddingBottom: 0, // Asegura que el contenido llene el espacio vertical
    ...(isTablet ? { paddingTop: 24 } : {}),
  };
  // Medir el alto del bloque de tÃƒÂ­tulo y centrar SOLO el formulario en tablets
  const [titleHeight, setTitleHeight] = useState(0);

  const initialFormState = {
    nombre_asesor: "",
    desc_asesor: "",
    correo_asesor: "",
    telefono_asesor: "",
    direccion_asesor: "",
    municipio_asesor: "",
    rfc_asesor: "",
    nacionalidad_asesor: "Mexicana",
    genero_asesor: "",
  };

  const [form, setForm] = useState(initialFormState);
  const originalFormRef = useRef(null);
  const [editableFields, setEditableFields] = useState({});
  const [showDomainSuggestions, setShowDomainSuggestions] = useState(false);
  const [domainSuggestions, setDomainSuggestions] = useState([]);
  const emailInputContainerRef = useRef(null);
  const [isOtroMunicipio, setIsOtroMunicipio] = useState(false);
  const [emailInputLayout, setEmailInputLayout] = useState(null);

  const [isPreviewVisible, setIsPreviewVisible] = useState(false);
  useEffect(() => {
    // Si recibimos un asesor para editar, llenamos el formulario
    if (asesorToEdit) {
      // Sanitizar null/undefined a string vacÃƒÂ­o para que los inputs no reciban null
      const sanitized = {};
      for (const [key, val] of Object.entries(asesorToEdit)) {
        sanitized[key] = val ?? "";
      }
      setForm({ ...initialFormState, ...sanitized });
      originalFormRef.current = { ...initialFormState, ...sanitized };

      const checkAvatar = async () => {
        try {
          const fileName = `${asesorToEdit.id_asesor}.png`;
          const { data: files, error } = await supabase.storage
            .from("AvatarAsesor")
            .list("public");

          if (!error && files) {
            const hasAvatar = files.some((f) => f.name === fileName);
            if (hasAvatar) {
              const { data } = supabase.storage
                .from("AvatarAsesor")
                .getPublicUrl(`public/${fileName}`);
              if (data) {
                setForm((f) => ({ ...f, avatar_url: `${data.publicUrl}?t=${Date.now()}` }));
              }
            } else {
              setForm((f) => ({ ...f, avatar_url: "" }));
            }
          } else {
            setForm((f) => ({ ...f, avatar_url: "" }));
          }
        } catch (err) {
          console.error("Error checking avatar:", err);
          setForm((f) => ({ ...f, avatar_url: "" }));
        }
      };

      checkAvatar();

      // Inicializar todos los campos como no editables en modo ediciÃƒÂ³n
      const isCustomMunicipio =
        asesorToEdit.municipio_asesor &&
        !MUNICIPIOS.some((m) => m.value === asesorToEdit.municipio_asesor);
      if (isCustomMunicipio) {
        setIsOtroMunicipio(true);
      }

      const initialEditableState = Object.keys(initialFormState).reduce(
        (acc, key) => {
          acc[key] = true;
          return acc;
        },
        {},
      );
      setEditableFields(initialEditableState);
    }
    // Si no hay asesorToEdit, el formulario estÃƒÂ¡ vacÃƒÂ­o y todos los campos son editables por defecto (o no controlados por editableFields)
  }, [asesorToEdit]);

  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState({ type: "", msg: "" });
  const [fieldErrors, setFieldErrors] = useState({});
  const [genderOpen, setGenderOpen] = useState(false);
  const genderAnchorRef = useRef(null);
  const [genderMenuPos, setGenderMenuPos] = useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
  });
  const [municipioOpen, setMunicipioOpen] = useState(false);
  const municipioAnchorRef = useRef(null);
  const [municipioMenuPos, setMunicipioMenuPos] = useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
  });

  const set = (key) => (value) => setForm((f) => ({ ...f, [key]: value }));

  // Helper para renderizar el label con el botÃƒÂ³n de editar
  const pickImage = async () => {
    if (viewOnly) return;

    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== "granted") {
      notifyError("Necesitamos acceso a tu galería para seleccionar una foto.");
      return;
    }

    let result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: [`images`],
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.5,
      base64: true,
    });

    if (!result.canceled) {
      const { uri, base64 } = result.assets[0];
      setForm((prevForm) => ({
        ...prevForm,
        avatar_url: uri,
        avatar_base64: base64,
      }));
    }
  };

  const handleDeleteImage = async () => {
    const ok = await confirm({
      title: "Eliminar foto de perfil",
      message: "¿Estás seguro de que quieres eliminar la foto? Esta acción no se puede deshacer.",
      confirmText: "Eliminar",
      type: "destructive",
    });
    if (!ok) return;

    if (asesorToEdit?.id_asesor) {
      const fileName = `${asesorToEdit.id_asesor}.png`;
      const { error } = await supabase.storage
        .from("AvatarAsesor")
        .remove([`public/${fileName}`]);

      if (error) {
        console.error("Error deleting image:", error);
        notifyError("No se pudo eliminar la imagen del servidor.");
        return;
      }
    }
    setForm((prevForm) => ({
      ...prevForm,
      avatar_url: "",
      avatar_base64: null,
    }));
  };

  const renderLabelWithEditButton = useCallback(
    ({ labelText, fieldKey }) => {
      return (
        <View className="flex-row items-center mb-1">
          <View className="flex-row items-center gap-x-2">
            <Text className="text-slate-700 text-xs font-semibold uppercase tracking-wide">
              {labelText}
            </Text>
          </View>
          {asesorToEdit &&
            !viewOnly && ( // Solo mostrar el botÃƒÂ³n de editar en modo ediciÃƒÂ³n y no en solo-lectura
              <TouchableOpacity
                onPress={() =>
                  setEditableFields((prev) => ({
                    ...prev,
                    [fieldKey]: !prev[fieldKey],
                  }))
                }
                className="ml-2 p-1 rounded-full bg-slate-100"
                hitSlop={8}
              >
                {editableFields[fieldKey] ? (
                  // Icono de Confirmar (Check)
                  <Svg
                    height="16"
                    viewBox="0 -960 960 960"
                    width="16"
                    fill="#10b981"
                  >
                    <Path d="M382-240 154-468l57-57 171 171 367-367 57 57-424 424Z" />
                  </Svg>
                ) : (
                  // Icono de Editar (LÃƒÂ¡piz)
                  <Svg
                    height="16"
                    viewBox="0 -960 960 960"
                    width="16"
                    fill="#475569"
                  >
                    <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                  </Svg>
                )}
              </TouchableOpacity>
            )}
        </View>
      );
    },
    [asesorToEdit, editableFields],
  ); // Dependencia para que se regenere si cambia el modo

  // Helpers de validaciÃƒÂ³n
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const phoneDigits = (v) => v.replace(/\D+/g, "");
  const onlyLettersSpaces = (v) =>
    /^(?=.{2,100}$)[A-Za-zÃƒÂÃƒâ€°ÃƒÂÃƒâ€œÃƒÅ¡ÃƒÅ“Ãƒâ€˜ÃƒÂ¡ÃƒÂ©ÃƒÂ­ÃƒÂ³ÃƒÂºÃƒÂ¼ÃƒÂ±'\-\.\s]+$/.test(v.trim());
  // RFC personas y morales MX
  const rfcRe =
    /^([A-Z&Ãƒâ€˜]{3,4})(\d{2})(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])[A-Z\d]{3}$/;

  const validateRFC = (rfc) => {
    // RFC es opcional Ã¢â‚¬â€ solo validamos el formato si se ingresa algo
    if (!rfc) return "";
    const upper = rfc.toUpperCase();
    if (!rfcRe.test(upper)) return "RFC invÃƒÂ¡lido (formato incorrecto)";
    return "";
  };

  const validators = useMemo(
    () => ({
      nombre_asesor: (v) =>
        !v.trim()
          ? "Ingresa el nombre"
          : !onlyLettersSpaces(v)
            ? "Solo letras y espacios"
            : "",
      correo_asesor: (v) =>
        !v.trim()
          ? "Ingresa el correo"
          : emailRe.test(v.trim())
            ? ""
            : "Correo invÃƒÂ¡lido",
      telefono_asesor: (v) => {
        const d = phoneDigits(v);
        if (!d) return "Ingresa el telÃƒÂ©fono";
        return d.length === 10 ? "" : "TelÃƒÂ©fono debe tener 10 dÃƒÂ­gitos";
      },
      direccion_asesor: (v) =>
        v && v.trim().length < 5 ? "DirecciÃƒÂ³n demasiado corta" : "",
      municipio_asesor: (v) =>
        v && !onlyLettersSpaces(v) ? "Usa solo letras y espacios" : "",
      rfc_asesor: (v) => validateRFC(v),
      nacionalidad_asesor: (v) =>
        v && !onlyLettersSpaces(v) ? "Usa solo letras y espacios" : "",
      genero_asesor: (v) => (!v ? "Selecciona el gÃƒÂ©nero" : ""),
    }),
    [asesorToEdit], // Dependencia para que se regenere al cambiar de modo
  );

  const formatPhoneNumber = (value) => {
    if (!value) return "";
    // Limpiamos todo lo que no sea un dÃƒÂ­gito
    const phoneNumber = value.replace(/[^\d]/g, "");
    const phoneNumberLength = phoneNumber.length;

    if (phoneNumberLength < 4) return phoneNumber;

    if (phoneNumberLength < 7) {
      return `${phoneNumber.slice(0, 3)} ${phoneNumber.slice(3)}`;
    }

    return `${phoneNumber.slice(0, 3)} ${phoneNumber.slice(3, 6)} ${phoneNumber.slice(6, 10)}`;
  };

  const validateField = useCallback(
    async (key, valueOverride) => {
      const value = valueOverride ?? form[key];
      const fn = validators[key];
      if (!fn) return true;
      const msg = fn(value, form);
      setFieldErrors((e) => ({ ...e, [key]: msg }));
      // chequeo de duplicado para correo al salir del campo
      if (key === "correo_asesor" && !msg && value) {
        // Solo buscar duplicados si el correo es sintÃƒÂ¡cticamente vÃƒÂ¡lido y no estÃƒÂ¡ vacÃƒÂ­o
        const email = String(value).trim().toLowerCase();
        let query = supabase
          .from("asesores")
          .select("id_asesor", { count: "exact", head: true })
          .eq("correo_asesor", email);

        // Si estamos editando, excluimos el ID del asesor actual de la bÃƒÂºsqueda
        if (asesorToEdit?.id_asesor) {
          query = query.not("id_asesor", "eq", asesorToEdit.id_asesor);
        }

        const { count, error } = await query;
        if (error) console.error("Error checking duplicate email:", error);

        if ((count ?? 0) > 0) {
          setFieldErrors((e) => ({
            ...e,
            correo_asesor: "Este correo ya existe",
          }));
          return false; // Indica que la validaciÃƒÂ³n fallÃƒÂ³
        }
      }
      return !msg;
    },
    [form, validators, asesorToEdit],
  );

  const validateAll = useCallback(() => {
    const errs = {};
    Object.entries(validators).forEach(([k, fn]) => {
      const e = fn(form[k] ?? "", form);
      if (e) errs[k] = e;
    });
    setFieldErrors(errs);
    return Object.keys(errs).length === 0;
  }, [form, validators]);

  const onSubmit = useCallback(async () => {
    setToast({ type: "", msg: "" });
    if (!validateAll()) return;
    try {
      setSaving(true);
      const email = form.correo_asesor.trim().toLowerCase();

      // Chequeo de duplicado (similar a la validaciÃƒÂ³n de campo)
      let dupQuery = supabase
        .from("asesores")
        .select("id_asesor", { count: "exact", head: true })
        .eq("correo_asesor", email);
      if (asesorToEdit?.id_asesor) {
        dupQuery = dupQuery.not("id_asesor", "eq", asesorToEdit.id_asesor);
      }
      const { count: dupCount } = await dupQuery;
      if ((dupCount ?? 0) > 0) {
        setFieldErrors((e) => ({
          ...e,
          correo_asesor: "Este correo ya estÃƒÂ¡ registrado",
        }));
        return;
      }
      const payload = {
        nombre_asesor: (form.nombre_asesor || "").trim(),
        desc_asesor: (form.desc_asesor || "").trim() || null,
        correo_asesor: email,
        telefono_asesor: phoneDigits((form.telefono_asesor || "").trim()),
        direccion_asesor: (form.direccion_asesor || "").trim() || null,
        municipio_asesor: (form.municipio_asesor || "").trim() || null,
        rfc_asesor: (form.rfc_asesor || "").trim().toUpperCase() || null,
        nacionalidad_asesor: (form.nacionalidad_asesor || "").trim() || null,
        genero_asesor: form.genero_asesor || null,
      };

      let result;
      let advisorId = asesorToEdit?.id_asesor;

      if (asesorToEdit) {
        // Modo EdiciÃƒÂ³n
        result = await supabase
          .from("asesores")
          .update(payload)
          .eq("id_asesor", asesorToEdit.id_asesor);
      } else {
        // Modo CreaciÃƒÂ³n
        result = await supabase.from("asesores").insert(payload).select();
        if (result.data && result.data.length > 0) {
          advisorId = result.data[0].id_asesor;
        }
      }

      if (result.error) {
        console.error("Save error", result.error);
        setToast({
          type: "error",
          msg: "No se pudo guardar. Intenta de nuevo.",
        });
        return;
      }

      // Subida de imagen usando el ID del asesor como nombre de archivo
      if (
        form.avatar_base64 &&
        advisorId
      ) {
        const fileName = `${advisorId}.png`;
        const filePath = `public/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from("AvatarAsesor")
          .upload(filePath, decode(form.avatar_base64), {
            contentType: "image/png",
            upsert: true,
          });

        if (uploadError) {
          console.error("Error uploading avatar:", uploadError);
          // No bloqueamos el ÃƒÂ©xito del guardado del asesor, pero podrÃƒÂ­amos notificar
          setToast({
            type: "ok",
            msg: "Asesor guardado, pero hubo un error subiendo la imagen.",
          });
        }
      }

      setToast({
        type: "ok",
        msg: `Asesor ${asesorToEdit ? "actualizado" : "registrado"} correctamente.`,
      });
      // Solo limpiar el formulario si estamos creando un nuevo asesor
      if (!asesorToEdit) {
        setForm(initialFormState);
      }
      setFieldErrors({});
      // Si el guardado fue exitoso y hay una funciÃƒÂ³n para cerrar, la llamamos despuÃƒÂ©s de un momento
      if (onFormClose) setTimeout(() => onFormClose(), 1500);
    } finally {
      setSaving(false);
    }
  }, [form, asesorToEdit, onFormClose, validateAll, initialFormState]);

  const disabled = saving;

  return (
    <View style={{ flex: 1, backgroundColor: "#f8fafc" }}>
      <View className={`flex-1 p-[16] pb-0 ${isTablet ? "pt-[24]" : ""}`}>
        {/* TÃƒÂ­tulo en el contenedor principal (sin card que limite el diseÃƒÂ±o) */}
        <View
          className="max-w-6xl self-start"
          onLayout={(e) => setTitleHeight(e.nativeEvent.layout.height)}
        >
          {onFormClose && (
            <TouchableOpacity
              onPress={() => {
                let hasChanges = false;
                if (originalFormRef.current) {
                  // Modo EdiciÃƒÂ³n: Comparamos los campos editables
                  const fieldsToCheck = [
                    "nombre_asesor",
                    "desc_asesor",
                    "correo_asesor",
                    "telefono_asesor",
                    "direccion_asesor",
                    "municipio_asesor",
                    "rfc_asesor",
                    "nacionalidad_asesor",
                    "genero_asesor",
                  ];
                  for (const field of fieldsToCheck) {
                    const originalValue = String(originalFormRef.current[field] ?? "").trim();
                    const currentValue = String(form[field] ?? "").trim();
                    if (originalValue !== currentValue) {
                      hasChanges = true;
                      break;
                    }
                  }
                  
                  // Verificar si se ha seleccionado una nueva imagen
                  if (form.avatar_base64 != null) {
                    hasChanges = true;
                  }
                  
                  // Verificar si se eliminÃƒÂ³ una imagen que originalmente existÃƒÂ­a
                  const originalHasAvatar = !!originalFormRef.current.avatar_url;
                  const currentHasAvatar = !!form.avatar_url;
                  if (originalHasAvatar && !currentHasAvatar) {
                    hasChanges = true;
                  }
                } else {
                  // Modo Agregar: Comprobamos si hay algÃƒÂºn dato escrito
                  hasChanges =
                    form.nombre_asesor.trim() !== "" ||
                    form.desc_asesor.trim() !== "" ||
                    form.correo_asesor.trim() !== "" ||
                    form.telefono_asesor.trim() !== "" ||
                    form.direccion_asesor.trim() !== "" ||
                    form.municipio_asesor.trim() !== "" ||
                    form.rfc_asesor.trim() !== "" ||
                    form.genero_asesor.trim() !== "" ||
                    form.avatar_base64 != null;
                }
                onFormClose(hasChanges);
              }}
              className="flex-row items-center mb-4 opacity-80"
            >
              <Svg
                height="20"
                viewBox="0 -960 960 960"
                width="20"
                fill="#475569"
              >
                <Path d="M400-80 0-480l400-400 71 71-329 329 329 329-71 71Z" />
              </Svg>
              <Text className="text-slate-600 font-bold ml-1">
                Volver a la lista
              </Text>
            </TouchableOpacity>
          )}

          <Text className="text-slate-900 text-2xl font-extrabold">
            {viewOnly
              ? "Detalles del Asesor"
              : asesorToEdit
                ? "Editar Asesor"
                : "Registro de Asesores"}
          </Text>
          <Text className="text-slate-600">
            {viewOnly
              ? "InformaciÃƒÂ³n registrada del asesor."
              : asesorToEdit
                ? "Modifica los datos del asesor."
                : "Completa los siguientes campos."}
          </Text>
        </View>
        <Text className="text-center uppercase text-wrap text-slate-700 text-xs font-semibold tracking-wide">
          Foto de perfil
        </Text>

        {/* Bloque del formulario centrado en tablets */}
        <ScrollView
          id="formulario-asesores"
          style={{ flex: 1 }}
          className={`max-w-6xl self-center ${isLandscape ? "" : "mt-4"}`}
          keyboardShouldPersistTaps="handled"
          keyboardDismissMode="interactive"
          automaticallyAdjustKeyboardInsets
          contentContainerStyle={{ paddingBottom: 120 }}
          showsVerticalScrollIndicator={false}
        >
          {/* SecciÃƒÂ³n de la foto de perfil */}
          <View className="items-center mb-4">
            <View className="relative">
              <Pressable
                onPress={() => {
                  if (form.avatar_url) setIsPreviewVisible(true);
                  else pickImage();
                }}
              >
                {form.avatar_url ? (
                  <Image
                    source={{ uri: form.avatar_url }}
                    className="w-24 h-24 rounded-full bg-slate-200"
                  />
                ) : (
                  <View className="w-24 h-24 rounded-full bg-slate-200 justify-center items-center">
                    <Svg
                      height="48"
                      viewBox="0 -960 960 960"
                      width="48"
                      fill="#9ca3af"
                    >
                      <Path d="M480-480q-66 0-113-47t-47-113q0-66 47-113t113-47q66 0 113 47t47 113q0 66-47 113t-113 47ZM160-160v-112q0-34 17.5-62.5T224-378q62-31 126-46.5T480-440q66 0 130 15.5T736-378q29 15 46.5 43.5T800-272v112H160Z" />
                    </Svg>
                  </View>
                )}
              </Pressable>
              {!viewOnly && (
                <>
                  <Pressable
                    onPress={pickImage}
                    className="absolute bottom-0 right-0 bg-slate-700 p-2 rounded-full border-2 border-white"
                    android_ripple={{
                      color: "rgba(255,255,255,0.2)",
                      radius: 16,
                    }}
                  >
                    <Svg
                      height="16"
                      viewBox="0 -960 960 960"
                      width="16"
                      fill="#ffffff"
                    >
                      <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                    </Svg>
                  </Pressable>
                  {form.avatar_url && (
                    <Pressable
                      onPress={handleDeleteImage}
                      className="absolute top-0 right-0 bg-red-600 p-1.5 rounded-full border-2 border-white"
                      android_ripple={{
                        color: "rgba(255,255,255,0.2)",
                        radius: 14,
                      }}
