const TablaCursos = ({
  data,
  loading = false,
  query = "",
  isRefetching = false,
  onEdit,
  onDelete,
  onRefresh,
}) => {
  const [sortKey, setSortKey] = useState("id_curso");
  const [sortDir, setSortDir] = useState("asc");

  const currencyFormatter = new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  });

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const arr = data.filter((r) => {
      if (!q) return true;
      const nombre = String(r.nombre_curso || "").toLowerCase();
      const precio = String(r.costo_curso || "").toLowerCase();
      return nombre.includes(q) || precio.includes(q);
    });
    const sorted = [...arr].sort((a, b) => {
      let va = a[sortKey] ?? "";
      let vb = b[sortKey];
      if (typeof va === "string") va = va.toLowerCase();
      if (typeof vb === "string") vb = vb.toLowerCase();
      if (va < vb) return sortDir === "asc" ? -1 : 1;
      if (va > vb) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [data, query, sortKey, sortDir]);

  const SortHeader = ({ label, k, flex = 1, center }) => (
    <Pressable
      onPress={() => {
        setSortKey(k);
        setSortDir((d) =>
          sortKey === k ? (d === "asc" ? "desc" : "asc") : "asc",
        );
      }}
      className="py-3 px-3"
      style={{ flex, alignItems: center ? "center" : "flex-start" }}
      android_ripple={{ color: "rgba(0,0,0,0.05)" }}
    >
      <View className="flex-row items-center gap-1">
        <Text className="text-slate-800 font-semibold text-xs sm:text-sm uppercase tracking-wide">
          {label}
        </Text>
        {sortKey === k && (
          <Svg width={12} height={12} viewBox="0 -960 960 960" fill="#334155">
            {sortDir === "asc" ? (
              <Path d="M480-680 240-440h480L480-680Z" />
            ) : (
              <Path d="M240-520h480L480-280 240-520Z" />
            )}
          </Svg>
        )}
      </View>
    </Pressable>
  );

  return (
    <View className={`px-2 pb-4 relative flex-1`}>
      <View
        className={`rounded-xl overflow-hidden border border-slate-200 bg-white shadow-sm ${Platform.OS == "web" ? "flex-1" : ""}`}
        style={{ opacity: isRefetching ? 0.5 : 1 }}
      >
        <ScrollView
          stickyHeaderIndices={[0]}
          refreshControl={
            <RefreshControl
              refreshing={isRefetching}
              onRefresh={onRefresh}
              tintColor="#6F09EA"
            />
          }
        >
          <View className="bg-slate-100 border-b border-slate-200 flex-row">
            <SortHeader label="Nombre" k="nombre_curso" flex={1} />
            <SortHeader label="Precio" k="costo_curso" flex={0.3} />
            <SortHeader label="Acciones" k="Acciones" flex={0.2} center />
          </View>

          {filtered.length > 0 ? (
            filtered.map((r, id_curso) => (
              <Pressable
                key={r.id_curso}
                className={`flex-row items-center ${id_curso % 2 ? "bg-white" : "bg-slate-50"}`}
                android_ripple={{ color: "rgba(0,0,0,0.04)" }}
              >
                <View style={{ flex: 1 }} className="py-3 px-3">
                  <Text
                    numberOfLines={1}
                    className="text-slate-800 font-medium"
                  >
                    {r.nombre_curso}
                  </Text>
                </View>
                <View style={{ flex: 0.3 }} className="py-3 px-3">
                  <Text numberOfLines={1} className="text-slate-700">
                    {currencyFormatter.format(r.costo_curso || 0)}
                  </Text>
                </View>
                <View
                  id="celda-acciones"
                  style={{ flex: 0.2 }}
                  className="py-3 px-3"
                >
                  <View className="flex flex-row items-center justify-around">
                    <TouchableOpacity onPress={() => onEdit(r)}>
                      <Svg
                        height="22"
                        viewBox="0 -960 960 960"
                        width="22"
                        fill="#3b82f6"
                      >
                        <Path d="M200-200h56l345-345-56-56-345 345v56Zm572-403L602-771l56-56q23-23 56.5-23t56.5 23l56 56q23 23 23 56.5T849-602l-57 57Zm-58 59L290-120H120v-170l424-424 170 170Z" />
                      </Svg>
                    </TouchableOpacity>
                    <TouchableOpacity onPress={() => onDelete(r.id_curso)}>
                      <Svg
                        height="22"
                        viewBox="0 -960 960 960"
                        width="22"
                        fill="#ef4444"
                      >
                        <Path d="M280-120q-33 0-56.5-23.5T200-200v-520h-40v-80h200v-40h240v40h200v80h-40v520q0 33-23.5 56.5T680-120H280Zm400-600H280v520h400v-520ZM360-280h80v-360h-80v360Zm160 0h80v-360h-80v360ZM280-720v520-520Z" />
                      </Svg>
                    </TouchableOpacity>
                  </View>
                </View>
              </Pressable>
            ))
          ) : (
            <View className="p-8 items-center justify-center bg-white">
              <Text className="text-slate-500 text-center font-medium">
                {query
                  ? "No se encontraron cursos para tu búsqueda."
                  : "Aún no hay cursos registrados."}
              </Text>
              <Text className="text-slate-400 text-center text-sm mt-1">
                {query
                  ? "Intenta con otras palabras clave."
                  : "¡Agrega un nuevo curso para comenzar!"}
              </Text>
            </View>
          )}
        </ScrollView>
      </View>
      {isRefetching && (
        <View
          style={StyleSheet.absoluteFill}
          className="absolute inset-0 bg-white/50 flex items-center justify-center rounded-xl"
        >
          <ActivityIndicator size="large" color="#6F09EA" />
        </View>
      )}
      {loading && (
        <View
          style={StyleSheet.absoluteFill}
          className="absolute inset-0 bg-white/80 flex items-center justify-center rounded-xl"
        >
          <ActivityIndicator size="large" color="#6F09EA" />
        </View>
      )}
    </View>
  );
};

const CurrencyInput = ({ value, onChangeText, placeholder, editable }) => {
  const isEditable = editable !== false;
  const inputRef = React.useRef(null);
  const [showDecimalMenu, setShowDecimalMenu] = useState(false);
  const [customDecimal, setCustomDecimal] = useState("");

  // Separar el valor en parte entera y decimal
  const numericValue = Number(value) || 0;
  const integerPart = Math.floor(numericValue);
  const decimalPart = Math.round((numericValue - integerPart) * 100);
  const decimalDisplay = String(decimalPart).padStart(2, "0");

  const handleFocus = () => {
    if (isEditable && (value === null || value === "")) {
      onChangeText("");
    }
    setTimeout(() => inputRef.current?.setSelection(99, 99), 0);
  };

  const handleDecimalClick = () => {
    if (!isEditable) return;
    setCustomDecimal(String(decimalPart).padStart(2, "0"));
    setShowDecimalMenu(true);
  };

  const handleDecimalSelect = (decimal) => {
    const newValue = integerPart + decimal / 100;
    onChangeText(String(newValue));
    setShowDecimalMenu(false);
  };

  const handleCustomDecimalSave = () => {
    const decimal = parseInt(customDecimal) || 0;
    if (decimal >= 0 && decimal <= 99) {
      handleDecimalSelect(decimal);
    }
  };

  return (
    <>
      <View
        style={[
          styles.currencyInputContainer,
          !isEditable && styles.disabledInput,
        ]}
      >
        <Text style={styles.currencySymbol}>$</Text>
        <TextInput
          style={[
            styles.currencyInput,
            (value === "0" || value === "" || value === null) &&
            styles.currencyInputPlaceholder,
          ]}
          ref={inputRef}
          value={value === null ? "" : String(integerPart)}
          onChangeText={(text) => {
            const numericText = text.replace(/[^0-9]/g, "");
            const newValue = (Number(numericText) || 0) + decimalPart / 100;
            onChangeText(String(newValue));
          }}
          onFocus={handleFocus}
          placeholder={placeholder || "0"}
          keyboardType="number-pad"
          editable={isEditable}
        />
        <TouchableOpacity
          onPress={handleDecimalClick}
          disabled={!isEditable}
          style={{ flexDirection: "row", alignItems: "center" }}
        >
          <Text
            style={[
              styles.currencyCents,
              isEditable && { color: "#6F09EA", fontWeight: "600" },
            ]}
          >
            .{decimalDisplay}
          </Text>
        </TouchableOpacity>
      </View>

      {/* Modal de selección de decimales */}
      <Modal
        visible={showDecimalMenu}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setShowDecimalMenu(false)}
      >
        <TouchableWithoutFeedback onPress={() => setShowDecimalMenu(false)}>
          <View style={styles.decimalMenuOverlay}>
            <TouchableWithoutFeedback>
              <View style={styles.decimalMenuContainer}>
                <Text style={styles.decimalMenuTitle}>
                  Seleccionar decimales
                </Text>

                <View style={styles.decimalQuickOptions}>
                  {[0, 25, 50, 75, 99].map((decimal) => (
                    <TouchableOpacity
                      key={decimal}
                      style={[
                        styles.decimalOption,
                        decimalPart === decimal && styles.decimalOptionSelected,
                      ]}
                      onPress={() => handleDecimalSelect(decimal)}
                    >
                      <Text
                        style={[
                          styles.decimalOptionText,
                          decimalPart === decimal &&
                          styles.decimalOptionTextSelected,
                        ]}
                      >
                        .{String(decimal).padStart(2, "0")}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>

                <View style={styles.decimalCustomContainer}>
                  <Text style={styles.decimalCustomLabel}>Personalizado:</Text>
                  <View style={styles.decimalCustomInputContainer}>
                    <Text style={styles.decimalCustomDot}>.</Text>
                    <TextInput
                      style={styles.decimalCustomInput}
                      value={customDecimal}
                      onChangeText={(text) => {
                        const numeric = text.replace(/[^0-9]/g, "");
                        if (numeric.length <= 2) {
                          setCustomDecimal(numeric);
                        }
                      }}
                      keyboardType="number-pad"
                      maxLength={2}
                      placeholder="00"
                      placeholderTextColor="#9ca3af"
                    />
                  </View>
                  <TouchableOpacity
                    style={styles.decimalCustomButton}
                    onPress={handleCustomDecimalSave}
                  >
                    <Text style={styles.decimalCustomButtonText}>✓</Text>
                  </TouchableOpacity>
                </View>

                <TouchableOpacity
                  style={styles.decimalCloseButton}
                  onPress={() => setShowDecimalMenu(false)}
                >
                  <Text style={styles.decimalCloseButtonText}>Cerrar</Text>
                </TouchableOpacity>
              </View>
            </TouchableWithoutFeedback>
          </View>
        </TouchableWithoutFeedback>
      </Modal>
    </>
  );
};

const StepButton = ({ onPress, disabled, type, onPressIn, onPressOut }) => {
  const isIncrement = type === "increment";
  return (
    <TouchableOpacity
      onPress={onPress}
      onPressIn={onPressIn}
      onPressOut={onPressOut}
      disabled={disabled}
      style={[
        styles.stepButton,
        disabled && styles.stepButtonDisabled,
        isIncrement ? { marginLeft: 8 } : { marginRight: 8 },
      ]}
    >
      <Text
        style={[
          styles.stepButtonText,
          disabled && styles.stepButtonTextDisabled,
        ]}
      >
        {isIncrement ? "+" : "-"}
      </Text>
    </TouchableOpacity>
  );
};

const ChipButton = ({ label, onPress, disabled, variant, isSelected }) => (
  <TouchableOpacity
    style={[
      styles.chip,
      isSelected && styles.chipSelected,
      variant === "primary" && styles.chipPrimary,
      variant === "clear" && styles.chipClear,
      disabled && styles.chipDisabled,
    ]}
    onPress={onPress}
    disabled={disabled}
  >
    <Text
      style={[
        styles.chipText,
        isSelected && styles.chipTextSelected,
        variant === "primary" && styles.chipTextPrimary,
        variant === "clear" && styles.chipTextClear,
        disabled && styles.chipTextDisabled,
      ]}
    >
      {label}
    </Text>
  </TouchableOpacity>
);

const ChipButtonGroup = ({
  chips,
  onSelect,
  disabled,
  selectedValue,
  clearLabel,
}) => (
  <View style={styles.chipContainer}>
    {selectedValue !== null && selectedValue !== 0 && (
      <ChipButton
        label={clearLabel || "Limpiar"}
        onPress={() => onSelect(0)}
        disabled={disabled}
        variant="clear"
      />
    )}
    {chips.map((chip) => (
      <ChipButton
        key={chip.value}
        label={chip.label}
        onPress={() => {
          if (chip.value === selectedValue) {
            onSelect(0);
          } else {
            onSelect(chip.value);
          }
        }}
        isSelected={chip.value === selectedValue && chip.value !== 0}
        variant={chip.variant}
        disabled={disabled || chip.disabled}
      />
    ))}
  </View>
);

export const AddCursoForm = ({
  visible,
  onClose,
  onSave,
  isSaving,
  newCurso,
  setNewCurso,
}) => {
  const anim = useRef(new Animated.Value(0)).current;
  const intervalRef = useRef(null);
  const [liveCosto, setLiveCosto] = useState(Number(newCurso.costo_curso) || 0);

  useEffect(() => {
    Animated.timing(anim, {
      toValue: visible ? 1 : 0,
      duration: 300,
      useNativeDriver: false,
    }).start();
  }, [visible]);

  useEffect(() => {
    setLiveCosto(Number(newCurso.costo_curso) || 0);
  }, [newCurso.costo_curso]);

  const stopCounter = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  const handleCostoChange = (value) => {
    setLiveCosto(value);
    setNewCurso((c) => ({ ...c, costo_curso: String(value) }));
  };

  const formStyle = {
    opacity: anim,
    transform: [
      {
        translateY: anim.interpolate({
          inputRange: [0, 1],
          outputRange: [50, 0],
        }),
      },
    ],
  };

  if (!visible && anim._value === 0) {
    return null;
  }

  return (
    <Animated.View
      style={[formStyle, styles_addCurso.formContainer]}
    >
      <View style={styles_addCurso.formHeader}>
        <Text style={styles_addCurso.formTitle}>
          Agregar Nuevo Curso
        </Text>
        <TouchableOpacity onPress={onClose} hitSlop={10}>
          <Svg height="24" viewBox="0 -960 960 960" width="24" fill="#64748b">
            <Path d="m256-200-56-56 224-224-224-224 56-56 224 224 224-224 56 56-224 224 224 224-56 56-224-224-224 224Z" />
          </Svg>
        </TouchableOpacity>
      </View>
      <View style={styles_addCurso.inputContainer}>
        <Text style={styles.label}>Nombre del Curso</Text>
        <TextInput
          style={styles_addCurso.formInput}
          value={newCurso.nombre_curso}
          onChangeText={(text) =>
            setNewCurso((c) => ({ ...c, nombre_curso: text }))
          }
          placeholder="Ej. Curso de Verano STEAM"
          placeholderTextColor="#9ca3af"
        />
      </View>

      <Text style={styles.label}>Precio del Curso</Text>
      <View style={styles_addCurso.priceRow}>
        <StepButton
          type="decrement"
          disabled={(Number(newCurso.costo_curso) || 0) <= 0}
          onPress={() => handleCostoChange(Math.max(0, (liveCosto || 0) - 50))}
          onPressIn={() => {
            stopCounter();
            intervalRef.current = setInterval(() => {
              setLiveCosto((prev) => {
                const newValue = Math.max(0, (prev || 0) - 50);
                handleCostoChange(newValue);
                return newValue;
              });
            }, 150);
          }}
          onPressOut={stopCounter}
        />
        <View style={{ flex: 1 }}>
          <Slider
            style={{ width: "100%", height: 40 }}
            minimumValue={0}
            maximumValue={5000}
            step={50}
            value={liveCosto}
            onSlidingComplete={handleCostoChange}
            minimumTrackTintColor={"#6F09EA"}
            maximumTrackTintColor="#d1d5db"
            thumbTintColor={"#6F09EA"}
          />
        </View>
        <CurrencyInput
          value={newCurso.costo_curso}
          onChangeText={(text) => {
            const numericValue =
              text === "" ? 0 : parseInt(text.replace(/[^0-9]/g, ""), 10) || 0;
            handleCostoChange(numericValue);
          }}
        />
        <StepButton
          type="increment"
          onPress={() => handleCostoChange((liveCosto || 0) + 50)}
          onPressIn={() => {
            stopCounter();
            intervalRef.current = setInterval(() => {
              setLiveCosto((prev) => {
                const newValue = (prev || 0) + 50;
                handleCostoChange(newValue);
                return newValue;
              });
            }, 150);
          }}
          onPressOut={stopCounter}
        />
      </View>
      <ChipButtonGroup
        chips={[500, 1000, 1500, 2000, 3000].map((v) => ({
          label: `$${v}`,
          value: v,
        }))}
        selectedValue={Number(newCurso.costo_curso)}
        onSelect={handleCostoChange}
      />
      <TouchableOpacity
        onPress={onSave}
        disabled={isSaving}
        style={[
          styles_addCurso.saveButton,
          isSaving ? styles_addCurso.saveButtonSaving : styles_addCurso.saveButtonNormal,
        ]}
      >
        {isSaving ? (
          <ActivityIndicator color="#fff" />
        ) : (
          <Text style={styles_addCurso.saveButtonText}>Guardar Curso</Text>
        )}
      </TouchableOpacity>
    </Animated.View>
  );
};


