const formatStudentRecord = (item) => {
  const transactionDates = Array.isArray(item.transacciones)
    ? item.transacciones
        .map((transaction) => transaction.fecha_transaction)
        .filter(Boolean)
        .sort()
    : [];
  const latestTransactionDate = transactionDates.at(-1) || null;

  return {
    id_estudiante: item.id_alumno,
    nombre_estudiante: item.nombre_alumno,
    grupo: item.grupo,
    estatus_alumno: item.estatus_alumno,
    curso_asignado: item.cursos?.nombre_curso || "Sin curso",
    fecha_inscripcion: latestTransactionDate,
  };
};

