import React, { useCallback, useRef, useState } from "react";
import {
  ActivityIndicator,
  Animated,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  useWindowDimensions,
} from "react-native";
import { createMaterialTopTabNavigator } from "@react-navigation/material-top-tabs";
import { useFocusEffect } from "@react-navigation/native";
import { Dropdown } from "react-native-element-dropdown";
import Svg, { Path } from "react-native-svg";
import { supabase } from "../../lib/supabase";
import SeccionReportes from "../reportes/SeccionReportes";
import RegistroEgreso from "./RegistroEgreso";
import RegistroIngreso from "./RegistroIngreso";
import TablaEgresos, { CustomFinanzasTabBar } from "./TablaEgresos";
import TablaIngresos from "./TablaIngresos";

const Tab = createMaterialTopTabNavigator();

const ScreenFinanzas = () => {
  const [loading, setLoading] = useState(false);
  const [ingresoRefreshTrigger, setIngresoRefreshTrigger] = useState(0);
  const [egresoRefreshTrigger, setEgresoRefreshTrigger] = useState(0);
  const [selectedIngresoDateFilter, setSelectedIngresoDateFilter] =
    useState("last_month");
  const [selectedEgresoDateFilter, setSelectedEgresoDateFilter] =
    useState("last_month");
  const [syncDateFilters, setSyncDateFilters] = useState(false);
  const [availableYears, setAvailableYears] = useState([]);
  const [loadingYears, setLoadingYears] = useState(false);
  const [isIngresoFormVisible, setIsIngresoFormVisible] = useState(false);
  const [editingIngreso, setEditingIngreso] = useState(null);
  const [isEgresoFormVisible, setIsEgresoFormVisible] = useState(false);
  const [editingEgreso, setEditingEgreso] = useState(null);
  const ingresoFormAnimation = useRef(new Animated.Value(0)).current;
  const egresoFormAnimation = useRef(new Animated.Value(0)).current;
  const { height } = useWindowDimensions();

  const fetchAvailableYears = useCallback(async () => {
    setLoadingYears(true);
    try {
      const [{ data: ingresos, error: ingresosError }, { data: egresos, error: egresosError }] =
        await Promise.all([
          supabase.from("ingresos").select("fecha_ingreso"),
          supabase.from("egresos").select("fecha_egreso, estado").eq("estado", "pagado"),
        ]);

      if (ingresosError || egresosError) {
        console.error("Error fetching years:", ingresosError || egresosError);
        return;
      }

      const currentYear = new Date().getFullYear();
      const years = new Set();

      ingresos?.forEach((item) => {
        if (item.fecha_ingreso) years.add(Number(item.fecha_ingreso.split("-")[0]));
      });

      egresos?.forEach((item) => {
        if (item.fecha_egreso) years.add(Number(item.fecha_egreso.split("-")[0]));
      });

      const sorted = [...years].sort((a, b) => b - a);
      const future = sorted
        .filter((year) => year > currentYear)
        .map((year) => ({ label: String(year), value: `year-${year}` }));
      const current = years.has(currentYear)
        ? [{ label: "Este ano", value: `year-${currentYear}` }]
        : [];
      const past = sorted
        .filter((year) => year < currentYear)
        .map((year) => ({ label: String(year), value: `year-${year}` }));

      setAvailableYears([...future, ...current, ...past]);
    } catch (error) {
      console.error("Error fetching available years:", error);
    } finally {
      setLoadingYears(false);
    }
  }, []);

  useFocusEffect(
    useCallback(() => {
      fetchAvailableYears();
    }, [fetchAvailableYears]),
  );

  const dateFilterOptions = [
    { label: "Ultimo mes", value: "last_month" },
    { label: "Ultimos 3 meses", value: "3_months_ago" },
    ...availableYears,
  ];

  const formContainerStyle = (animation) => ({
    transform: [
      {
        translateY: animation.interpolate({
          inputRange: [0, 1],
          outputRange: [height, 0],
        }),
      },
    ],
  });

  const closeIngresoForm = () => {
    Animated.timing(ingresoFormAnimation, {
      toValue: 0,
      duration: 300,
      useNativeDriver: false,
    }).start(() => {
      setIsIngresoFormVisible(false);
      setEditingIngreso(null);
      setIngresoRefreshTrigger((current) => current + 1);
    });
  };

  const closeEgresoForm = () => {
    Animated.timing(egresoFormAnimation, {
      toValue: 0,
      duration: 300,
      useNativeDriver: false,
    }).start(() => {
      setIsEgresoFormVisible(false);
      setEditingEgreso(null);
      setEgresoRefreshTrigger((current) => current + 1);
    });
  };

  const openIngresoForm = (ingreso = null) => {
    setEditingIngreso(ingreso);
    setIsIngresoFormVisible(true);
    Animated.timing(ingresoFormAnimation, {
      toValue: 1,
      duration: 300,
      useNativeDriver: false,
    }).start();
  };

  const openEgresoForm = (egreso = null) => {
    setEditingEgreso(egreso);
    setIsEgresoFormVisible(true);
    Animated.timing(egresoFormAnimation, {
      toValue: 1,
      duration: 300,
      useNativeDriver: false,
    }).start();
  };

  const isAnyFormVisible = isIngresoFormVisible || isEgresoFormVisible;

  return (
    <Tab.Navigator
      initialRouteName="Ingresos"
      tabBarPosition="top"
      tabBar={(props) => (
        <CustomFinanzasTabBar
          {...props}
          screenProps={{
            syncDateFilters,
            setSyncDateFilters,
            selectedIngresoDateFilter,
            setSelectedEgresoDateFilter,
          }}
        />
