        if (typeof left === "string") left = left.toLowerCase();
        if (typeof right === "string") right = right.toLowerCase();
        if (left < right) return sortDir === "asc" ? -1 : 1;
        if (left > right) return sortDir === "asc" ? 1 : -1;
        return 0;
