const SeccionCatalogos = ({ catalogos, setCatalogos }) => {
  const slideAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const [catalogoLayout, setCatalogoLayout] = useState(null);
  const [tarifarioLayout, setTarifarioLayout] = useState(null);
  const lastTapTimeRef = useRef(null);
  const hintAnim = useRef(new Animated.Value(0)).current;

  // Detección de orientación
  const { width, height } = useWindowDimensions();
  const isLandscape = width > height;
  const isDesktop = width >= 1200;

  const [catalogFiles, setCatalogFiles] = useState(
    () => getCachedFiles("Catalogos") || [],
  );
  const [tarifarioFiles, setTarifarioFiles] = useState(
    () => getCachedFiles("Tarifarios") || [],
  );
  const [loadingFiles, setLoadingFiles] = useState(false);

  // Lista los archivos de un bucket y devuelve las URLs públicas (estables).
  const fetchBucketFiles = async (bucket) => {
    const { data, error } = await supabase.storage
      .from(bucket)
      .list("", { sortBy: { column: "name", order: "asc" } });

    if (error || !data) return null;

    return data
      .filter((f) => f.name !== ".emptyFolderPlaceholder")
      .map((f) => {
        const { data: pub } = supabase.storage.from(bucket).getPublicUrl(f.name);
        return {
          name: f.name,
          uri: pub.publicUrl,
          isPdf: f.name.toLowerCase().endsWith(".pdf"),
        };
      });
  };

  const loadDocuments = async () => {
    // Carga híbrida: memoria → AsyncStorage → red
    const doFetch = async () => {
      const [catUrls, tarUrls] = await Promise.all([
        fetchBucketFiles("Catalogos"),
        fetchBucketFiles("Tarifarios"),
      ]);

      if (catUrls) {
        setCatalogFiles(catUrls);
        setCachedFiles("Catalogos", catUrls);
      }
      if (tarUrls) {
        setTarifarioFiles(tarUrls);
        setCachedFiles("Tarifarios", tarUrls);
      }
    };

    const result = await loadCatalogData(doFetch);

    // Si vino de caché, no mostrar spinner (ya se mostraron datos instantáneos)
    if (!result.immediate) {
      setLoadingFiles(true);
    }

    setLoadingFiles(false);

    // Precargar todas las imágenes en background para que se cacheen
    if (catalogFiles.length > 0) {
      prefetchAllThumbnails(catalogFiles);
    }
    if (tarifarioFiles.length > 0) {
      prefetchAllThumbnails(tarifarioFiles);
    }
  };

  useFocusEffect(
    useCallback(() => {
      loadDocuments();
    }, [])
  );

  const handleDoubleTap = () => {
    const now = Date.now();
    const DOUBLE_PRESS_DELAY = 300; // ms
    if (
      lastTapTimeRef.current &&
      now - lastTapTimeRef.current < DOUBLE_PRESS_DELAY
    ) {
      // Doble toque detectado
      setCatalogos((prev) => !prev);
    } else {
      lastTapTimeRef.current = now;
    }
  };

  useEffect(() => {
    if (catalogoLayout && tarifarioLayout) {
      const targetLayout = catalogos ? tarifarioLayout : catalogoLayout;
      const baseWidth = catalogoLayout.width;
      const scaleFactor = targetLayout.width / baseWidth;

      Animated.spring(slideAnim, {
        toValue: targetLayout.x,
        useNativeDriver: false,
        bounciness: 4,
      }).start();

      Animated.spring(scaleAnim, {
        toValue: scaleFactor,
        useNativeDriver: false,
        bounciness: 8,
      }).start();
    }
  }, [catalogos, catalogoLayout, tarifarioLayout]);

  // Animación para el hint de doble toque
  useFocusEffect(
    useCallback(() => {
      const sequence = Animated.sequence([
        Animated.delay(500),
        Animated.timing(hintAnim, {
          toValue: 1,
          duration: 500,
          useNativeDriver: false,
        }),
        Animated.delay(800),
        Animated.timing(hintAnim, {
          toValue: 0,
          duration: 500,
          useNativeDriver: false,
        }),
      ]);
      sequence.start();
      return () => sequence.stop();
    }, []),
  );

  const defaultCatalogImages = [
    require("../../assets/Catalogo/Catalogo-01.png"),
    require("../../assets/Catalogo/Catalogo-02.png"),
    require("../../assets/Catalogo/Catalogo-03.png"),
    require("../../assets/Catalogo/Catalogo-04.png"),
    require("../../assets/Catalogo/Catalogo-05.png"),
    require("../../assets/Catalogo/Catalogo-06.png"),
    require("../../assets/Catalogo/Catalogo-07.png"),
    require("../../assets/Catalogo/Catalogo-08.png"),
    require("../../assets/Catalogo/Catalogo-09.png"),
    require("../../assets/Catalogo/Catalogo-10.png"),
    require("../../assets/Catalogo/Catalogo-11.png"),
    require("../../assets/Catalogo/Catalogo-12.png"),
    require("../../assets/Catalogo/Catalogo-13.png"),
    require("../../assets/Catalogo/Catalogo-14.png"),
    require("../../assets/Catalogo/Catalogo-15.png"),
    require("../../assets/Catalogo/Catalogo-16.png"),
  ];

  const defaultTarifarioImages = [
    require("../../assets/Tarifario/Tarifario-1.png"),
    require("../../assets/Tarifario/Tarifario-2.png"),
    require("../../assets/Tarifario/Tarifario-3.png"),
    require("../../assets/Tarifario/Tarifario-4.png"),
    require("../../assets/Tarifario/Tarifario-5.png"),
    require("../../assets/Tarifario/Tarifario-6.png"),
    require("../../assets/Tarifario/Tarifario-7.png"),
  ];

  const imagesToShow = catalogos
    ? (tarifarioFiles.length > 0 ? tarifarioFiles : defaultTarifarioImages)
    : (catalogFiles.length > 0 ? catalogFiles : defaultCatalogImages);

  // Estado para vista de libro en desktop
  const [bookSpread, setBookSpread] = useState(0);
  const totalSpreads = Math.ceil(imagesToShow.length / 2);
  const isTablet = width >= 768 && width < 1200;

  // Estado para pantalla completa (doble clic en desktop)
  const [fullscreenPage, setFullscreenPage] = useState(null);
  const lastClickRef = useRef({ time: 0, index: -1 });

  // Detección de doble clic para desktop
  const handlePagePress = (pageIndex) => {
    const now = Date.now();
    const last = lastClickRef.current;
    if (last.index === pageIndex && now - last.time < 350) {
      // Doble clic detectado → abrir pantalla completa
      setFullscreenPage(pageIndex);
      lastClickRef.current = { time: 0, index: -1 };
    } else {
      lastClickRef.current = { time: now, index: pageIndex };
    }
  };

  const goNextSpread = () => {
    if (bookSpread < totalSpreads - 1) setBookSpread(bookSpread + 1);
  };
  const goPrevSpread = () => {
    if (bookSpread > 0) setBookSpread(bookSpread - 1);
  };

  // Swipe táctil solo en nativo (tablet/móvil)
  const swipeX = useRef(new Animated.Value(0)).current;
  const panResponder = useRef(
    Platform.OS !== "web"
      ? PanResponder.create({
          onMoveShouldSetPanResponder: (_, g) => Math.abs(g.dx) > 20,
          onPanResponderMove: (_, g) => swipeX.setValue(g.dx),
          onPanResponderRelease: (_, g) => {
            if (g.dx < -50) goNextSpread();
            else if (g.dx > 50) goPrevSpread();
            Animated.spring(swipeX, { toValue: 0, useNativeDriver: false }).start();
          },
        })
      : null
  ).current;

  const goNextSingle = () => {
    if (fullscreenPage !== null && fullscreenPage < imagesToShow.length - 1) {
      setFullscreenPage(fullscreenPage + 1);
    }
  };
  const goPrevSingle = () => {
    if (fullscreenPage !== null && fullscreenPage > 0) {
      setFullscreenPage(fullscreenPage - 1);
    }
  };

  // Resetear al cambiar de catálogo/tarifario
  useEffect(() => {
    setBookSpread(0);
    setFullscreenPage(null);
  }, [catalogos]);

  // Precargar imágenes cuando cambia la página visible
  useEffect(() => {
    if (imagesToShow.length > 0) {
      // Precargar desde la página actual + 2 más
      const startIdx = bookSpread * 2;
      prefetchImages(imagesToShow, startIdx);
    }
  }, [bookSpread, imagesToShow]);

  return (
    <View className="flex-1 bg-gradient-to-b from-slate-100 to-slate-50">
      {/* Header mejorado con cards separadas */}
      <View className={isDesktop ? "px-6 py-3" : "p-4"} style={{ backgroundColor: "rgba(255,255,255,0.8)", borderBottomWidth: 1, borderBottomColor: "#e2e8f0" }}>
        <View className="flex-row gap-3 justify-center">
          {/* Botón Catálogo */}
          <Pressable
            onPress={() => setCatalogos(false)}
            style={{
              flex: 1,
              maxWidth: isDesktop ? 140 : 180,
            }}
            android_ripple={{
              color: !catalogos
                ? "rgba(255,255,255,0.3)"
                : "rgba(111,9,234,0.1)",
              borderless: false,
              radius: 16,
            }}
          >
            {({ pressed }) => (
              <View
                style={{
                  backgroundColor: !catalogos ? "#6F09EA" : "white",
                  borderRadius: isDesktop ? 12 : 16,
                  padding: isDesktop ? 10 : 16,
                  shadowColor: !catalogos ? "#6F09EA" : "#000",
                  shadowOffset: { width: 0, height: isDesktop ? 2 : 4 },
                  shadowOpacity: !catalogos ? 0.3 : 0.1,
                  shadowRadius: !catalogos ? (isDesktop ? 6 : 12) : 4,
                  elevation: !catalogos ? (isDesktop ? 4 : 8) : 2,
                  borderWidth: !catalogos ? 0 : 2,
                  borderColor: !catalogos ? "transparent" : "#e2e8f0",
                  transform: [{ scale: !catalogos ? 1.02 : 1 }],
                  opacity: pressed ? 0.7 : 1,
                }}
              >
                <View className="items-center gap-1" style={{ gap: isDesktop ? 1 : 8 }}>
                  <View
                    style={{
                      backgroundColor: !catalogos
                        ? "rgba(255,255,255,0.2)"
                        : "#f1f5f9",
                      borderRadius: isDesktop ? 8 : 12,
                      padding: isDesktop ? 5 : 8,
                    }}
                  >
                    <Svg
                      height={isDesktop ? "22" : "28"}
                      viewBox="0 -960 960 960"
                      width={isDesktop ? "22" : "28"}
                      fill={!catalogos ? "#ffffff" : "#6F09EA"}
                    >
                      <Path d="M560-564v-68q33-14 67.5-21t72.5-7q26 0 51 4t49 10v64q-24-9-48.5-13.5T700-600q-38 0-73 9.5T560-564Zm0 220v-68q33-14 67.5-21t72.5-7q26 0 51 4t49 10v64q-24-9-48.5-13.5T700-380q-38 0-73 9t-67 27Zm0-110v-68q33-14 67.5-21t72.5-7q26 0 51 4t49 10v64q-24-9-48.5-13.5T700-490q-38 0-73 9.5T560-454ZM260-320q47 0 91.5 10.5T440-278v-394q-41-24-87-36t-93-12q-36 0-71.5 7T120-692v396q35-12 69.5-18t70.5-6Zm260 42q44-21 88.5-31.5T700-320q36 0 70.5 6t69.5 18v-396q-33-14-68.5-21t-71.5-7q-47 0-93 12t-87 36v394Zm-40 118q-48-38-104-59t-116-21q-42 0-82.5 11T100-198q-21 11-40.5-1T40-234v-482q0-11 5.5-21T62-752q46-24 96-36t102-12q58 0 113.5 15T480-740q51-30 106.5-45T700-800q52 0 102 12t96 36q11 5 16.5 15t5.5 21v482q0 23-19.5 35t-40.5 1q-37-20-77.5-31T700-240q-60 0-116 21t-104 59ZM280-494Z" />
                    </Svg>
                  </View>
                  <Text
                    style={{
                      color: !catalogos ? "#ffffff" : "#475569",
                      fontSize: isDesktop ? 12 : 15,
                      fontWeight: "700",
                      letterSpacing: 0.5,
                    }}
                  >
                    CATÁLOGO
                  </Text>
                  {!catalogos && (
                    <View
                      style={{
                        width: isDesktop ? 30 : 40,
                        height: 3,
                        backgroundColor: "white",
                        borderRadius: 2,
                        marginTop: isDesktop ? 2 : 4,
                      }}
                    />
                  )}
                </View>
              </View>
            )}
          </Pressable>

          {/* Botón Tarifario */}
          <Pressable
            onPress={() => setCatalogos(true)}
            style={{
              flex: 1,
              maxWidth: isDesktop ? 140 : 180,
            }}
            android_ripple={{
              color: catalogos
                ? "rgba(255,255,255,0.3)"
                : "rgba(111,9,234,0.1)",
              borderless: false,
              radius: 16,
            }}
          >
            {({ pressed }) => (
              <View
                style={{
                  backgroundColor: catalogos ? "#6F09EA" : "white",
                  borderRadius: isDesktop ? 12 : 16,
                  padding: isDesktop ? 10 : 16,
                  shadowColor: catalogos ? "#6F09EA" : "#000",
                  shadowOffset: { width: 0, height: isDesktop ? 2 : 4 },
                  shadowOpacity: catalogos ? 0.3 : 0.1,
                  shadowRadius: catalogos ? (isDesktop ? 6 : 12) : 4,
                  elevation: catalogos ? (isDesktop ? 4 : 8) : 2,
                  borderWidth: catalogos ? 0 : 2,
                  borderColor: catalogos ? "transparent" : "#e2e8f0",
                  transform: [{ scale: catalogos ? 1.02 : 1 }],
                  opacity: pressed ? 0.7 : 1,
                }}
              >
                <View className="items-center gap-1" style={{ gap: isDesktop ? 1 : 8 }}>
                  <View
                    style={{
                      backgroundColor: catalogos
                        ? "rgba(255,255,255,0.2)"
                        : "#f1f5f9",
                      borderRadius: isDesktop ? 8 : 12,
                      padding: isDesktop ? 5 : 8,
                    }}
                  >
                    <Svg
                      height={isDesktop ? "22" : "28"}
                      viewBox="0 -960 960 960"
                      width={isDesktop ? "22" : "28"}
                      fill={catalogos ? "#ffffff" : "#6F09EA"}
                    >
                      <Path d="M441-120v-86q-53-12-91.5-46T293-348l74-30q15 48 44.5 73t77.5 25q41 0 69.5-18.5T587-356q0-35-22-55.5T463-458q-86-27-118-64.5T313-614q0-65 42-101t86-41v-84h80v84q50 8 82.5 36.5T651-650l-74 32q-12-32-34-48t-60-16q-44 0-67 19.5T393-614q0 33 30 52t104 40q69 20 104.5 63.5T667-358q0 71-42 108t-104 46v84h-80Z" />
                    </Svg>
                  </View>
                  <Text
                    style={{
                      color: catalogos ? "#ffffff" : "#475569",
                      fontSize: isDesktop ? 12 : 15,
                      fontWeight: "700",
                      letterSpacing: 0.5,
                    }}
                  >
                    TARIFARIO
                  </Text>
                  {catalogos && (
                    <View
                      style={{
                        width: isDesktop ? 30 : 40,
                        height: 3,
                        backgroundColor: "white",
                        borderRadius: 2,
                        marginTop: isDesktop ? 2 : 4,
                      }}
                    />
                  )}
                </View>
              </View>
            )}
          </Pressable>
        </View>
      </View>

      {/* Contenedor de imágenes con efecto libro */}
      <View style={{ flex: 1, padding: isDesktop ? 8 : (isLandscape ? 8 : 16) }}>
        {loadingFiles ? (
          <View className="flex-1 justify-center items-center">
            <ActivityIndicator size="large" color="#6F09EA" />
          </View>
        ) : isDesktop ? (
          /* ===== VISTA LIBRO EN DESKTOP ===== */
          <View style={{ flex: 1, position: "relative" }}>
            <View style={{ flex: 1, flexDirection: "row", gap: 6 }}>
              {/* Página izquierda */}
              <Pressable
                style={{ flex: 1, backgroundColor: "white", borderRadius: 8, shadowColor: "#000", shadowOffset: { width: -2, height: 2 }, shadowOpacity: 0.1, shadowRadius: 6, elevation: 6, overflow: "hidden", borderWidth: 1, borderColor: "#e2e8f0", cursor: "pointer" }}
                onPress={() => imagesToShow[bookSpread * 2] && handlePagePress(bookSpread * 2)}
              >
                {imagesToShow[bookSpread * 2] ? (
                  typeof imagesToShow[bookSpread * 2] === "object" && imagesToShow[bookSpread * 2].isPdf ? (
                    <View className="items-center justify-center p-4 flex-col" style={{ flex: 1 }}>
                      <Svg height="48" viewBox="0 -960 960 960" width="48" fill="#dc2626" className="mb-3">
                        <Path d="M280-120q-33 0-56.5-23.5T200-200v-560q0-33 23.5-56.5T280-800h400l200 200v480q0 33-23.5 56.5T800-120H280Zm0-80h520v-430H640v-130H280v560Zm120-120h280v-80H400v80Zm0-120h280v-80H400v80Zm0-120h160v-80H400v80ZM280-200v-560 560Z" />
                      </Svg>
                      <Text className="text-slate-800 font-bold text-center mb-1" style={{ fontSize: 12 }} numberOfLines={2}>
                        {imagesToShow[bookSpread * 2].name}
                      </Text>
                      <TouchableOpacity
                        onPress={() => Linking.openURL(imagesToShow[bookSpread * 2].uri)}
                        style={{ paddingHorizontal: 14, paddingVertical: 6, borderRadius: 6, backgroundColor: "#4f46e5", marginTop: 8 }}
                      >
                        <Text className="text-white font-bold" style={{ fontSize: 12 }}>Ver PDF</Text>
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <LazyImage
                      source={typeof imagesToShow[bookSpread * 2] === "object" ? { uri: imagesToShow[bookSpread * 2].uri } : imagesToShow[bookSpread * 2]}
                      style={{ width: "100%", height: "100%" }}
                      resizeMode="contain"
                    />
                  )
                ) : null}
              </Pressable>

              {/* Página derecha */}
              <Pressable
                style={{ flex: 1, backgroundColor: "white", borderRadius: 8, shadowColor: "#000", shadowOffset: { width: 2, height: 2 }, shadowOpacity: 0.1, shadowRadius: 6, elevation: 6, overflow: "hidden", borderWidth: 1, borderColor: "#e2e8f0", cursor: "pointer" }}
                onPress={() => imagesToShow[bookSpread * 2 + 1] && handlePagePress(bookSpread * 2 + 1)}
              >
                {imagesToShow[bookSpread * 2 + 1] ? (
                  typeof imagesToShow[bookSpread * 2 + 1] === "object" && imagesToShow[bookSpread * 2 + 1].isPdf ? (
                    <View className="items-center justify-center p-4 flex-col" style={{ flex: 1 }}>
                      <Svg height="48" viewBox="0 -960 960 960" width="48" fill="#dc2626" className="mb-3">
                        <Path d="M280-120q-33 0-56.5-23.5T200-200v-560q0-33 23.5-56.5T280-800h400l200 200v480q0 33-23.5 56.5T800-120H280Zm0-80h520v-430H640v-130H280v560Zm120-120h280v-80H400v80Zm0-120h280v-80H400v80Zm0-120h160v-80H400v80ZM280-200v-560 560Z" />
                      </Svg>
                      <Text className="text-slate-800 font-bold text-center mb-1" style={{ fontSize: 12 }} numberOfLines={2}>
                        {imagesToShow[bookSpread * 2 + 1].name}
                      </Text>
                      <TouchableOpacity
                        onPress={() => Linking.openURL(imagesToShow[bookSpread * 2 + 1].uri)}
                        style={{ paddingHorizontal: 14, paddingVertical: 6, borderRadius: 6, backgroundColor: "#4f46e5", marginTop: 8 }}
                      >
                        <Text className="text-white font-bold" style={{ fontSize: 12 }}>Ver PDF</Text>
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <LazyImage
                      source={typeof imagesToShow[bookSpread * 2 + 1] === "object" ? { uri: imagesToShow[bookSpread * 2 + 1].uri } : imagesToShow[bookSpread * 2 + 1]}
                      style={{ width: "100%", height: "100%" }}
                      resizeMode="contain"
                    />
                  )
                ) : null}
              </Pressable>
            </View>

            {/* Flechas flotantes */}
            <Pressable
              onPress={goPrevSpread}
              disabled={bookSpread === 0}
              style={{ position: "absolute", left: 12, top: "50%", marginTop: -24, width: 48, height: 48, borderRadius: 24, backgroundColor: bookSpread === 0 ? "#e2e8f0" : "#6F09EA", alignItems: "center", justifyContent: "center", opacity: bookSpread === 0 ? 0.35 : 1, zIndex: 10, shadowColor: "#000", shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.25, shadowRadius: 6 }}
            >
              <Svg height="24" viewBox="0 0 24 24" width="24" fill={bookSpread === 0 ? "#94a3b8" : "#ffffff"}>
                <Path d="M15.41 7.41 14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
              </Svg>
            </Pressable>
            <Pressable
              onPress={goNextSpread}
              disabled={bookSpread >= totalSpreads - 1}
              style={{ position: "absolute", right: 12, top: "50%", marginTop: -24, width: 48, height: 48, borderRadius: 24, backgroundColor: bookSpread >= totalSpreads - 1 ? "#e2e8f0" : "#6F09EA", alignItems: "center", justifyContent: "center", opacity: bookSpread >= totalSpreads - 1 ? 0.35 : 1, zIndex: 10, shadowColor: "#000", shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.25, shadowRadius: 6 }}
            >
              <Svg height="24" viewBox="0 0 24 24" width="24" fill={bookSpread >= totalSpreads - 1 ? "#94a3b8" : "#ffffff"}>
                <Path d="M8.59 16.59 10 18l6-6-6-6-1.41 1.41L13.17 12z" />
              </Svg>
            </Pressable>
          </View>

        ) : isTablet ? (
          /* ===== VISTA TABLET ===== */
          <Animated.View
            style={{ flex: 1, transform: Platform.OS !== "web" ? [{ translateX: swipeX }] : [] }}
            {...(Platform.OS !== "web" && panResponder ? panResponder.panHandlers : {})}
          >
            <View style={{ flex: 1, flexDirection: "row", alignItems: "center" }}>
              {/* Flecha izquierda */}
              <Pressable
                onPress={goPrevSpread}
                disabled={bookSpread === 0}
                style={{ width: 56, height: 56, borderRadius: 28, backgroundColor: bookSpread === 0 ? "#e2e8f0" : "#6F09EA", alignItems: "center", justifyContent: "center", opacity: bookSpread === 0 ? 0.35 : 1, marginHorizontal: 8, flexShrink: 0 }}
              >
                <Svg height="28" viewBox="0 0 24 24" width="28" fill={bookSpread === 0 ? "#94a3b8" : "#ffffff"}>
                  <Path d="M15.41 7.41 14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
                </Svg>
              </Pressable>

              {/* Página actual */}
              <Pressable
                style={{ flex: 1, height: "100%", backgroundColor: "white", borderRadius: 12, shadowColor: "#000", shadowOffset: { width: 0, height: 6 }, shadowOpacity: 0.12, shadowRadius: 12, elevation: 8, borderWidth: 1, borderColor: "#e2e8f0" }}
                onPress={() => imagesToShow[bookSpread * 2] && handlePagePress(bookSpread * 2)}
              >
                {imagesToShow[bookSpread * 2] ? (
                  typeof imagesToShow[bookSpread * 2] === "object" && imagesToShow[bookSpread * 2].isPdf ? (
                    <View className="items-center justify-center p-6 flex-col" style={{ flex: 1 }}>
                      <Svg height="56" viewBox="0 -960 960 960" width="56" fill="#dc2626" className="mb-3">
                        <Path d="M280-120q-33 0-56.5-23.5T200-200v-560q0-33 23.5-56.5T280-800h400l200 200v480q0 33-23.5 56.5T800-120H280Zm0-80h520v-430H640v-130H280v560Zm120-120h280v-80H400v80Zm0-120h280v-80H400v80Zm0-120h160v-80H400v80ZM280-200v-560 560Z" />
                      </Svg>
                      <Text className="text-slate-800 font-bold text-center mb-1" style={{ fontSize: 14 }} numberOfLines={2}>
                        {imagesToShow[bookSpread * 2].name}
                      </Text>
                      <TouchableOpacity
                        onPress={() => Linking.openURL(imagesToShow[bookSpread * 2].uri)}
                        style={{ paddingHorizontal: 18, paddingVertical: 8, borderRadius: 8, backgroundColor: "#4f46e5", marginTop: 10 }}
                      >
                        <Text className="text-white font-bold" style={{ fontSize: 14 }}>Ver PDF</Text>
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <LazyImage
                      source={typeof imagesToShow[bookSpread * 2] === "object" ? { uri: imagesToShow[bookSpread * 2].uri } : imagesToShow[bookSpread * 2]}
                      style={{ width: "100%", height: "100%" }}
                      resizeMode="contain"
                    />
                  )
                ) : null}
              </Pressable>

              {/* Flecha derecha */}
              <Pressable
                onPress={goNextSpread}
                disabled={bookSpread >= totalSpreads - 1}
                style={{ width: 56, height: 56, borderRadius: 28, backgroundColor: bookSpread >= totalSpreads - 1 ? "#e2e8f0" : "#6F09EA", alignItems: "center", justifyContent: "center", opacity: bookSpread >= totalSpreads - 1 ? 0.35 : 1, marginHorizontal: 8, flexShrink: 0 }}
              >
                <Svg height="28" viewBox="0 0 24 24" width="28" fill={bookSpread >= totalSpreads - 1 ? "#94a3b8" : "#ffffff"}>
                  <Path d="M8.59 16.59 10 18l6-6-6-6-1.41 1.41L13.17 12z" />
                </Svg>
              </Pressable>
            </View>
            {/* Indicador */}
            <View style={{ flexDirection: "row", justifyContent: "center", paddingVertical: 8, gap: 6 }}>
              {imagesToShow.map((_, i) => (
                <View key={i} style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: Math.floor(i / 2) === bookSpread ? "#6F09EA" : "#cbd5e1" }} />
              ))}
            </View>
          </Animated.View>

        ) : (
          /* ===== VISTA TAB EN MÓVIL ===== */
          <Tab.Navigator
            key={catalogos ? "tarifario" : "catalogo"}
            tabBarPosition="bottom"
            tabBar={(props) => <MinimalistTabBar {...props} />}
            lazy={true}
            lazyPreloadNumScreens={1}
          >
            {imagesToShow.map((imageSource, index) => (
              <Tab.Screen key={index} name={`Página ${index + 1}`}>
                {() => (
                  <Pressable
                    onPress={handleDoubleTap}
                    className="flex-1 items-center justify-center"
                  >
                    <View
                      style={{
                        width: isLandscape ? "98%" : "95%",
                        height: isLandscape ? "98%" : "95%",
                        backgroundColor: "white",
                        borderRadius: 16,
                        shadowColor: "#000",
                        shadowOffset: { width: 0, height: 8 },
                        shadowOpacity: 0.15,
                        shadowRadius: 16,
                        elevation: 10,
                        overflow: "hidden",
                        borderWidth: 1,
                        borderColor: "#e2e8f0",
                        justifyContent: "center",
                        alignItems: "center",
                      }}
                    >
                      {typeof imageSource === "object" && imageSource.isPdf ? (
                        <View className="items-center justify-center p-6 flex-col">
                          <Svg height={isDesktop ? "48" : "64"} viewBox="0 -960 960 960" width={isDesktop ? "48" : "64"} fill="#dc2626" className="mb-4">
                            <Path d="M280-120q-33 0-56.5-23.5T200-200v-560q0-33 23.5-56.5T280-800h400l200 200v480q0 33-23.5 56.5T800-120H280Zm0-80h520v-430H640v-130H280v560Zm120-120h280v-80H400v80Zm0-120h280v-80H400v80Zm0-120h160v-80H400v80ZM280-200v-560 560Z" />
                          </Svg>
                          <Text className="text-slate-800 font-bold text-center mb-1" style={{ fontSize: isDesktop ? 13 : 16 }} numberOfLines={2}>
                            {imageSource.name}
                          </Text>
                          <Text className="text-slate-500 text-center mb-4" style={{ fontSize: isDesktop ? 11 : 14 }}>
                            Documento PDF
                          </Text>
                          <TouchableOpacity
                            onPress={() => Linking.openURL(imageSource.uri)}
                            style={{ paddingHorizontal: isDesktop ? 16 : 24, paddingVertical: isDesktop ? 8 : 12, borderRadius: 8, backgroundColor: "#4f46e5" }}
                            className="flex-row items-center"
                          >
                            <Text className="text-white font-bold" style={{ fontSize: isDesktop ? 13 : 15 }}>Ver PDF</Text>
                          </TouchableOpacity>
                        </View>
                      ) : (
                        <LazyImage
                          source={typeof imageSource === "object" ? { uri: imageSource.uri } : imageSource}
                          style={{
                            width: "100%",
                            height: "100%",
                          }}
                          resizeMode="contain"
                        />
                      )}
                    </View>
                  </Pressable>
                )}
              </Tab.Screen>
            ))}
          </Tab.Navigator>
        )}
      </View>

      {/* Indicador de páginas en vista libro desktop */}
      {isDesktop && !loadingFiles && (
        <View style={{ paddingVertical: 10, backgroundColor: "#f8fafc", alignItems: "center" }}>
          <Text style={{ fontWeight: "bold", color: "#334155", fontSize: 14 }}>
            Página {bookSpread * 2 + 1}
            {imagesToShow[bookSpread * 2 + 1] ? `-${bookSpread * 2 + 2}` : ""}
            {" "}de {imagesToShow.length}
          </Text>
        </View>
      )}

      {/* Modal pantalla completa */}
      <Modal
        visible={fullscreenPage !== null}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setFullscreenPage(null)}
      >
        <View style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.95)", justifyContent: "center", alignItems: "center" }}>
          {/* Botón cerrar */}
          <Pressable
            onPress={() => setFullscreenPage(null)}
            style={{ position: "absolute", top: 16, right: 16, zIndex: 20, width: 44, height: 44, borderRadius: 22, backgroundColor: "rgba(255,255,255,0.15)", alignItems: "center", justifyContent: "center" }}
          >
            <Svg height="24" viewBox="0 0 24 24" width="24" fill="#ffffff">
              <Path d="M19 6.41 17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
            </Svg>
          </Pressable>

          {/* Flecha izquierda */}
          {fullscreenPage > 0 && (
            <Pressable
              onPress={goPrevSingle}
              style={{ position: "absolute", left: 16, top: "50%", marginTop: -24, width: 52, height: 52, borderRadius: 26, backgroundColor: "rgba(255,255,255,0.15)", alignItems: "center", justifyContent: "center", zIndex: 20 }}
            >
              <Svg height="28" viewBox="0 0 24 24" width="28" fill="#ffffff">
                <Path d="M15.41 7.41 14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
              </Svg>
            </Pressable>
          )}

          {/* Imagen completa */}
          {fullscreenPage !== null && imagesToShow[fullscreenPage] && (
            <LazyImage
              source={typeof imagesToShow[fullscreenPage] === "object" ? { uri: imagesToShow[fullscreenPage].uri } : imagesToShow[fullscreenPage]}
              style={{ width: "85%", height: "85%" }}
              resizeMode="contain"
            />
          )}

          {/* Flecha derecha */}
          {fullscreenPage !== null && fullscreenPage < imagesToShow.length - 1 && (
            <Pressable
              onPress={goNextSingle}
              style={{ position: "absolute", right: 16, top: "50%", marginTop: -24, width: 52, height: 52, borderRadius: 26, backgroundColor: "rgba(255,255,255,0.15)", alignItems: "center", justifyContent: "center", zIndex: 20 }}
            >
              <Svg height="28" viewBox="0 0 24 24" width="28" fill="#ffffff">
                <Path d="M8.59 16.59 10 18l6-6-6-6-1.41 1.41L13.17 12z" />
              </Svg>
            </Pressable>
          )}

          {/* Contador */}
          <View style={{ position: "absolute", bottom: 24, backgroundColor: "rgba(0,0,0,0.6)", borderRadius: 20, paddingHorizontal: 16, paddingVertical: 8 }}>
            <Text style={{ color: "#ffffff", fontWeight: "600", fontSize: 14 }}>
              {fullscreenPage !== null ? fullscreenPage + 1 : 0} / {imagesToShow.length}
            </Text>
          </View>
        </View>
      </Modal>

      {/* Hint animado mejorado */}
      <Animated.View
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: [
            { translateX: -120 },
            { translateY: -35 },
            { scale: hintAnim },
          ],
          opacity: hintAnim,
        }}
        className="bg-gradient-to-r from-purple-600 to-indigo-600 rounded-2xl p-4 flex-row items-center gap-x-3 shadow-2xl"
        pointerEvents="none"
      >
        <View className="bg-white/20 rounded-full p-2">
          <Svg height="24" viewBox="0 0 24 24" width="24" fill="white">
            <Path d="M18.5 10.5c.83 0 1.5-.67 1.5-1.5s-.67-1.5-1.5-1.5S17 8.17 17 9s.67 1.5 1.5 1.5zm-5 0c.83 0 1.5-.67 1.5-1.5S14.33 7.5 13.5 7.5 12 8.17 12 9s.67 1.5 1.5 1.5zm-5 0c.83 0 1.5-.67 1.5-1.5S9.33 7.5 8.5 7.5 7 8.17 7 9s.67 1.5 1.5 1.5zM12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8z" />
          </Svg>
        </View>
        <Text className="text-white font-bold text-base">
          Doble toque para cambiar
        </Text>
      </Animated.View>
    </View>
  );
};


