import { LineChart } from "react-native-gifted-charts";
import { Dropdown } from "react-native-element-dropdown";
import { createMaterialTopTabNavigator } from "@react-navigation/material-top-tabs";
import { useFocusEffect } from "@react-navigation/native";
import { supabase } from "../../lib/supabase";
import { useNotify } from "../../hooks/use-confirm";

const Tab = createMaterialTopTabNavigator();

const SeccionReportes = () => {
  const { notifyError } = useNotify();
  const [year, setYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1); // 1-12
  // Datos completos de los 12 meses (índice 0 = Enero, índice 11 = Diciembre)
  const [ingresosData, setIngresosData] = useState(
    Array(12).fill({ value: 0, label: "", dataPointText: "" }),
  );
  const [egresosData, setEgresosData] = useState(
    Array(12).fill({ value: 0, label: "", dataPointText: "" }),
  );
  const [estudiantesData, setEstudiantesData] = useState(
    Array(12).fill({ value: 0, label: "", dataPointText: "" }),
  );
  const [loading, setLoading] = useState(true);
  const [availableYears, setAvailableYears] = useState([]);
  const [loadingYears, setLoadingYears] = useState(false);

  // Opciones de meses
  const monthOptions = useMemo(
    () => [
      { label: "Enero", value: 1 },
      { label: "Febrero", value: 2 },
      { label: "Marzo", value: 3 },
      { label: "Abril", value: 4 },
      { label: "Mayo", value: 5 },
      { label: "Junio", value: 6 },
      { label: "Julio", value: 7 },
      { label: "Agosto", value: 8 },
      { label: "Septiembre", value: 9 },
      { label: "Octubre", value: 10 },
      { label: "Noviembre", value: 11 },
      { label: "Diciembre", value: 12 },
    ],
    [],
  );

  // Detectar orientación de la pantalla
  const { width, height } = useWindowDimensions();
  const isPortrait = height > width;

  // Memoizar currencyFormatter para evitar recrearlo en cada render
  const currencyFormatter = useMemo(
    () =>
      new Intl.NumberFormat("es-MX", {
        style: "currency",
        currency: "MXN",
      }),
    [],
  );

  // Función para cargar años disponibles desde Supabase (memoizada)
  const fetchAvailableYears = useCallback(async () => {
    setLoadingYears(true);
    try {
      // Obtener años de ingresos
      const { data: ingresos, error: ingresosError } = await supabase
        .from("ingresos")
        .select("fecha_ingreso");

      // Obtener años de egresos (solo pagados)
      const { data: egresos, error: egresosError } = await supabase
        .from("egresos")
        .select("fecha_egreso, estado")
        .eq("estado", "pagado");

      // Obtener años de transacciones (ventas)
      const { data: transacciones, error: transError } = await supabase
        .from("transacciones")
        .select("fecha_transaction");

      if (ingresosError || egresosError || transError) {
        console.error(
          "Error fetching years:",
          ingresosError || egresosError || transError,
        );
        return;
      }

      // Extraer años únicos
      const yearsSet = new Set();

      ingresos?.forEach((item) => {
        if (item.fecha_ingreso) {
          const year = item.fecha_ingreso.split("-")[0];
          yearsSet.add(parseInt(year));
        }
      });

      egresos?.forEach((item) => {
        if (item.fecha_egreso) {
          const year = item.fecha_egreso.split("-")[0];
          yearsSet.add(parseInt(year));
        }
      });

      transacciones?.forEach((item) => {
        if (item.fecha_transaction) {
          const year = item.fecha_transaction.split("-")[0];
          yearsSet.add(parseInt(year));
        }
      });

      // Convertir a array y ordenar descendente
      const yearsArray = Array.from(yearsSet)
        .sort((a, b) => b - a)
        .map((year) => ({
          label: String(year),
          value: year,
        }));

      setAvailableYears(yearsArray);
    } catch (error) {
      console.error("Error fetching available years:", error);
    } finally {
      setLoadingYears(false);
    }
  }, []);

  const fetchData = useCallback(async (selectedYear) => {
    const startDate = `${selectedYear}-01-01`;
    const endDate = `${selectedYear}-12-31`;

    try {
      // 1. Fetch Transacciones (Ventas) - Solo el anticipo es ingreso real
      const { data: transacciones, error: transError } = await supabase
        .from("transacciones")
        .select("fecha_transaction, anticipo")
        .gte("fecha_transaction", startDate)
        .lte("fecha_transaction", endDate);

      if (transError)
        console.error("Error fetching transacciones:", transError);

      // 2. Fetch Ingresos (Otros ingresos)
      const { data: ingresos, error: ingresosError } = await supabase
        .from("ingresos")
        .select("fecha_ingreso, monto_ingreso")
        .gte("fecha_ingreso", startDate)
        .lte("fecha_ingreso", endDate);

      if (ingresosError)
        console.error("Error fetching ingresos:", ingresosError);

      // 3. Fetch Egresos (Solo pagados)
      const { data: egresos, error: egresosError } = await supabase
        .from("egresos")
        .select("fecha_egreso, monto_egreso")
        .eq("estado", "pagado")
        .gte("fecha_egreso", startDate)
        .lte("fecha_egreso", endDate);

      if (egresosError) console.error("Error fetching egresos:", egresosError);

      // 4. Fetch Estudiantes registrados (tabla: alumnos, campo: fecha_inscripcion)
      const { data: estudiantes, error: estudiantesError } = await supabase
        .from("alumnos")
        .select("fecha_inscripcion")
        .gte("fecha_inscripcion", startDate)
        .lte("fecha_inscripcion", endDate);

      if (estudiantesError)
        console.error("Error fetching estudiantes:", estudiantesError);

      const monthsTemplate = Array.from({ length: 13 }, (_, i) => {
        const label = new Date(0, i).toLocaleString("es-MX", {
          month: "short",
        });

        return {
          value: 0,
          label: label,
          dataPointText: "0",
        };
      });

      const monthlyIngresos = JSON.parse(JSON.stringify(monthsTemplate));
      const monthlyEgresos = JSON.parse(JSON.stringify(monthsTemplate));
      const monthlyEstudiantes = JSON.parse(JSON.stringify(monthsTemplate));

      // Helper to parse date - Extraer mes directamente del string
      const getMonthFromDate = (dateStr) => {
        if (!dateStr) return null;
        if (typeof dateStr === "string" && dateStr.includes("-")) {
          const datePart = dateStr.split("T")[0];
          const [year, month, day] = datePart.split("-").map(Number);
          return month;
        }
        return null;
      };

      // Process Transacciones (Add to Ingresos) - Sumar solo el anticipo
      transacciones?.forEach((item) => {
        const monthIndex = getMonthFromDate(item.fecha_transaction);
        if (monthIndex !== null) {
          monthlyIngresos[monthIndex].value += item.anticipo || 0;
        }
      });

      // Process Ingresos (Add to Ingresos)
      ingresos?.forEach((item) => {
        const monthIndex = getMonthFromDate(item.fecha_ingreso);
        if (monthIndex !== null) {
          monthlyIngresos[monthIndex].value += item.monto_ingreso || 0;
        }
      });

      // Process Egresos
      egresos?.forEach((item) => {
        const monthIndex = getMonthFromDate(item.fecha_egreso);
        if (monthIndex !== null) {
          monthlyEgresos[monthIndex].value += item.monto_egreso || 0;
        }
      });

      // Process Estudiantes (Contar registros por mes)
      estudiantes?.forEach((item) => {
        const monthIndex = getMonthFromDate(item.fecha_inscripcion);
        if (monthIndex !== null) {
          monthlyEstudiantes[monthIndex].value += 1; // Contar cada estudiante
        }
      });

      // Update dataPointText
      monthlyIngresos.forEach((item) => {
        if (item) {
          item.dataPointText =
            item.value > 0 ? item.value.toLocaleString("es-MX") : "";
        }
      });
      monthlyEgresos.forEach((item) => {
        if (item) {
          item.dataPointText =
            item.value > 0 ? item.value.toLocaleString("es-MX") : "";
        }
      });
      monthlyEstudiantes.forEach((item) => {
        if (item) {
          item.dataPointText = item.value > 0 ? String(item.value) : "";
        }
      });

      // Guardar los 12 meses completos (índice 0 = Enero ... índice 11 = Diciembre)
      // El slice para la gráfica se calcula por separado en un useMemo
      setIngresosData(monthlyIngresos.slice(1, 13));
      setEgresosData(monthlyEgresos.slice(1, 13));
      setEstudiantesData(monthlyEstudiantes.slice(1, 13));
    } catch (error) {
      console.error("Error in fetchData:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleRefresh = useCallback(async () => {
    if (loading) return;
    setLoading(true);
    await fetchData(year);
  }, [loading, year, fetchData]);

  // Solo useFocusEffect, no useEffect duplicado
  useFocusEffect(
    useCallback(() => {
      const loadData = async () => {
        await fetchAvailableYears();
        setLoading(true);
        await fetchData(year);
      };
      loadData();
    }, [year]), // Solo year como dependencia
  );

  // Slice de datos para la gráfica: si es el año actual, solo hasta el mes actual;
  // si es un año anterior, los 12 meses completos.
  const chartIngresos = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth() + 1;
    if (year === currentYear) return ingresosData.slice(0, currentMonth);
    return ingresosData;
  }, [ingresosData, year]);

  const chartEgresos = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth() + 1;
    if (year === currentYear) return egresosData.slice(0, currentMonth);
    return egresosData;
  }, [egresosData, year]);

  const chartEstudiantes = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth() + 1;
    if (year === currentYear) return estudiantesData.slice(0, currentMonth);
    return estudiantesData;
  }, [estudiantesData, year]);

  // Totales anuales (solo meses disponibles para el chart)
  const totalIngresos = useMemo(
    () => chartIngresos.reduce((sum, item) => sum + item.value, 0),
    [chartIngresos],
  );
  const totalEgresos = useMemo(
    () => chartEgresos.reduce((sum, item) => sum + item.value, 0),
    [chartEgresos],
  );
  const totalEstudiantes = useMemo(
    () => chartEstudiantes.reduce((sum, item) => sum + item.value, 0),
    [chartEstudiantes],
  );

  // Calcular balance (Ingresos - Egresos)
  const balance = useMemo(
    () => totalIngresos - totalEgresos,
    [totalIngresos, totalEgresos],
  );

  // Calcular balance y totales del mes seleccionado
  // ingresosData[0] = Enero, ingresosData[selectedMonth-1] = mes seleccionado
  const balanceMesSeleccionado = useMemo(() => {
    const ingresosMes = ingresosData[selectedMonth - 1]?.value || 0;
    const egresosMes = egresosData[selectedMonth - 1]?.value || 0;
    return ingresosMes - egresosMes;
  }, [ingresosData, egresosData, selectedMonth]);

  // Calcular totales del mes seleccionado para mostrar en las gráficas
  const totalIngresosMesSeleccionado = useMemo(() => {
    return ingresosData[selectedMonth - 1]?.value || 0;
  }, [ingresosData, selectedMonth]);

  const totalEgresosMesSeleccionado = useMemo(() => {
    return egresosData[selectedMonth - 1]?.value || 0;
  }, [egresosData, selectedMonth]);

  const totalEstudiantesMesSeleccionado = useMemo(() => {
    return estudiantesData[selectedMonth - 1]?.value || 0;
  }, [estudiantesData, selectedMonth]);

  // Verificar si estamos en el mes y año actual
  const isCurrentMonthAndYear = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth() + 1;
    return year === currentYear && selectedMonth === currentMonth;
  }, [year, selectedMonth]);

  const ChartCard = React.memo(
    ({
      title,
      total,
      data,
      unit = "",
      isPortrait,
      loading,
      totalMesActual,
      monthName,
      isCurrentMonth,
    }) => (
      <View
        style={[
          styles_charts.card,
          isPortrait ? styles_charts.portrait : styles_charts.landscape,
        ]}
      >
        <View style={styles_charts.header}>
          <View style={styles_charts.titleRow}>
            <Text style={styles_charts.title}>{title}</Text>
            <Text style={styles_charts.total}>
              {totalMesActual !== null && totalMesActual !== undefined
                ? unit === "$"
                  ? currencyFormatter.format(totalMesActual)
                  : `${totalMesActual}`
                : unit === "$"
                  ? currencyFormatter.format(total)
                  : `${total} ${title.toLowerCase()}`}
            </Text>
          </View>
          {totalMesActual !== null &&
            totalMesActual !== undefined &&
            monthName && (
              <Text style={styles_charts.subtitle}>
                {monthName}
                {isCurrentMonth && " (Mes Actual)"}
              </Text>
            )}
        </View>
        {loading ? (
          <View style={styles_charts.loadingContainer}>
            <ActivityIndicator color="#6F09EA" />
          </View>
        ) : (
          <View style={{ marginLeft: isPortrait ? 45 : 43 }}>
            <LineChart
              data={data}
              spacing={isPortrait ? 55 : 43}
              thickness={3}
              hideRules
              hideYAxisText
              xAxisThickness={0}
              yAxisThickness={0}
              xAxisLabelTextStyle={{ color: "#9ca3af", fontSize: 10 }}
              noOfSections={4}
              color="#6F09EA"
              startFillColor="#a78bfa"
              endFillColor="#ffffff"
              startOpacity={0.4}
              endOpacity={0.1}
              areaChart
              dataPointsColor="#6F09EA"
              dataPointsRadius={4}
              textColor="#64748b"
              textFontSize={11}
              textShiftY={-10}
              textShiftX={-15}
              showValuesAsDataPointsText
            />
          </View>
        )}
      </View>
    ),
  );

  // Función para generar PDF del reporte
  const generateReportPDF = async () => {
    try {
      // Usar el año y mes seleccionados en los filtros
      const reportYear = year;
      const reportMonth = selectedMonth;
      const currentMonthName = monthOptions.find(
        (m) => m.value === reportMonth,
      )?.label;

      const currentDate = new Date().toLocaleDateString("es-MX", {
        year: "numeric",
        month: "long",
        day: "numeric",
      });

      // Obtener datos del año seleccionado
      const startDate = `${reportYear}-01-01`;
      const endDate = `${reportYear}-12-31`;

      // Fetch data para el año actual
      const { data: transacciones } = await supabase
        .from("transacciones")
        .select("fecha_transaction, anticipo")
        .gte("fecha_transaction", startDate)
        .lte("fecha_transaction", endDate);

      const { data: ingresos } = await supabase
        .from("ingresos")
        .select("fecha_ingreso, monto_ingreso")
        .gte("fecha_ingreso", startDate)
        .lte("fecha_ingreso", endDate);

      const { data: egresos } = await supabase
        .from("egresos")
        .select("fecha_egreso, monto_egreso, estado")
        .gte("fecha_egreso", startDate)
        .lte("fecha_egreso", endDate)
        .eq("estado", "pagado");

      // Fetch estudiantes registrados
      const { data: estudiantes } = await supabase
        .from("alumnos")
        .select("fecha_inscripcion")
        .gte("fecha_inscripcion", startDate)
        .lte("fecha_inscripcion", endDate);

      // Procesar datos por mes
      const monthlyIngresos = Array.from({ length: 13 }, (_, i) => ({
        label: i === 0 ? "" : monthOptions[i - 1]?.label || "",
        value: 0,
      }));

      const monthlyEgresos = Array.from({ length: 13 }, (_, i) => ({
        label: i === 0 ? "" : monthOptions[i - 1]?.label || "",
        value: 0,
      }));

      const monthlyEstudiantes = Array.from({ length: 13 }, (_, i) => ({
        label: i === 0 ? "" : monthOptions[i - 1]?.label || "",
        value: 0,
      }));

      // Procesar transacciones (anticipos)
      transacciones?.forEach((item) => {
        const month = parseInt(item.fecha_transaction.split("-")[1]);
        if (month >= 1 && month <= 12) {
          monthlyIngresos[month].value += item.anticipo || 0;
        }
      });

      // Procesar ingresos
      ingresos?.forEach((item) => {
        const month = parseInt(item.fecha_ingreso.split("-")[1]);
        if (month >= 1 && month <= 12) {
          monthlyIngresos[month].value += item.monto_ingreso || 0;
        }
      });

      // Procesar egresos
      egresos?.forEach((item) => {
        const month = parseInt(item.fecha_egreso.split("-")[1]);
        if (month >= 1 && month <= 12) {
          monthlyEgresos[month].value += item.monto_egreso || 0;
        }
      });

      // Procesar estudiantes (contar)
      estudiantes?.forEach((item) => {
        const month = parseInt(item.fecha_inscripcion.split("-")[1]);
        if (month >= 1 && month <= 12) {
          monthlyEstudiantes[month].value += 1; // Contar cada estudiante
        }
      });

      // Calcular totales hasta el mes seleccionado (reportMonth)
      let totalIngresosAnual = 0;
      let totalEgresosAnual = 0;
      let totalEstudiantesAnual = 0;

      for (let i = 1; i <= reportMonth; i++) {
        totalIngresosAnual += monthlyIngresos[i].value;
        totalEgresosAnual += monthlyEgresos[i].value;
        totalEstudiantesAnual += monthlyEstudiantes[i].value;
      }

      const balanceAnual = totalIngresosAnual - totalEgresosAnual;
      const ingresosMesActual = monthlyIngresos[reportMonth].value;
      const egresosMesActual = monthlyEgresos[reportMonth].value;
      const estudiantesMesActual = monthlyEstudiantes[reportMonth].value;
      const balanceMesActual = ingresosMesActual - egresosMesActual;

      // Generar tablas HTML hasta el mes seleccionado
      const ingresosTable = monthlyIngresos
        .slice(1, reportMonth + 1)
        .map((item) => {
          return `
            <tr>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0;">${item.label}</td>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0; text-align: right;">
                ${currencyFormatter.format(item.value)}
              </td>
            </tr>
          `;
        })
        .join("");

      const egresosTable = monthlyEgresos
        .slice(1, reportMonth + 1)
        .map((item) => {
          return `
            <tr>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0;">${item.label}</td>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0; text-align: right;">
                ${currencyFormatter.format(item.value)}
              </td>
            </tr>
          `;
        })
        .join("");

      const estudiantesTable = monthlyEstudiantes
        .slice(1, reportMonth + 1)
        .map((item) => {
          return `
            <tr>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0;">${item.label}</td>
              <td style="padding: 8px; border-bottom: 1px solid #e2e8f0; text-align: right;">
                ${item.value}
              </td>
            </tr>
          `;
        })
        .join("");

      // Función para generar gráfica SVG (para ingresos y egresos con $)
      const generateLineChartSVG = (data, color, label) => {
        const width = 700;
        const height = 250;
        const padding = 70; // Aumentado de 40 a 70 para acomodar números grandes
        const chartWidth = width - padding * 2;
        const chartHeight = height - padding * 2;

        const maxValue = Math.max(...data, 1);
        const stepX = chartWidth / (data.length - 1 || 1);

        // Generar puntos de la línea
        const points = data
          .map((value, index) => {
            const x = padding + index * stepX;
            const y = height - padding - (value / maxValue) * chartHeight;
            return `${x},${y}`;
          })
          .join(" ");

        // Generar path para el área rellena
        const areaPath = `
          M ${padding},${height - padding}
          L ${data
            .map((value, index) => {
              const x = padding + index * stepX;
              const y = height - padding - (value / maxValue) * chartHeight;
              return `${x},${y}`;
            })
            .join(" L ")}
          L ${padding + (data.length - 1) * stepX},${height - padding}
          Z
        `;

        return `
          <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <!-- Fondo -->
            <rect width="${width}" height="${height}" fill="#ffffff"/>
            
            <!-- Grid horizontal -->
            ${[0, 0.25, 0.5, 0.75, 1]
            .map(
              (ratio) => `
              <line 
                x1="${padding}" 
                y1="${height - padding - chartHeight * ratio}" 
                x2="${width - padding}" 
                y2="${height - padding - chartHeight * ratio}" 
                stroke="#e2e8f0" 
                stroke-width="1"
              />
              <text 
                x="${padding - 10}" 
                y="${height - padding - chartHeight * ratio + 5}" 
                text-anchor="end" 
                font-size="10" 
                fill="#64748b"
              >
                $${Math.round(maxValue * ratio).toLocaleString()}
              </text>
            `,
            )
            .join("")}
            
            <!-- Área rellena -->
            <path 
              d="${areaPath}" 
              fill="${color}" 
              fill-opacity="0.2"
            />
            
            <!-- Línea -->
            <polyline 
              points="${points}" 
              fill="none" 
              stroke="${color}" 
              stroke-width="3"
            />
            
            <!-- Puntos -->
            ${data
            .map((value, index) => {
              const x = padding + index * stepX;
              const y = height - padding - (value / maxValue) * chartHeight;
              return `
                <circle cx="${x}" cy="${y}" r="4" fill="${color}"/>
              `;
            })
            .join("")}
            
            <!-- Etiquetas del eje X -->
            ${monthlyIngresos
            .slice(1, reportMonth + 1)
            .map((item, index) => {
              const x = padding + index * stepX;
              return `
                <text 
                  x="${x}" 
                  y="${height - 10}" 
                  text-anchor="middle" 
                  font-size="10" 
                  fill="#64748b"
                >
                  ${item.label.substring(0, 3)}
                </text>
              `;
            })
            .join("")}
            
            <!-- Título -->
            <text 
              x="${width / 2}" 
              y="20" 
              text-anchor="middle" 
              font-size="14" 
              font-weight="bold" 
              fill="#1e293b"
            >
              ${label}
            </text>
          </svg>
        `;
      };

      // Función para generar gráfica SVG para estudiantes (sin símbolo $)
      const generateLineChartSVG_Students = (data, color, label) => {
        const width = 700;
        const height = 250;
        const padding = 70; // Mismo padding que la función anterior
        const chartWidth = width - padding * 2;
        const chartHeight = height - padding * 2;

        const maxValue = Math.max(...data, 1);
        const stepX = chartWidth / (data.length - 1 || 1);

        // Generar puntos de la línea
        const points = data
          .map((value, index) => {
            const x = padding + index * stepX;
            const y = height - padding - (value / maxValue) * chartHeight;
            return `${x},${y}`;
          })
          .join(" ");

        // Generar path para el área rellena
        const areaPath = `
          M ${padding},${height - padding}
          L ${data
            .map((value, index) => {
              const x = padding + index * stepX;
              const y = height - padding - (value / maxValue) * chartHeight;
              return `${x},${y}`;
            })
            .join(" L ")}
          L ${padding + (data.length - 1) * stepX},${height - padding}
          Z
        `;

        return `
          <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <!-- Fondo -->
            <rect width="${width}" height="${height}" fill="#ffffff"/>
            
            <!-- Grid horizontal -->
            ${[0, 0.25, 0.5, 0.75, 1]
            .map(
              (ratio) => `
              <line 
                x1="${padding}" 
                y1="${height - padding - chartHeight * ratio}" 
                x2="${width - padding}" 
                y2="${height - padding - chartHeight * ratio}" 
                stroke="#e2e8f0" 
                stroke-width="1"
              />
              <text 
                x="${padding - 10}" 
                y="${height - padding - chartHeight * ratio + 5}" 
                text-anchor="end" 
                font-size="10" 
                fill="#64748b"
              >
                ${Math.round(maxValue * ratio)}
              </text>
            `,
            )
            .join("")}
            
            <!-- Área rellena -->
            <path 
              d="${areaPath}" 
              fill="${color}" 
              fill-opacity="0.2"
            />
            
            <!-- Línea -->
            <polyline 
              points="${points}" 
              fill="none" 
              stroke="${color}" 
              stroke-width="3"
            />
            
            <!-- Puntos -->
            ${data
            .map((value, index) => {
              const x = padding + index * stepX;
              const y = height - padding - (value / maxValue) * chartHeight;
              return `
                <circle cx="${x}" cy="${y}" r="4" fill="${color}"/>
              `;
            })
            .join("")}
            
            <!-- Etiquetas del eje X -->
            ${monthlyIngresos
            .slice(1, reportMonth + 1)
            .map((item, index) => {
              const x = padding + index * stepX;
              return `
                <text 
                  x="${x}" 
                  y="${height - 10}" 
                  text-anchor="middle" 
                  font-size="10" 
                  fill="#64748b"
                >
                  ${item.label.substring(0, 3)}
                </text>
              `;
            })
            .join("")}
            
            <!-- Título -->
            <text 
              x="${width / 2}" 
              y="20" 
              text-anchor="middle" 
              font-size="14" 
              font-weight="bold" 
              fill="#1e293b"
            >
              ${label}
            </text>
          </svg>
        `;
      };

      // Generar SVGs de las gráficas
      const ingresosSVG = generateLineChartSVG(
        monthlyIngresos.slice(1, reportMonth + 1).map((item) => item.value),
        "#10b981",
        "Ingresos Mensuales",
      );

      const egresosSVG = generateLineChartSVG(
        monthlyEgresos.slice(1, reportMonth + 1).map((item) => item.value),
        "#ef4444",
        "Egresos Mensuales",
      );

      const estudiantesSVG = generateLineChartSVG_Students(
        monthlyEstudiantes.slice(1, reportMonth + 1).map((item) => item.value),
        "#6F09EA",
        "Estudiantes Registrados",
      );

      // Función para generar gráfica de pastel SVG
      const generatePieChartSVG = (ingresos, egresos) => {
        const width = 400;
        const height = 400;
        const centerX = width / 2;
        const centerY = height / 2;
        const radius = 120;

        const total = ingresos + egresos;
        if (total === 0) return "<svg></svg>"; // Evitar división por cero

        const ingresosPercentage = (ingresos / total) * 100;
        const egresosPercentage = (egresos / total) * 100;

        // Calcular ángulos (en grados)
        const ingresosAngle = (ingresos / total) * 360;

        // Convertir a radianes para calcular las coordenadas
        const ingresosRadians = (ingresosAngle * Math.PI) / 180;

        // Calcular puntos del arco
        const largeArcFlag = ingresosAngle > 180 ? 1 : 0;

        // Punto final del arco de ingresos
        const x1 = centerX + radius * Math.cos(-Math.PI / 2); // Inicio en la parte superior
        const y1 = centerY + radius * Math.sin(-Math.PI / 2);

        const x2 = centerX + radius * Math.cos(-Math.PI / 2 + ingresosRadians);
        const y2 = centerY + radius * Math.sin(-Math.PI / 2 + ingresosRadians);

        return `
          <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <!-- Fondo -->
            <rect width="${width}" height="${height}" fill="#ffffff"/>
            
            <!-- Título -->
            <text 
              x="${centerX}" 
              y="30" 
              text-anchor="middle" 
              font-size="16" 
              font-weight="bold" 
              fill="#1e293b"
            >
              Distribución Anual
            </text>
            
            <!-- Slice de Ingresos (verde) -->
            <path
              d="M ${centerX},${centerY}
                 L ${x1},${y1}
                 A ${radius},${radius} 0 ${largeArcFlag},1 ${x2},${y2}
                 Z"
              fill="#10b981"
              stroke="#ffffff"
              stroke-width="2"
            />
            
            <!-- Slice de Egresos (rojo) - el resto del círculo -->
            <path
              d="M ${centerX},${centerY}
                 L ${x2},${y2}
                 A ${radius},${radius} 0 ${1 - largeArcFlag},1 ${x1},${y1}
                 Z"
              fill="#ef4444"
              stroke="#ffffff"
              stroke-width="2"
            />
            
            <!-- Leyenda -->
            <g transform="translate(${centerX - 80}, ${height - 80})">
              <!-- Ingresos -->
              <rect x="0" y="0" width="20" height="20" fill="#10b981"/>
              <text x="25" y="15" font-size="12" fill="#1e293b">
                Ingresos: ${ingresosPercentage.toFixed(1)}%
              </text>
              <text x="25" y="30" font-size="11" fill="#64748b">
                ${currencyFormatter.format(ingresos)}
              </text>
              
              <!-- Egresos -->
              <rect x="0" y="40" width="20" height="20" fill="#ef4444"/>
              <text x="25" y="55" font-size="12" fill="#1e293b">
                Egresos: ${egresosPercentage.toFixed(1)}%
              </text>
              <text x="25" y="70" font-size="11" fill="#64748b">
                ${currencyFormatter.format(egresos)}
              </text>
            </g>
            
            <!-- Círculo de fondo para el texto del balance -->
            <circle 
              cx="${centerX}" 
              cy="${centerY}" 
              r="60" 
              fill="#ffffff" 
              fill-opacity="0.75"
              stroke="#e2e8f0"
              stroke-width="2"
            />
            
            <!-- Texto central con balance -->
            <text 
              x="${centerX}" 
              y="${centerY - 10}" 
              text-anchor="middle" 
              font-size="14" 
              font-weight="bold" 
              fill="#64748b"
            >
              Balance
            </text>
            <text 
              x="${centerX}" 
              y="${centerY + 15}" 
              text-anchor="middle" 
              font-size="18" 
              font-weight="bold" 
              fill="${balanceAnual >= 0 ? "#10b981" : "#ef4444"}"
            >
              ${currencyFormatter.format(balanceAnual)}
            </text>
          </svg>
        `;
      };

      // Generar gráfica de pastel
      const pieChartSVG = generatePieChartSVG(
        totalIngresosAnual,
        totalEgresosAnual,
      );

      // Función para generar gráfica de pastel de estudiantes por mes
      const generateStudentsPieChartSVG = (monthlyData) => {
        const width = 600;
        const height = 450;
        const centerX = width / 2;
        const centerY = height / 2 - 20;
        const radius = 120;

        // Obtener datos hasta el mes seleccionado
        const dataWithLabels = monthlyData
          .slice(1, reportMonth + 1)
          .map((item, index) => ({
            label: item.label,
            value: item.value,
            month: index + 1,
          }))
          .filter((item) => item.value > 0); // Solo meses con estudiantes

        const total = dataWithLabels.reduce((sum, item) => sum + item.value, 0);

        if (total === 0) {
          return `
            <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
              <rect width="${width}" height="${height}" fill="#ffffff"/>
              <text 
                x="${centerX}" 
                y="${centerY}" 
                text-anchor="middle" 
                font-size="14" 
                fill="#64748b"
              >
                No hay datos de estudiantes registrados
              </text>
            </svg>
          `;
        }

        // Colores para cada mes
        const colors = [
          "#6366f1",
          "#8b5cf6",
          "#a855f7",
          "#d946ef",
          "#ec4899",
          "#f43f5e",
          "#ef4444",
          "#f97316",
          "#f59e0b",
          "#eab308",
          "#84cc16",
          "#22c55e",
        ];

        let currentAngle = -Math.PI / 2; // Empezar desde arriba (-90 grados)
        let paths = "";
        let legends = "";

        dataWithLabels.forEach((item, index) => {
          const percentage = (item.value / total) * 100;
          const sweepAngle = (item.value / total) * 2 * Math.PI; // Ángulo en radianes
          const color = colors[index % colors.length];

          // Caso especial: si es 100%, dibujar un círculo completo
          if (percentage >= 99.9) {
            paths += `
              <circle
                cx="${centerX}"
                cy="${centerY}"
                r="${radius}"
                fill="${color}"
                stroke="#ffffff"
                stroke-width="2"
              />
            `;
          } else {
            // Punto inicial del arco
            const x1 = centerX + radius * Math.cos(currentAngle);
            const y1 = centerY + radius * Math.sin(currentAngle);

            // Punto final del arco
            const x2 = centerX + radius * Math.cos(currentAngle + sweepAngle);
            const y2 = centerY + radius * Math.sin(currentAngle + sweepAngle);

            // Flag para arcos grandes (más de 180 grados)
            const largeArcFlag = sweepAngle > Math.PI ? 1 : 0;

            // Crear path del segmento
            paths += `
              <path
                d="M ${centerX},${centerY}
                   L ${x1},${y1}
                   A ${radius},${radius} 0 ${largeArcFlag},1 ${x2},${y2}
                   Z"
                fill="${color}"
                stroke="#ffffff"
                stroke-width="2"
              />
            `;
          }

          // Crear leyenda (dos columnas)
          const legendX = index < 6 ? 50 : 320;
          const legendY = 280 + (index % 6) * 25;

          legends += `
            <rect x="${legendX}" y="${legendY}" width="15" height="15" fill="${color}"/>
            <text x="${legendX + 20}" y="${legendY + 12}" font-size="11" fill="#1e293b">
              ${item.label}: ${item.value} (${percentage.toFixed(1)}%)
            </text>
          `;

          currentAngle += sweepAngle;
        });

        return `
          <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
            <!-- Fondo -->
            <rect width="${width}" height="${height}" fill="#ffffff"/>
            
            <!-- Título -->
            <text 
              x="${centerX}" 
              y="30" 
              text-anchor="middle" 
              font-size="16" 
              font-weight="bold" 
              fill="#1e293b"
            >
              Distribución de Estudiantes
            </text>
            
            <!-- Segmentos del pastel -->
            ${paths}
            
            <!-- Círculo central con total -->
            <circle 
              cx="${centerX}" 
              cy="${centerY}" 
              r="50" 
              fill="#ffffff"
              fill-opacity="0.75"
              stroke="#e2e8f0"
              stroke-width="2"
            />
            <text 
              x="${centerX}" 
              y="${centerY - 5}" 
              text-anchor="middle" 
              font-size="12" 
              fill="#64748b"
            >
              Total
            </text>
            <text 
              x="${centerX}" 
              y="${centerY + 15}" 
              text-anchor="middle" 
              font-size="20" 
              font-weight="bold" 
              fill="#6F09EA"
            >
              ${total}
            </text>
            
            <!-- Leyenda -->
            ${legends}
          </svg>
        `;
      };

      // Generar gráfica de pastel de estudiantes
      const studentsPieChartSVG =
        generateStudentsPieChartSVG(monthlyEstudiantes);

      const html = `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <style>
            body {
              font-family: Arial, sans-serif;
              padding: 20px;
              color: #1e293b;
            }
            .header {
              text-align: center;
              margin-bottom: 30px;
              border-bottom: 3px solid #6F09EA;
              padding-bottom: 15px;
            }
            .header h1 {
              color: #6F09EA;
              margin: 0 0 5px 0;
              font-size: 28px;
            }
            .header p {
              margin: 3px 0;
              color: #64748b;
              font-size: 12px;
            }
            .balance-section {
              display: flex;
              justify-content: space-between;
              margin-bottom: 25px;
              gap: 15px;
            }
            .balance-card {
              flex: 1;
              padding: 15px;
              border-radius: 8px;
              border: 2px solid;
            }
            .balance-card.positive {
              background-color: #f0fdf4;
              border-color: #86efac;
            }
            .balance-card.negative {
              background-color: #fef2f2;
              border-color: #fca5a5;
            }
            .balance-card h3 {
              margin: 0 0 8px 0;
              font-size: 14px;
              color: #64748b;
            }
            .balance-card .amount {
              font-size: 24px;
              font-weight: bold;
              margin: 0;
            }
            .balance-card.positive .amount {
              color: #16a34a;
            }
            .balance-card.negative .amount {
              color: #dc2626;
            }
            .section {
              margin-bottom: 25px;
              page-break-inside: avoid;
            }
            .section h2 {
              color: #6F09EA;
              font-size: 18px;
              margin-bottom: 10px;
              border-bottom: 2px solid #e2e8f0;
              padding-bottom: 5px;
            }
            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 10px;
              page-break-inside: avoid;
            }
            th {
              background-color: #f1f5f9;
              padding: 10px;
              text-align: left;
              font-size: 12px;
              color: #475569;
              border-bottom: 2px solid #cbd5e1;
            }
            td {
              font-size: 12px;
              color: #1e293b;
            }
            .footer {
              margin-top: 30px;
              text-align: center;
              font-size: 10px;
              color: #94a3b8;
              border-top: 1px solid #e2e8f0;
              padding-top: 15px;
            }
            .summary {
              background-color: #f8fafc;
              padding: 15px;
              border-radius: 8px;
              margin-bottom: 20px;
            }
            .summary-row {
              display: flex;
              justify-content: space-between;
              padding: 5px 0;
              font-size: 14px;
            }
            .summary-row.total {
              font-weight: bold;
              font-size: 16px;
              border-top: 2px solid #cbd5e1;
              padding-top: 10px;
              margin-top: 5px;
            }
            .chart-container {
              margin: 20px 0;
              padding: 15px;
              background-color: #ffffff;
              border-radius: 8px;
              border: 1px solid #e2e8f0;
              page-break-inside: avoid;
            }
            .chart-container canvas {
              max-height: 300px;
            }
          </style>
        </head>
        <body>
          <div class="header">
            <p style="margin: 0; font-size: 18px; font-weight: bold; color: #6F09EA;">MQerKAcademy</p>
            <p style="margin: 0; font-size: 12px; color: #64748b; margin-bottom: 10px;">Sistema Fenix Retail</p>
            <h1>Reporte Financiero ${reportYear}</h1>
            <p>Generado el ${currentDate}</p>
            <p>Período: Enero - ${currentMonthName} ${reportYear}</p>
          </div>
          
          <div class="balance-section">
            <div class="balance-card ${balanceAnual >= 0 ? "positive" : "negative"}">
              <h3>Balance Total ${reportYear}</h3>
              <p class="amount">${currencyFormatter.format(balanceAnual)}</p>
            </div>
            <div class="balance-card ${balanceMesActual >= 0 ? "positive" : "negative"}">
              <h3>Balance ${currentMonthName}</h3>
              <p class="amount">${currencyFormatter.format(balanceMesActual)}</p>
            </div>
          </div>
          
          <div class="summary">
            <div class="summary-row">
              <span>Total Ingresos ${reportYear}:</span>
              <span>${currencyFormatter.format(totalIngresosAnual)}</span>
            </div>
            <div class="summary-row">
              <span>Total Egresos ${reportYear}:</span>
              <span>${currencyFormatter.format(totalEgresosAnual)}</span>
            </div>
            <div class="summary-row total">
              <span>Balance Anual:</span>
              <span style="color: ${balanceAnual >= 0 ? "#16a34a" : "#dc2626"}">
                ${currencyFormatter.format(balanceAnual)}
              </span>
            </div>
          </div>
          
          <div class="summary">
            <div class="summary-row">
              <span>Ingresos ${currentMonthName}:</span>
              <span>${currencyFormatter.format(ingresosMesActual)}</span>
            </div>
            <div class="summary-row">
              <span>Egresos ${currentMonthName}:</span>
              <span>${currencyFormatter.format(egresosMesActual)}</span>
            </div>
            <div class="summary-row total">
              <span>Balance ${currentMonthName}:</span>
              <span style="color: ${balanceMesActual >= 0 ? "#16a34a" : "#dc2626"}">
                ${currencyFormatter.format(balanceMesActual)}
              </span>
            </div>
          </div>
          
          <!-- Gráficas -->
          <div class="section">
            <h2>Gráficas Comparativas</h2>
            <div class="chart-container">
              ${ingresosSVG}
            </div>
            <div class="chart-container">
              ${egresosSVG}
            </div>
            <div class="chart-container">
              ${estudiantesSVG}
            </div>
            <div class="chart-container" style="display: flex; justify-content: center;">
              ${pieChartSVG}
            </div>
            <div class="chart-container" style="display: flex; justify-content: center;">
              ${studentsPieChartSVG}
            </div>
          </div>
          
          <div class="section">
            <h2>Desglose de Ingresos ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Monto</th>
                </tr>
              </thead>
              <tbody>
                ${ingresosTable}
              </tbody>
            </table>
          </div>
          
          <div class="section">
            <h2>Desglose de Egresos ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Monto</th>
                </tr>
              </thead>
              <tbody>
                ${egresosTable}
              </tbody>
            </table>
          </div>
          
          <div class="section">
            <h2>Estudiantes Registrados ${reportYear}</h2>
            <table>
              <thead>
                <tr>
                  <th>Mes</th>
                  <th style="text-align: right;">Cantidad</th>
                </tr>
              </thead>
              <tbody>
                ${estudiantesTable}
              </tbody>
            </table>
            <div style="margin-top: 15px; padding: 10px; background-color: #f1f5f9; border-radius: 6px;">
              <div style="display: flex; justify-content: space-between; font-weight: bold; color: #6F09EA;">
                <span>Total de Estudiantes Registrados:</span>
                <span>${totalEstudiantesAnual}</span>
              </div>
            </div>
          </div>
          
          <div class="footer">
            <p style="font-weight: bold; color: #6F09EA; margin-bottom: 5px;">MQerKAcademy</p>
            <p>Reporte generado automáticamente por Fenix Retail</p>
            <p>© ${new Date().getFullYear()} MQerKAcademy - Todos los derechos reservados</p>
          </div>
        </body>
        </html>
      `;

      // Generar nombre del archivo PDF
      const yearShort = reportYear.toString().slice(-2); // Últimos 2 dígitos del año
      const monthNameShort = currentMonthName.substring(0, 3); // Primeras 3 letras del mes
      const pdfFileName = `Reporte-FenixRetail_Ene-${monthNameShort}-${yearShort}.pdf`;

      const { uri } = await Print.printToFileAsync({
        html: html,
      });

      // Renombrar el archivo
      const newUri = `${FileSystem.cacheDirectory}${pdfFileName}`;
      await FileSystem.moveAsync({
        from: uri,
        to: newUri,
      });

      console.log("Reporte PDF generado en:", newUri);
      await shareAsync(newUri, {
        UTI: ".pdf",
        mimeType: "application/pdf",
        dialogTitle: pdfFileName,
      });
    } catch (error) {
      console.error("Error al generar reporte PDF:", error);
      notifyError("No se pudo generar el reporte: " + error.message);
    }
  };

  return (
    <View className="flex-1 bg-slate-50">
      <View className="p-4 pb-2">
        <View>
          {/* Header compacto con título, selectores y botón */}
          <View className="flex-row justify-between items-center gap-3 mb-4">
            <Text className="text-2xl font-bold text-slate-800">
              Reporte Anual
            </Text>

            <View className="flex-row gap-2 items-center">
              {/* Selector de Mes */}
              <View style={{ width: 130 }}>
                <Dropdown
                  style={styles_charts.dropdownIngresos}
                  data={monthOptions}
                  labelField="label"
                  valueField="value"
                  placeholder="Mes"
                  value={selectedMonth}
                  onChange={(item) => setSelectedMonth(item.value)}
                />
              </View>
              {/* Selector de Año */}
              <View style={{ width: 100 }}>
                <Dropdown
                  style={[
                    styles_charts.dropdownIngresos,
                    loadingYears && { opacity: 0.5 },
                  ]}
                  containerStyle={loadingYears && { opacity: 0.5 }}
                  data={availableYears}
                  labelField="label"
                  valueField="value"
                  placeholder={loadingYears ? "Año" : "Año"}
                  value={year}
                  onChange={(item) => setYear(item.value)}
                  disable={loadingYears}
                />
              </View>

              {/* Botón PDF */}
              <TouchableOpacity
                onPress={generateReportPDF}
                className="bg-green-600 px-3 py-2 rounded-lg flex-row items-center gap-2"
                disabled={loading}
                style={{ opacity: loading ? 0.5 : 1 }}
              >
                <Svg height="16" width="16" viewBox="0 0 512 512">
                  <Path
                    fill="#ffffff"
                    d="M378.413,0H208.297h-13.182L185.8,9.314L57.02,138.102l-9.314,9.314v13.176v265.514c0,47.36,38.528,85.895,85.896,85.895h244.811c47.353,0,85.881-38.535,85.881-85.895V85.896C464.294,38.528,425.766,0,378.413,0z M432.497,426.105c0,29.877-24.214,54.091-54.084,54.091H133.602c-29.884,0-54.098-24.214-54.098-54.091V160.591h83.716c24.885,0,45.077-20.178,45.077-45.07V31.804h170.116c29.87,0,54.084,24.214,54.084,54.092V426.105z"
                  />
                  <Path
                    fill="#ffffff"
