export default function RegistroVenta({ navigation, onFormClose }) {
  const confirm = useConfirm();
  const formProps = useRegistroVentaForm({ navigation, onFormClose });
  const {
    isLandscape,
    form,
    isSaving,
    isFormValid,
    handleClearForm,
    handleRegisterSale,
    selectedCursoInfo,
    totalFinal,
    totalConIncentivo,
  } = formProps;

  return (
    <SafeAreaView className="flex-1 bg-slate-50">
      <View className="flex-1">
        <View style={styles.header}>
          <TouchableOpacity
            className="flex flex-row justify-center"
            onPress={async () => {
              const isDirty = !equal(form, initialFormState);
              if (!isDirty) {
                onFormClose();
                return;
              }
              Keyboard.dismiss();
              const ok = await confirm({
                title: "Cambios sin guardar",
                message: "Tienes cambios sin guardar. ¿Qué deseas hacer?",
                confirmText: "Descartar",
                cancelText: "Cancelar",
                type: "destructive",
              });
              if (ok) onFormClose();
            }}
          >
            <Svg style={styles.backButton} height="24" viewBox="0 -960 960 960" width="24" fill="#475569">
              <Path d="M400-80 0-480l400-400 71 71-329 329 329 329-71 71Z" />
            </Svg>
            <Text style={styles.headerTitle}>Registrar Nueva Venta</Text>
          </TouchableOpacity>
        </View>

        <View style={{ flex: 1, flexDirection: "row" }}>
          <View style={{ flex: 3 }}>
            <View style={{ flex: 1 }}>
              <ScrollView
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode="interactive"
                automaticallyAdjustKeyboardInsets
                contentContainerStyle={[styles.scrollContent, { paddingBottom: 120 }]}
              >
                <StudentSection {...formProps} />
                <CourseSection {...formProps} />
                <PaymentSection {...formProps} />
                <DescriptionSection {...formProps} />
              </ScrollView>

              <View style={styles.actionsContainer}>
                <TouchableOpacity style={styles.clearButton} onPress={handleClearForm}>
                  <Text style={styles.clearButtonText}>Limpiar</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[
                    styles.submitButton,
                    { flex: 1 },
                    (!isFormValid || isSaving) && styles.submitButtonDisabled,
                  ]}
                  disabled={!isFormValid || isSaving}
                  onPress={handleRegisterSale}
                >
                  {isSaving ? <ActivityIndicator color="#fff" /> : <Text style={styles.submitButtonText}>Registrar Venta</Text>}
                </TouchableOpacity>
              </View>
            </View>
          </View>

          <View
            id="ticket"
            className={isLandscape ? "" : "hidden"}
            style={[styles.previewContainer, { flex: Platform.OS !== "web" ? 1.35 : 1, overflow: "hidden" }]}
          >
            <TicketPreview
              form={form}
              curso={selectedCursoInfo}
              totalFinal={totalFinal}
              totalConIncentivo={totalConIncentivo}
            />
          </View>
        </View>
      </View>
    </SafeAreaView>
  );
}

