      <div class="dashed-line"></div>

      <!-- Detalles -->
      <div style="font-size: 10px; color: #334155;">
        <div class="bold" style="font-size: 9px; color: #475569; margin-bottom: 2px;">DETALLES DE CURSO</div>
        <div class="flex-row">
          <span style="flex: 1; margin-right: 8px;">${curso.nombre_curso || "Sin curso"}</span>
          <span class="bold">${currencyFormatter.format(total)}</span>
        </div>
      </div>

      <div class="dashed-line"></div>

      <!-- Desglose de Pagos -->
      <div style="font-size: 10.5px; color: #334155;">
        <div class="flex-row">
          <span>Anticipo:</span>
          <span style="font-weight: 600;">- ${currencyFormatter.format(anticipo)}</span>
        </div>
        ${anticipo > 0 ? `
        <div class="flex-row" style="color: #ef4444;">
          <span class="bold">Pendiente:</span>
          <span class="bold">${currencyFormatter.format(pendiente)}</span>
        </div>` : ""}
        <div class="flex-row" style="margin-top: 4px; font-size: 11.5px;">
          <span class="bold">Total a Pagar:</span>
          <span class="bold" style="color: #6F09EA;">${currencyFormatter.format(total)}</span>
        </div>
      </div>

      <div class="dashed-line"></div>

      <!-- Términos e información del Ticket -->
      <div class="text-center" style="font-size: 9px; display: flex; flex-direction: column; gap: 3px;">
        <div class="bold">*CONSERVE ESTE COMPROBANTE*</div>
        <div class="bold" style="color: #334155;">PAGO REALIZADO CON EXITO</div>
        <div style="font-size: 7.5px; color: #475569; line-height: 10px; margin: 2px 0;">
          NO HAY DEVOLUCION DEL PAGO POR CUALQUIER SERVICIO PRESTADO EN NUESTRA INSTITUCIÓN
        </div>
        <div class="bold" style="color: #334155;">¡GRACIAS POR LA CONFIANZA!</div>
      </div>
    </body>
  </html>
  `;
  };

  const handleReprint = async (transaccion) => {
    try {
      if (!transaccion || !transaccion.id_transaccion) {
        notifyError("No se pudo identificar la transacción.");
        return;
      }

      setLoading(true);

      const { data: txn, error } = await supabase
        .from("transacciones")
        .select(
          `
          *,
          alumnos!fk_transacciones_alumno (nombre_alumno, grupo, direccion_alumno),
          cursos (nombre_curso, costo_curso)
        `,
        )
        .eq("id_transaccion", transaccion.id_transaccion)
        .single();

      if (error || !txn) {
        notifyError("No se pudo obtener la transacción.");
        setLoading(false);
        return;
      }

      setLoading(false);
      setSelectedTxnForReprint(txn);
      setReprintModalVisible(true);
    } catch (error) {
      console.error("Error al obtener transacción:", error);
      setLoading(false);
      notifyError("No se pudo obtener la transacción: " + error.message);
    }
  };

  const executePrint = async () => {
    if (!selectedTxnForReprint) return;

    const txn = selectedTxnForReprint;
    const alumno = txn.alumnos || {};
    const curso = txn.cursos || {};
    const fechaParts = txn.fecha_transaction.split("T")[0].split("-");
    const year = parseInt(fechaParts[0], 10);
    const paddedId = String(txn.id_transaccion).padStart(4, "0");
    const folio = `MQ-${year}-${paddedId}`;

      try {
        setLoading(true);

        // En web: abrir ticket en ventana nueva y mostrar diálogo de impresión
        if (Platform.OS === "web") {
          const logoConfig = await getTicketLogoDisplaySettings();
          const html = buildTicketHtml(txn, alumno, curso, folio, logoConfig);
        const printWindow = window.open("", "_blank", "width=400,height=600");
        if (printWindow) {
          printWindow.document.write(html);
          printWindow.document.close();
          printWindow.onload = () => {
            printWindow.print();
          };
        } else {
          notifyError("Se bloqueó la ventana emergente. Permite las ventanas emergentes para imprimir.");
        }
        setLoading(false);
        return;
      }

      // En móvil: buscar el PDF guardado en el álbum Fenix-Retail
      const ticketFileName = `Ticket-MQerKAcademy-${folio}.pdf`;

      try {
        const { status } = await MediaLibrary.requestPermissionsAsync();
        if (status !== "granted") {
          notify({
            type: "warning",
            title: "Permisos necesarios",
            message: "Se necesitan permisos para acceder a los archivos guardados.",
          });
          setLoading(false);
          return;
        }

        const album = await MediaLibrary.getAlbumAsync("Fenix-Retail");
        if (!album) {
          notify({
            type: "warning",
            title: "Álbum no encontrado",
            message: "No se encontró el álbum Fenix-Retail.",
          });
          setLoading(false);
          return;
        }

        const { assets } = await MediaLibrary.getAssetsAsync({
          album,
          first: 500,
          mediaType: "unknown",
          sortBy: [[MediaLibrary.SortBy.creationTime, false]],
        });

        const foundAsset = assets.find(
          (asset) => asset.filename === ticketFileName,
        );

        if (foundAsset) {
          await shareAsync(foundAsset.uri, {
            UTI: ".pdf",
            mimeType: "application/pdf",
            dialogTitle: ticketFileName,
          });
        } else {
          notify({
            type: "warning",
            title: "Ticket no encontrado",
            message: `No se encontró el ticket ${folio} en el álbum Fenix-Retail.`,
          });
        }
      } catch (error) {
        console.error("Error buscando archivo:", error);
        notifyError(`No se pudo acceder al archivo guardado.\n\n${error.message}`);
      }

      setLoading(false);
    } catch (error) {
      console.error("Error al reimprimir ticket:", error);
      setLoading(false);
      notifyError("No se pudo reimprimir el ticket: " + error.message);
    }
  };

  useEffect(() => {
    // Informa al componente padre si el formulario está visible para deshabilitar el swipe
    onFormToggle(isFormVisible);
  }, [isFormVisible, onFormToggle]);

  // Estilos de animación que se aplicarán al contenedor del formulario
  const formContainerStyle = {
    // El formulario se escala desde 0.95 a 1 (zoom in)
    transform: [
      {
        scale: anim.interpolate({
          inputRange: [0, 1],
          outputRange: [0.95, 1],
        }),
      },
    ],
    // El formulario se desvanece de 0 a 1
    opacity: anim,
  };

  const fetchEstudiantesConAdeudo = async () => {
    // Consultamos la tabla 'transacciones' en lugar de 'alumnos'
    // Filtramos por pendiente > 0 para obtener solo las deudas
    const { data, error } = await supabase
      .from("transacciones")
      .select(
        `
        *,
        alumnos!fk_transacciones_alumno (id_alumno, nombre_alumno, grupo, direccion_alumno, estatus_alumno),
        cursos (nombre_curso, costo_curso)
      `,
      )
      .gt("pendiente", 0) // Solo transacciones con deuda
      .order("fecha_transaction", { ascending: false }); // Ordenar por fecha más reciente

    if (!error && data) {
      const formattedData = data.map((t) => {
        // Mapeamos los datos de la transacción al formato que espera la tabla
        // Usamos los datos del alumno relacionado
        const alumno = t.alumnos || {};
        const curso = t.cursos || {};

        return {
          // Datos de la transacción como base
          id_transaccion: t.id_transaccion,
          fecha_transaction: t.fecha_transaction,
          monto_pendiente: t.pendiente,
          total: t.total,
          anticipo: t.anticipo,

          // Datos del alumno (aplanados)
          id_alumno: alumno.id_alumno, // Importante para las acciones (editar, etc.)
          nombre_alumno: alumno.nombre_alumno || "Desconocido",
          grupo: t.grupo_alumno || alumno.grupo || "Sin grupo", // Priorizamos el grupo de la transacción
          direccion_alumno: alumno.direccion_alumno,
          estatus_alumno: alumno.estatus_alumno,

          // Datos del curso
          nombre_curso: curso.nombre_curso || "Sin curso",
          costo_curso: curso.costo_curso,
        };
      });

      // Extraer años únicos de todas las transacciones
      const years = [
        ...new Set(
          formattedData
            .map((t) => {
              if (t.fecha_transaction) {
                return new Date(t.fecha_transaction).getFullYear();
              }
              return null;
            })
            .filter((y) => y !== null),
        ),
      ].sort((a, b) => b - a);

      setAvailableYears(years);
      setEstudiantesConAdeudo(formattedData);
    } else if (error) {
      console.error("Error fetching deudas:", error);
    }
    setLoading(false);
    setIsRefetching(false);
  };

  const handleRefresh = async () => {
    if (isRefetching || loading) return;
    setIsRefetching(true);
    await fetchEstudiantesConAdeudo();
  };

  useFocusEffect(
    useCallback(() => {
      if (estudiantesConAdeudo.length > 0) setIsRefetching(true);
      else setLoading(true);
      fetchEstudiantesConAdeudo();
    }, []),
  );

  const handleOpenPaymentModal = async (deuda) => {
    setSelectedDebtForPayment(deuda);
    setPaymentModalVisible(true);
    setProcessingPayment(true); // Usamos esto como loading

    try {
      // Obtener todas las transacciones del estudiante
      const { data, error } = await supabase
        .from("transacciones")
        .select(
          `
          pendiente,
          total,
          anticipo,
          curso_id,
          id_transaccion,
          fecha_transaction,
          cursos (nombre_curso)
        `,
        )
        .eq("alumno_id", deuda.id_alumno);

      if (error) throw error;

      let deudaTotal = 0;
      let pagadoTotal = 0;
      const cursosMap = new Map();

      data.forEach((t) => {
        deudaTotal += t.pendiente || 0;
        pagadoTotal +=
          (t.anticipo || 0) +
          ((t.total || 0) - (t.pendiente || 0) - (t.anticipo || 0));

        if (t.curso_id && t.cursos) {
          if (!cursosMap.has(t.curso_id)) {
            cursosMap.set(t.curso_id, {
              id: t.curso_id,
              nombre: t.cursos.nombre_curso,
              pendiente: 0,
              transacciones: [],
              fecha_transaction: t.fecha_transaction, // Guardar la primera fecha
            });
          }
          const curso = cursosMap.get(t.curso_id);
          curso.pendiente += t.pendiente || 0;
          curso.transacciones.push(t);

          // Actualizar con la fecha más reciente
          if (
            t.fecha_transaction &&
            (!curso.fecha_transaction ||
              new Date(t.fecha_transaction) > new Date(curso.fecha_transaction))
          ) {
            curso.fecha_transaction = t.fecha_transaction;
          }
        }
      });

      setStudentDetails({
        deudaTotal,
        pagadoTotal,
        cursos: Array.from(cursosMap.values()),
      });
    } catch (err) {
      console.error("Error fetching student details:", err);
      notifyError("No se pudieron cargar los detalles del estudiante.");
    } finally {
      setProcessingPayment(false);
    }
  };

  const handleOpenCoursePaymentModal = (curso) => {
    setSelectedCourseForPayment(curso);
    setPaymentAmount(0);
    setCoursePaymentModalVisible(true);
  };

  const handleProcessPayment = async () => {
    const amount = Number(paymentAmount);
    if (amount <= 0) {
      notify({
        type: "warning",
        title: "Monto inválido",
        message: "Por favor selecciona un monto válido.",
      });
      return;
    }

    if (amount > selectedCourseForPayment.pendiente) {
      notify({
        type: "warning",
        title: "Monto inválido",
        message: "El monto del abono no puede ser mayor al saldo pendiente.",
      });
      return;
    }

    setProcessingPayment(true);

    try {
      // Buscar las transacciones pendientes para este curso
      const transactions = selectedCourseForPayment.transacciones
        .filter((t) => t.pendiente > 0)
        .sort((a, b) => a.id_transaccion - b.id_transaccion);

      let remainingPayment = amount;

      for (const transaction of transactions) {
        if (remainingPayment <= 0) break;

        const paymentForThisTransaction = Math.min(
          remainingPayment,
          transaction.pendiente,
        );
        const newPendiente = transaction.pendiente - paymentForThisTransaction;

        const { error: updateError } = await supabase
          .from("transacciones")
          .update({ pendiente: newPendiente })
          .eq("id_transaccion", transaction.id_transaccion);

        if (updateError) throw updateError;

        remainingPayment -= paymentForThisTransaction;
      }

      // Registrar el abono en la tabla de ingresos
      const { error: ingresoError } = await supabase.from("ingresos").insert([
        {
          fecha_ingreso: new Date().toISOString().split("T")[0],
          monto_ingreso: amount,
          nombre_ingreso: selectedCourseForPayment.nombre,
          desc_ingreso: selectedDebtForPayment?.nombre_alumno,
        },
      ]);

      if (ingresoError) throw ingresoError;

      notifySuccess("Abono registrado correctamente.");
      setCoursePaymentModalVisible(false);
      // Recargar detalles del estudiante
      handleOpenPaymentModal(selectedDebtForPayment);
      // Recargar lista
      handleRefresh();
    } catch (error) {
      console.error("Error processing payment:", error);
      notifyError("Hubo un problema al procesar el abono.");
    } finally {
      setProcessingPayment(false);
    }
  };

  const handleCloseDebt = async (curso) => {
    const ok = await confirm({
      title: "Cerrar deuda (cliente no pagó)",
      message: `El anticipo ya fue registrado en finanzas al momento de la venta. Se cancelará el saldo pendiente de $${curso.pendiente.toLocaleString("es-MX")} del curso "${curso.nombre}" y el alumno dejará de figurar como deudor. ¿Deseas continuar?`,
      confirmText: "Cerrar deuda",
      type: "destructive",
    });

    if (!ok) return;

    setProcessingPayment(true);
    try {
      // El anticipo se contabiliza como ingreso al registrar la venta, así que aquí
      // solo cancelamos el saldo pendiente eliminando las transacciones del curso.
      const { error: deleteError } = await supabase
        .from("transacciones")
        .delete()
        .eq("alumno_id", selectedDebtForPayment.id_alumno)
        .eq("curso_id", curso.id);

      if (deleteError) throw deleteError;

      notifySuccess("La deuda ha sido cerrada. El alumno ya no figura como deudor.");

      // Cerrar modal de detalles y refrescar la lista general
      setPaymentModalVisible(false);
      handleRefresh();
    } catch (err) {
      console.error("Error al cerrar la deuda:", err);
      notifyError("Hubo un problema al cerrar la deuda.");
    } finally {
      setProcessingPayment(false);
    }
  };

  return (
    <View style={styles_ventas.container}>
      {loading ? (
        <View style={styles_ventas.loadingContainer}>
          <ActivityIndicator size="large" color="#6F09EA" />
        </View>
      ) : (
        <>
          {/* Primera fila: Búsqueda */}
          <View style={styles_ventas.searchContainer}>
            <View style={styles_ventas.searchInputWrapper}>
              <Svg
                height="20"
                viewBox="0 -960 960 960"
                width="20"
                fill="#9ca3af"
              >
                <Path d="M784-120 532-372q-30 24-69 38t-83 14q-109 0-184.5-75.5T120-580q0-109 75.5-184.5T380-840q109 0 184.5 75.5T640-580q0 44-14 83t-38 69l252 252-56 56ZM380-400q75 0 127.5-52.5T560-580q0-75-52.5-127.5T380-760q-75 0-127.5 52.5T200-580q0 75 52.5 127.5T380-400Z" />
              </Svg>
              <TextInput
                editable={!isFormVisible}
                placeholder="Buscar por nombre, curso..."
                value={searchTerm}
                onChangeText={setSearchTerm}
                style={styles_ventas.searchInput}
              />
            </View>
          </View>

          {/* Segunda fila: Filtro de año y botón */}
          <View style={styles_ventas.filterRow}>
            {/* Selector de Año */}
            <View style={styles_ventas.yearFilterWrapper}>
              <Svg
                height="18"
                viewBox="0 -960 960 960"
                width="18"
                fill="#6b7280"
              >
                <Path d="M200-80q-33 0-56.5-23.5T120-160v-560q0-33 23.5-56.5T200-800h40v-80h80v80h320v-80h80v80h40q33 0 56.5 23.5T840-720v560q0 33-23.5 56.5T760-80H200Zm0-80h560v-400H200v400Zm0-480h560v-80H200v80Zm0 0v-80 80Z" />
              </Svg>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                style={styles_ventas.yearFilterScroll}
              >
                <View style={{ flexDirection: "row", gap: 8 }}>
                  {/* Opción "Todos" */}
                  <TouchableOpacity
                    onPress={() => setSelectedYear(null)}
                    style={[
                      styles_ventas.yearButton,
                      selectedYear === null
                        ? styles_ventas.yearButtonActiveTodos
                        : styles_ventas.yearButtonInactive,
                    ]}
                  >
                    <Text
                      style={[
                        styles_ventas.yearButtonText,
                        selectedYear === null
                          ? styles_ventas.yearButtonTextActive
                          : styles_ventas.yearButtonTextInactive,
                      ]}
                    >
                      Todos
                    </Text>
                  </TouchableOpacity>
                  {availableYears.map((year) => (
                    <TouchableOpacity
                      key={year}
                      onPress={() => setSelectedYear(year)}
                      style={[
                        styles_ventas.yearButton,
                        selectedYear === year
                          ? styles_ventas.yearButtonActive
                          : styles_ventas.yearButtonInactive,
                      ]}
                    >
                      <Text
                        style={[
                          styles_ventas.yearButtonText,
                          selectedYear === year
                            ? styles_ventas.yearButtonTextActive
                            : styles_ventas.yearButtonTextInactive,
                        ]}
                      >
                        {year}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </ScrollView>
            </View>

            {/* Botón Generar Venta */}
            <TouchableOpacity
              onPress={handleGenerateSale}
              style={styles_ventas.generateSaleButton}
            >
              <Svg
                height="18"
                viewBox="0 -960 960 960"
                width="18"
                fill="#ffffff"
              >
                <Path d="M440-440H200v-80h240v-240h80v240h240v80H520v240h-80v-240Z" />
              </Svg>
              <Text style={styles_ventas.generateSaleButtonText}>
                Generar Venta
              </Text>
            </TouchableOpacity>
          </View>

          <TablaVentasPendientes
            data={estudiantesConAdeudo}
            query={searchTerm}
            isRefetching={isRefetching}
            onRefresh={handleRefresh}
            onReprint={handleReprint}
            onRowClick={handleOpenPaymentModal}
            selectedYear={selectedYear}
          />
        </>
      )}

      {/* El formulario ahora se renderiza sobre la lista y se anima */}
      {isFormVisible && (
        <Animated.View
          style={[styles_ventas.formOverlay, formContainerStyle]}
        >
          <RegistroVenta
            navigation={navigation}
            onFormClose={handleCloseForm}
          />
        </Animated.View>
      )}

      {/* Modal de detalles del estudiante - Usando el mismo componente que en Estudiantes */}
      <StudentDetailsModal
        visible={paymentModalVisible}
        onClose={() => setPaymentModalVisible(false)}
        student={{
          nombre_estudiante: selectedDebtForPayment?.nombre_alumno,
          grupo: selectedDebtForPayment?.grupo,
        }}
        details={studentDetails}
        loading={processingPayment}
        onMakePayment={handleOpenCoursePaymentModal}
        onCloseDebt={handleCloseDebt}
      />

      {/* Modal de abono a curso específico */}
      <Modal
        animationType="fade"
        transparent={true}
        visible={coursePaymentModalVisible}
        onRequestClose={() => setCoursePaymentModalVisible(false)}
      >
        <View style={styles_ventas.modalOverlay}>
          <View style={styles_ventas.modalContent}>
            <Text style={styles_ventas.modalTitle}>Registrar Abono</Text>
            <Text style={styles_ventas.modalText}>
              Estudiante: {selectedDebtForPayment?.nombre_alumno}
            </Text>
            <Text style={styles_ventas.modalText}>
              Curso: {selectedCourseForPayment?.nombre}
            </Text>
            <Text style={styles_ventas.modalTextSmall}>
              Pendiente actual: $
              {selectedCourseForPayment?.pendiente.toLocaleString("es-MX")}
            </Text>

            <View style={styles_ventas.sliderWrapper}>
              <Text style={styles_ventas.paymentAmountValue}>
                ${Math.round(paymentAmount).toLocaleString("es-MX")}
              </Text>

              <Slider
                style={{ width: "100%", height: 40 }}
                minimumValue={0}
                maximumValue={selectedCourseForPayment?.pendiente || 0}
                step={10}
                value={Number(paymentAmount)}
                onSlidingComplete={(val) => setPaymentAmount(val)}
                minimumTrackTintColor="#4f46e5"
                maximumTrackTintColor="#cbd5e1"
                thumbTintColor="#4f46e5"
              />

              <View style={styles_ventas.presetAmountsWrapper}>
                {(() => {
                  const total = selectedCourseForPayment?.pendiente || 0;

                  const roundToNice = (num) => {
                    if (num <= 10) return Math.round(num / 5) * 5;
                    if (num <= 50) return Math.round(num / 10) * 10;
                    if (num <= 100) return Math.round(num / 20) * 20;
                    return Math.round(num / 50) * 50;
                  };

                  const amounts = [
                    roundToNice(total * 0.33),
                    roundToNice(total * 0.66),
                    total,
                  ].filter((val, idx, arr) => arr.indexOf(val) === idx);

                  return amounts.map((amount, idx) => {
                    const isTotal = amount === total;
                    return (
                      <TouchableOpacity
                        key={idx}
                        onPress={() => setPaymentAmount(amount)}
                        style={[
                          styles_ventas.presetAmountButton,
                          paymentAmount === amount
                            ? styles_ventas.presetAmountButtonActive
                            : styles_ventas.presetAmountButtonInactive,
                        ]}
                      >
                        <Text
                          style={[
                            styles_ventas.presetAmountButtonText,
                            paymentAmount === amount
                              ? styles_ventas.presetAmountButtonTextActive
                              : styles_ventas.presetAmountButtonTextInactive,
                          ]}
                        >
                          {isTotal
                            ? "Total"
                            : `$${amount.toLocaleString("es-MX")}`}
                        </Text>
                      </TouchableOpacity>
                    );
                  });
                })()}
              </View>
            </View>

            <View style={styles_ventas.modalActions}>
              <TouchableOpacity
                onPress={() => setCoursePaymentModalVisible(false)}
                style={styles_ventas.buttonCancel}
                disabled={processingPayment}
              >
                <Text style={styles_ventas.buttonCancelText}>Cancelar</Text>
              </TouchableOpacity>
              <TouchableOpacity
                onPress={handleProcessPayment}
                style={styles_ventas.buttonConfirm}
                disabled={processingPayment}
              >
                {processingPayment ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text style={styles_ventas.buttonConfirmText}>
                    Confirmar
                  </Text>
                )}
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* Modal de reimpresión de ticket / Ver detalles */}
      <Modal
        animationType="fade"
        transparent={true}
        visible={reprintModalVisible}
        onRequestClose={() => setReprintModalVisible(false)}
      >
        <View style={styles_ventas.modalOverlay}>
          <View style={[styles_ventas.modalContent, { maxWidth: 440 }]}>
            <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <Text style={[styles_ventas.modalTitle, { marginBottom: 0 }]}>Detalles de Transacción</Text>
              <TouchableOpacity onPress={() => setReprintModalVisible(false)}>
                <Svg height="24" viewBox="0 -960 960 960" width="24" fill="#64748b">
                  <Path d="m256-200-56-56 224-224-224-224 56-56 224 224 224-224 56 56-224 224 224 224-56 56-224-224-224 224Z" />
                </Svg>
              </TouchableOpacity>
            </View>

