export default function TicketPreview({ form, curso, totalFinal, totalConIncentivo }) {
  const freq = FREQ[form.frecuencia_sesiones] || null;
  const paid = form.anticipo || 0;
  const full = paid >= totalConIncentivo && totalConIncentivo > 0;
  const due  = Math.max(0, totalFinal);

  return (
    <View style={s.container}>
      <View style={s.header}>
        <Text style={s.title}>MQerk Academy</Text>
        <Text style={s.subtitle}>Comprobante de Venta</Text>
        <Text style={s.date}>{new Date().toLocaleString("es-MX")}</Text>
      </View>

      <View style={s.section}>
        <Text style={s.sectionTitle}>Cliente</Text>
        <Text style={s.text}>{form.nombre_cliente || "No especificado"}</Text>
      </View>

      <View style={s.section}>
        <Text style={s.sectionTitle}>Detalles</Text>
        <View style={s.row}>
          {form.curso_id ? (
            <>
              <Text style={[s.text, { flexShrink: 1, marginRight: 8 }]}>
                {form.curso_quantity}x {curso?.label || "Curso..."}
                {freq && <Text style={s.freq}> ({freq})</Text>}
              </Text>
              <Text style={s.text}>{fmt.format(form.importe)}</Text>
            </>
          ) : (
            <>
              <Text style={s.text}>Curso(s) no seleccionado(s)</Text>
              <Text style={s.text}>{fmt.format(0)}</Text>
            </>
          )}
        </View>
        {freq && form.curso_id && (
          <Text style={s.freqNote}>⟳ Frecuencia: {freq.replace("Pago ", "")}</Text>
        )}
      </View>

      {form.incentivo_premium > 0 && (
        <Row label="Incentivo Premium:"
          value={`- ${fmt.format(form.importe - totalConIncentivo)}`}
          ls={s.amber} vs={s.amber} />
      )}

      <View style={s.sep} />
      <Row
        label={full ? "Pago completo:" : "Anticipo (pago hoy):"}
        value={`- ${fmt.format(paid)}`}
        vs={{ fontWeight: "700" }}
      />
      <View style={s.sep} />

      {!full && form.curso_id && paid > 0 && (
        <Row label="Pendiente por pagar:" value={fmt.format(due)}
          ls={s.red} vs={[s.red, { fontWeight: "700", fontSize: 16 }]} />
      )}

      {!!form.fecha_limite_pago && (
        <Row label="Fecha límite:" value={form.fecha_limite_pago}
          ls={s.date} vs={s.date} />
      )}

      <Row
        label={full || paid === 0 ? "Total a Pagar:" : "Cobro de este recibo:"}
        value={fmt.format(full || paid === 0 ? totalConIncentivo : paid)}
        ls={s.totalLabel} vs={s.totalAmount}
      />
    </View>
  );
}

