import React from "react";
import { View, Text, TouchableOpacity, TextInput, Platform } from "react-native";
import Slider from "@react-native-community/slider";
import Svg, { Path } from "react-native-svg";
import LabeledInput from "../ui/LabeledInput";
import StepButton from "../ui/StepButton";
import CurrencyInput from "../ui/CurrencyInput";
import { ChipButtonGroup } from "../ui/ChipButton";
import styles from "../styles/registroVentaStyles";

const SLIDER_HEIGHT = 40;

export default function PaymentSection({
  form,
  isAnticipoDisabled,
  liveAnticipo,
  handleDirectAnticipoChange,
  maxAnticipoPosible,
  pendienteSinIncentivo,
  totalFinal,
  totalConIncentivo,
  is_incentivo_disabled,
  handleIncentivoPress,
  is_incentivo_active,
  handleIncentivoDeactivation,
  incentivoEnPorcentaje,
  toggleIncentivoTipo,
  liveIncentivo,
  handleDirectIncentivoChange,
  intervalRef,
  stopCounter,
}) {
  return (
    <View>
      <LabeledInput label="Anticipo">
        <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "center" }}>
          <StepButton
            type="decrement"
            disabled={isAnticipoDisabled || (form.anticipo || 0) <= 0}
            onPress={() => handleDirectAnticipoChange(Math.max(0, (liveAnticipo || 0) - 50))}
            onPressIn={() => {
              stopCounter();
              intervalRef.current = setInterval(() => {
                handleDirectAnticipoChange((prevValue) => Math.max(0, (prevValue || 0) - 50));
              }, 150);
            }}
            onPressOut={stopCounter}
          />
          <View style={{ flex: 1 }}>
            <Slider
              style={{ width: "100%", height: SLIDER_HEIGHT }}
              minimumValue={0}
              step={50}
              maximumValue={maxAnticipoPosible}
              value={Number(liveAnticipo) || 0}
              onSlidingComplete={handleDirectAnticipoChange}
              disabled={isAnticipoDisabled}
              minimumTrackTintColor={isAnticipoDisabled ? "#9ca3af" : "#6F09EA"}
              maximumTrackTintColor="#d1d5db"
              thumbTintColor={isAnticipoDisabled ? "#9ca3af" : "#6F09EA"}
            />
          </View>
          <CurrencyInput
            value={form.anticipo}
            onChangeText={(text) => {
              const numericValue = text === "" ? 0 : parseInt(text.replace(/[^0-9]/g, ""), 10) || 0;
              handleDirectAnticipoChange(numericValue);
            }}
            placeholder="0"
            editable={!isAnticipoDisabled}
          />
          <StepButton
            type="increment"
            disabled={isAnticipoDisabled || form.anticipo >= form.importe}
            onPress={() => handleDirectAnticipoChange(Math.min(form.importe, (liveAnticipo || 0) + 50))}
            onPressIn={() => {
              stopCounter();
              intervalRef.current = setInterval(() => {
                handleDirectAnticipoChange((prevValue) => Math.min(form.importe, (prevValue || 0) + 50));
              }, 150);
            }}
            onPressOut={stopCounter}
          />
        </View>

        {form.curso_id && (
          <ChipButtonGroup
            clearLabel="Sin anticipo"
            disabled={isAnticipoDisabled}
            selectedValue={form.anticipo}
            chips={(() => {
              const importe = form.importe || 0;
              if (importe <= 0) return [];

              const standardChips = [50, 100, 200, 500];
              const dynamicChips = new Set();

              standardChips.forEach((v) => {
                if (v < importe) dynamicChips.add(v);
              });

              let startValue = Math.floor((importe - 1) / 500) * 500;
              while (startValue > 500) {
                dynamicChips.add(startValue);
                startValue -= 500;
              }

              const chipObjects = Array.from(dynamicChips)
                .sort((a, b) => a - b)
                .map((v) => ({ label: `$${v}`, value: v }));

              chipObjects.push({
                label: "Total",
                value: importe,
                disabled: !importe || importe <= 0,
              });

              return chipObjects;
            })()}
            onSelect={handleDirectAnticipoChange}
          />
        )}
      </LabeledInput>

      <LabeledInput label={form.incentivo_premium ? "Pendiente (sin incentivo)" : "Total Final"}>
        <View style={{ flexDirection: "row", alignItems: "center" }}>
          <StepButton type="decrement" disabled />
          <Slider
            style={{ flex: 1, height: SLIDER_HEIGHT }}
            minimumValue={0}
            maximumValue={form.importe > 0 ? form.importe : 5000}
            value={pendienteSinIncentivo > 0 ? pendienteSinIncentivo : 0}
            disabled={true}
            minimumTrackTintColor="#4b5563"
            maximumTrackTintColor="#d1d5db"
            thumbTintColor="#9ca3af"
          />
          <CurrencyInput value={pendienteSinIncentivo} editable={false} />
          <StepButton type="increment" disabled />
        </View>
      </LabeledInput>

      <TouchableOpacity
        activeOpacity={1}
        style={[styles.incentivoContainer, is_incentivo_disabled && styles.incentivoDisabledContainer]}
      >
        <TouchableOpacity
          activeOpacity={is_incentivo_disabled ? 1.0 : 0.8}
          onPress={handleIncentivoPress}
          onLongPress={Platform.OS !== "web" && is_incentivo_active ? handleIncentivoDeactivation : null}
          style={[styles.incentivoHeader, is_incentivo_active && styles.incentivoHeaderActive]}
        >
          <Svg height="18" viewBox="0 0 24 24" width="18" fill="#f59e0b">
            <Path d="M5 16L3 5l5.5 5L12 4l3.5 6L21 5l-2 11H5zm14 3H5a2 2 0 00-2 2v1h20v-1a2 2 0 00-2-2z" />
          </Svg>
          <Text style={styles.premiumLabelText}>Incentivo Premium</Text>
        </TouchableOpacity>

        {is_incentivo_active && (
          <TouchableOpacity activeOpacity={1} style={styles.incentivoBody}>
            <View style={styles.segmentedControlContainer}>
              <TouchableOpacity
                style={[styles.segmentedChip, !incentivoEnPorcentaje && styles.segmentedChipActive]}
                onPress={() => {
                  if (incentivoEnPorcentaje) toggleIncentivoTipo();
                }}
                disabled={is_incentivo_disabled}
              >
                <Text style={[styles.segmentedChipText, !incentivoEnPorcentaje && styles.segmentedChipTextActive]}>
                  Monto Fijo ($)
                </Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.segmentedChip, incentivoEnPorcentaje && styles.segmentedChipActive]}
                onPress={() => {
                  if (!incentivoEnPorcentaje) toggleIncentivoTipo();
                }}
                disabled={is_incentivo_disabled}
              >
                <Text style={[styles.segmentedChipText, incentivoEnPorcentaje && styles.segmentedChipTextActive]}>
                  Porcentaje (%)
                </Text>
              </TouchableOpacity>
            </View>
            <View style={{ flexDirection: "row", alignItems: "center" }}>
              <StepButton
                type="decrement"
                disabled={is_incentivo_disabled || (form.incentivo_premium || 0) <= 0}
                onPress={() =>
                  handleDirectIncentivoChange(
                    Math.max(0, (liveIncentivo || 0) - (incentivoEnPorcentaje ? 5 : 50))
                  )
                }
                onPressIn={() => {
                  stopCounter();
                  intervalRef.current = setInterval(() => {
                    handleDirectIncentivoChange((prevValue) => {
                      const step = incentivoEnPorcentaje ? 5 : 50;
                      return Math.max(0, (prevValue || 0) - step);
                    });
                  }, 150);
                }}
                onPressOut={stopCounter}
              />
              <View style={{ flex: 1 }}>
                <Slider
                  style={{ width: "100%", height: SLIDER_HEIGHT }}
                  minimumValue={0}
                  maximumValue={incentivoEnPorcentaje ? 100 : pendienteSinIncentivo}
                  step={incentivoEnPorcentaje ? 5 : 50}
                  value={Number(liveIncentivo) || 0}
                  onSlidingComplete={handleDirectIncentivoChange}
                  minimumTrackTintColor={is_incentivo_disabled ? "#4b5563" : "#6F09EA"}
                  maximumTrackTintColor="#d1d5db"
                  thumbTintColor={is_incentivo_disabled ? "#9ca3af" : "#6F09EA"}
                  disabled={is_incentivo_disabled}
                />
              </View>
              {incentivoEnPorcentaje ? (
                <TextInput
                  style={[styles.input, { width: 100, marginLeft: 10, textAlign: "right" }, is_incentivo_disabled && styles.disabledInput]}
                  value={form.incentivo_premium === null ? "" : `${Math.round(form.incentivo_premium)} %`}
                  onChangeText={(text) => {
                    const numericValue = text === "" ? null : parseInt(text.replace(/[^0-9]/g, ""), 10) || 0;
                    handleDirectIncentivoChange(numericValue);
                  }}
                  keyboardType="number-pad"
                  placeholder="0 %"
                  editable={!is_incentivo_disabled}
                />
              ) : (
                <CurrencyInput
                  value={form.incentivo_premium}
                  onChangeText={(text) => {
                    const numericValue = text === "" ? 0 : parseInt(text.replace(/[^0-9]/g, ""), 10) || 0;
                    handleDirectIncentivoChange(numericValue);
                  }}
                  editable={!is_incentivo_disabled}
                />
              )}
              <StepButton
                type="increment"
                disabled={
                  is_incentivo_disabled ||
                  (incentivoEnPorcentaje ? form.incentivo_premium >= 100 : form.incentivo_premium >= form.importe)
                }
                onPress={() =>
                  handleDirectIncentivoChange((liveIncentivo || 0) + (incentivoEnPorcentaje ? 5 : 50))
                }
                onPressIn={() => {
                  stopCounter();
                  intervalRef.current = setInterval(() => {
                    handleDirectIncentivoChange((prevValue) => {
                      const step = incentivoEnPorcentaje ? 5 : 50;
                      return (prevValue || 0) + step;
                    });
                  }, 150);
                }}
                onPressOut={stopCounter}
              />
            </View>
            <ChipButtonGroup
              clearLabel="Sin incentivo"
              disabled={is_incentivo_disabled}
              selectedValue={form.incentivo_premium}
              chips={
                incentivoEnPorcentaje
                  ? [
                      { label: "10%", value: 10 },
                      { label: "25%", value: 25 },
                      { label: "50%", value: 50 },
                      { label: "75%", value: 75 },
                      { label: "100%", value: 100 },
                    ]
                  : (() => {
                      const maxIncentivo = form.importe || 0;
                      if (maxIncentivo <= 0) return [];

                      const standardChips = [50, 100, 200, 500];
                      const dynamicChips = new Set();

                      standardChips.forEach((v) => {
                        if (v < maxIncentivo) dynamicChips.add(v);
                      });

                      let startValue = Math.floor((maxIncentivo - 1) / 500) * 500;
                      while (startValue > 500) {
                        dynamicChips.add(startValue);
                        startValue -= 500;
                      }

                      const chipObjects = Array.from(dynamicChips)
                        .sort((a, b) => a - b)
                        .map((v) => ({ label: `$${v}`, value: v }));

                      chipObjects.push({
                        label: "Máximo",
                        value: maxIncentivo,
                        disabled: !maxIncentivo || maxIncentivo <= 0,
                      });

                      return chipObjects;
                    })()
              }
              onSelect={handleDirectIncentivoChange}
            />
          </TouchableOpacity>
        )}
      </TouchableOpacity>

      {form.incentivo_premium > 0 ? (
        <LabeledInput label="Pendiente (con incentivo)">
          <View style={{ flexDirection: "row", alignItems: "center" }}>
            <StepButton type="decrement" disabled />
            <Slider
              style={{ flex: 1, height: SLIDER_HEIGHT }}
              minimumValue={0}
              maximumValue={form.importe > 0 ? form.importe : 5000}
              value={totalFinal > 0 ? totalFinal : 0}
              disabled={true}
              minimumTrackTintColor="#4b5563"
              maximumTrackTintColor="#d1d5db"
              thumbTintColor="#9ca3af"
            />
            <CurrencyInput value={totalFinal} editable={false} />
            <StepButton type="increment" disabled />
          </View>
        </LabeledInput>
      ) : null}

      <LabeledInput label="Total a pagar">
        <View style={{ flexDirection: "row", alignItems: "center" }}>
          <StepButton type="decrement" disabled />
          <Slider
            style={{ flex: 1, height: SLIDER_HEIGHT }}
            minimumValue={0}
            maximumValue={form.importe > 0 ? form.importe : 5000}
            value={totalConIncentivo > 0 ? totalConIncentivo : 0}
            disabled={true}
            minimumTrackTintColor="#4b5563"
            maximumTrackTintColor="#d1d5db"
            thumbTintColor="#9ca3af"
          />
          <CurrencyInput value={totalConIncentivo} editable={false} />
          <StepButton type="increment" disabled />
        </View>
      </LabeledInput>
    </View>
  );
}

