export function ChipButton({ label, onPress, disabled, variant, isSelected }) {
  return (
    <TouchableOpacity
      style={[
        styles.chip,
        isSelected && styles.chipSelected,
        variant === "primary" && styles.chipPrimary,
        variant === "clear" && styles.chipClear,
        disabled && styles.chipDisabled,
      ]}
      onPress={onPress}
      disabled={disabled}
    >
      <Text
        style={[
          styles.chipText,
          isSelected && styles.chipTextSelected,
          variant === "primary" && styles.chipTextPrimary,
          variant === "clear" && styles.chipTextClear,
          disabled && styles.chipTextDisabled,
        ]}
      >
        {label}
      </Text>
    </TouchableOpacity>
  );
}

export function ChipButtonGroup({ chips, onSelect, disabled, selectedValue, clearLabel }) {
  return (
    <View style={styles.chipContainer}>
      {selectedValue !== null && selectedValue !== 0 && (
        <ChipButton
          label={clearLabel || "Limpiar"}
          onPress={() => onSelect(0)}
          disabled={disabled}
          variant="clear"
        />
      )}
      {chips.map((chip) => (
        <ChipButton
          key={chip.value}
          label={chip.label}
          onPress={() => {
            if (chip.value === selectedValue) {
              onSelect(0);
            } else {
              onSelect(chip.value);
            }
          }}
          isSelected={chip.value === selectedValue && chip.value !== 0}
          variant={chip.variant}
          disabled={disabled || chip.disabled}
        />
      ))}
    </View>
  );
}

import React from "react";
import { View, Text, TextInput } from "react-native";
import styles from "../styles/registroVentaStyles";

const DisabledCurrencyDisplay = ({ value }) => {
  return (
    <View style={[styles.currencyInputContainer, styles.disabledInput]}>
      <Text style={styles.disabledCurrencyText}>$</Text>
      <Text style={[styles.disabledCurrencyText, { flex: 1, textAlign: "right" }]}>
        {String(Math.floor(value))}
      </Text>
      <Text style={styles.disabledCurrencyText}>.00</Text>
    </View>
  );
};

export default function CurrencyInput({ value, onChangeText, placeholder, editable }) {
  const isEditable = editable !== false;
  const inputRef = React.useRef(null);

  const handleFocus = () => {
    if (isEditable && (value === null || value === "")) {
      onChangeText("");
    }
    setTimeout(() => inputRef.current?.setSelection(99, 99), 0);
  };

  if (!isEditable) {
    return <DisabledCurrencyDisplay value={value} />;
  }

  return (
    <View style={[styles.currencyInputContainer, !isEditable && styles.disabledInput]}>
      <Text style={styles.currencySymbol}>$</Text>
      <TextInput
        style={[
          styles.currencyInput,
          (value === 0 || value === null) && styles.currencyInputPlaceholder,
        ]}
        ref={inputRef}
        value={value === null ? "" : String(Math.floor(value))}
        onChangeText={onChangeText}
        onFocus={handleFocus}
        placeholder={placeholder || "0"}
        keyboardType="number-pad"
        editable={isEditable}
      />
      <Text style={styles.currencyCents}>.00</Text>
    </View>
  );
}

