import React, { useState, useEffect } from "react";
import HeaderAdmin from "../components/HeaderAdmin";
import { supabase } from "../lib/supabase";
import { useAuthContext } from "../hooks/use-auth-context";

function AppHeader({ navigation, route, isDesktop = false }) {
  const { profile, session } = useAuthContext();
  const [avatarUrl, setAvatarUrl] = useState("");

  const userId = session?.user?.id;
  // Marcador estable: solo cambia cuando se sube/borra el avatar (actualiza updated_at).
  // Evita re-descargar la foto al cambiar de sección.
  const avatarVersion = profile?.updated_at || "";

  useEffect(() => {
    let cancelled = false;

    const loadAvatar = async () => {
      if (!userId) {
        setAvatarUrl("");
        return;
      }

      try {
        const { data: files } = await supabase.storage
          .from("PPUser")
          .list(userId, {
            limit: 10,
            offset: 0,
          });

        if (cancelled) return;

        const avatarFile = files?.find((file) =>
          file.name.startsWith("avatar."),
        );

        if (avatarFile) {
          const {
            data: { publicUrl },
          } = supabase.storage
            .from("PPUser")
            .getPublicUrl(`${userId}/${avatarFile.name}`);

          // Cache-buster estable (no Date.now()): el navegador cachea la imagen
          // y solo la vuelve a pedir cuando cambia avatarVersion.
          setAvatarUrl(
            avatarVersion
              ? `${publicUrl}?v=${encodeURIComponent(avatarVersion)}`
              : publicUrl,
          );
        } else {
          setAvatarUrl("");
        }
      } catch (error) {
        if (cancelled) return;
        console.error("Error loading avatar in header:", error);
        setAvatarUrl("");
      }
    };

    loadAvatar();

    return () => {
      cancelled = true;
    };
  }, [userId, avatarVersion]);

  const routeTitles = {
    Inicio: "Panel Principal",
    Estudiantes: "Lista de Estudiantes",
    Asesores: "Asesores",
    Pagos: "Comprobantes de Pago",
    Finanzas: "Reportes de Pagos",
    Calendario: "Calendario",
    Cursos: "Cursos",
    Configuración: "Configuración de Usuario",
  };

  const currentSectionTitle = routeTitles[route?.name] || route?.name || "";
  const handleMenuPress = () => {
    navigation?.toggleDrawer?.();
  };

  return (
    <HeaderAdmin
      logoSource={require("../assets/MQerK_logo.png")}
      onLogoPress={handleMenuPress}
      showMenuButton={!isDesktop}
      onMenuPress={handleMenuPress}
      title="Fenix Retail"
      subtitle={currentSectionTitle}
      adminProfile={{
        name: profile?.full_name || "Usuario",
        email: profile?.email || "",
        role: "Admin",
        lastLogin: new Date().toLocaleString(),
        avatar: avatarUrl || undefined,
      }}
      unreadCount={0}
      notifications={[]}
      onNotificationPress={() => {}}
      onMarkAllAsRead={() => {}}
      onNavigateToSettings={() => navigation?.navigate?.("Configuración")}
      onLogout={() =>
        supabase.auth.signOut().catch((e) => console.error("Sign out error", e))
      }
    />
  );
}

export default AppHeader;

