              ? "#f1f5f9"
              : "transparent",
          borderWidth: isFocused ? 1 : 0,
          borderColor: "#ddd6fe",
          transition: isWeb ? "background-color 0.15s ease" : undefined,
        }}
      >
        {typeof options.drawerIcon === "function"
          ? options.drawerIcon({ color: tintColor, focused: isFocused, size: 24 })
