                    hitSlop={10}
                    style={Platform.OS === "web" ? { cursor: "pointer" } : { zIndex: 2 }}
                  >
                    {showPwd ? (
                      <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                        <Path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                        <Path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                      </Svg>
                    ) : (
                      <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                        <Path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                        <Path d="M3 3l18 18" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                      </Svg>
                    )}
                  </Pressable>
                </View>
              </View>

              <View style={{ flexDirection: "row", justifyContent: "flex-end", marginTop: 4 }}>
                <Pressable onPress={onResetPassword} disabled={submitting} hitSlop={8}>
                  <Text style={{ color: "#6F09EA", fontWeight: "700", fontSize: 13 }}>
                    ¿Olvidaste tu contraseña?
                  </Text>
                </Pressable>
              </View>

              <Pressable
                onPress={onPasswordLogin}
                disabled={submitting}
                style={[{ marginTop: 12, borderRadius: 12, overflow: "hidden" }, Platform.OS === "web" ? { cursor: submitting ? "not-allowed" : "pointer" } : null]}
                hitSlop={10}
              >
                <LinearGradient
                  colors={submitting ? ["#a78bfa", "#a78bfa"] : ["#6F09EA", "#4F09EA"]}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 0 }}
                  style={{
                    borderRadius: 12,
                    paddingVertical: 14,
                    alignItems: "center",
                  }}
                >
                  {submitting ? (
                    <ActivityIndicator color="#fff" />
                  ) : (
                    <Text style={{ color: "#ffffff", fontWeight: "700", fontSize: 15 }}>
                      Iniciar sesión
                    </Text>
                  )}
                </LinearGradient>
              </Pressable>

              {!!errorMsg && (
                <Text style={{ color: "#dc2626", textAlign: "center", fontSize: 13, fontWeight: "600", marginTop: 8 }}>
                  {errorMsg}
                </Text>
              )}

              {needsVerification && (
                <View style={{ marginTop: 8, alignItems: "center" }}>
                  <Pressable onPress={onResend} disabled={resending} hitSlop={8}>
                    <Text style={{ fontWeight: "700", color: resending ? "#94a3b8" : "#6F09EA" }}>
                      {resending ? "Reenviando…" : "Reenviar verificación"}
                    </Text>
                  </Pressable>
                </View>
              )}

              {allowedDomains.length > 0 && (
                <Text style={{ color: "#94a3b8", textAlign: "center", fontSize: 11, marginTop: 12 }}>
                  Solo se permiten correos de: {allowedDomains.join(", ")}
                </Text>
              )}
            </View>

            <View style={{ marginTop: 24, alignItems: "center" }}>
              <Text style={{ color: "#64748b", fontSize: 14 }}>
                ¿No tienes cuenta?{" "}
                <Text
                  style={{ color: "#6F09EA", fontWeight: "800" }}
                  onPress={() => navigation?.navigate("Register")}
                >
                  Regístrate
                </Text>
              </Text>
            </View>
          </View>
        </View>
      </LinearGradient>
    );
  }

  // Lado Móvil y Tablet (Integrated full-screen layout)
  return (
    <View style={{ flex: 1, backgroundColor: "#ffffff" }}>
      <ScrollView contentContainerStyle={{ flexGrow: 1 }} keyboardShouldPersistTaps="handled">
        {/* Banner Superior */}
        <View style={{ height: height * 0.35, minHeight: 270, position: "relative", justifyContent: "center", alignItems: "center", paddingBottom: 36 }}>
          <LinearGradient
            colors={["#6F09EA", "#31108f"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={StyleSheet.absoluteFillObject}
          />
          <Image
            source={require("../assets/MQerK_logo.png")}
            style={{ width: width >= 768 ? 130 : 96, height: width >= 768 ? 130 : 96, marginBottom: 12 }}
            resizeMode="contain"
          />
          <Text style={{ color: "#ffffff", fontSize: 26, fontWeight: "900", marginBottom: 4 }}>
            Fenix Retail
          </Text>
          <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "center", height: 24 }}>
            <Text style={{ color: "#c7d2fe", fontWeight: "700", fontSize: 14 }}>
              {typedText}
            </Text>
            {showCaret && (
              <Text style={{ color: "#c7d2fe", fontWeight: "700", fontSize: 14, opacity: caretVisible ? 1 : 0 }}>
                |
              </Text>
            )}
          </View>
        </View>

        {/* Formulario */}
        <View style={{
          flex: 1,
          paddingHorizontal: width >= 768 ? 80 : 28,
          paddingTop: 40,
          paddingBottom: 36,
          backgroundColor: "#ffffff",
          borderTopLeftRadius: 36,
          borderTopRightRadius: 36,
          marginTop: -36,
          justifyContent: "space-between"
        }}>
          {/* Cabecera del Formulario (Top) */}
          <View>
            <Text style={{ fontSize: width >= 768 ? 32 : 26, fontWeight: "900", color: "#0f172a", marginBottom: 6, textAlign: width >= 768 ? "center" : "left" }}>
