                  placeholderTextColor="#94a3b8"
                  value={email}
                  showSoftInputOnFocus={true}
                />
              </View>
            </View>

            {/* Campo Contraseña */}
            <View>
              <Text style={{ fontSize: 13, fontWeight: "700", color: "#334155", marginBottom: 8 }}>
                Contraseña
              </Text>
              <View style={{ position: "relative" }}>
                <View
                  style={{
                    position: "absolute",
                    left: 14,
                    top: "50%",
                    transform: [{ translateY: -9 }],
                    zIndex: 2,
                  }}
                  pointerEvents="none"
                >
                  <Svg width={18} height={18} viewBox="0 -960 960 960" fill="#94a3b8">
                    <Path d="M240-440v-200q0-100 70-170t170-70q100 0 170 70t70 170v200h40q33 0 56.5 23.5T840-360v280q0 33-23.5 56.5T760-0H200q-33 0-56.5-23.5T120-80v-280q0-33 23.5-56.5T200-440h40Zm80 0h320v-200q0-67-46.5-113.5T480-800q-67 0-113.5 46.5T320-640v200Z" />
                  </Svg>
                </View>
                <TextInput
                  onSubmitEditing={Keyboard.dismiss}
                  placeholder="•••••••••"
                  autoCapitalize="none"
                  secureTextEntry={!showPwd}
                  onChangeText={setPassword}
                  style={[
                    {
                      height: 48,
                      backgroundColor: "#f8fafc",
                      borderColor: "#cbd5e1",
                      borderWidth: 1,
                      borderRadius: 12,
                      paddingLeft: 42,
                      paddingRight: 42,
                      fontSize: 14,
                      color: "#0f172a",
                    },
                    Platform.OS !== "web" && pwdFocused ? { borderColor: "#6F09EA", borderWidth: 1.5 } : null,
                  ]}
                  onFocus={() => Platform.OS !== "web" && setPwdFocused(true)}
                  onBlur={() => Platform.OS !== "web" && setPwdFocused(false)}
                  autoCorrect={false}
                  importantForAutofill="yes"
                  textContentType={Platform.OS === "ios" ? "password" : undefined}
                  autoComplete="current-password"
                  placeholderTextColor="#94a3b8"
                  value={password}
                  showSoftInputOnFocus={true}
                />
                <Pressable
                  onPress={() => setShowPwd((v) => !v)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full items-center justify-center"
                  hitSlop={10}
                  style={Platform.OS === "web" ? { cursor: "pointer" } : { zIndex: 2 }}
                >
                  {showPwd ? (
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                      <Path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                    </Svg>
                  ) : (
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12Z" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                      <Path d="M3 3l18 18" stroke="#64748b" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                    </Svg>
                  )}
                </Pressable>
              </View>
            </View>

            <View style={{ flexDirection: "row", justifyContent: "flex-end", marginTop: 4 }}>
              <Pressable onPress={onResetPassword} disabled={submitting} hitSlop={8}>
                <Text style={{ color: "#6F09EA", fontWeight: "700", fontSize: 13 }}>
                  ¿Olvidaste tu contraseña?
                </Text>
              </Pressable>
            </View>
          </View>

          {/* Pie del Formulario (Bottom) */}
          <View>
            <Pressable
              onPress={onPasswordLogin}
              disabled={submitting}
              style={[{ borderRadius: 12, overflow: "hidden" }, Platform.OS === "web" ? { cursor: submitting ? "not-allowed" : "pointer" } : null]}
              hitSlop={10}
            >
              <LinearGradient
                colors={submitting ? ["#a78bfa", "#a78bfa"] : ["#6F09EA", "#4F09EA"]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={{
                  borderRadius: 12,
                  paddingVertical: 14,
                  alignItems: "center",
                }}
              >
                {submitting ? (
                  <ActivityIndicator color="#fff" />
                ) : (
                  <Text style={{ color: "#ffffff", fontWeight: "700", fontSize: 15 }}>
                    Iniciar sesión
                  </Text>
                )}
              </LinearGradient>
            </Pressable>

            {!!errorMsg && (
              <Text style={{ color: "#dc2626", textAlign: "center", fontSize: 13, fontWeight: "600", marginTop: 8 }}>
                {errorMsg}
              </Text>
            )}

            {needsVerification && (
              <View style={{ marginTop: 8, alignItems: "center" }}>
                <Pressable onPress={onResend} disabled={resending} hitSlop={8}>
                  <Text style={{ fontWeight: "700", color: resending ? "#94a3b8" : "#6F09EA" }}>
                    {resending ? "Reenviando…" : "Reenviar verificación"}
                  </Text>
                </Pressable>
              </View>
            )}

            {allowedDomains.length > 0 && (
              <Text style={{ color: "#94a3b8", textAlign: "center", fontSize: 11, marginTop: 12 }}>
                Solo se permiten correos de: {allowedDomains.join(", ")}
              </Text>
            )}

            <View style={{ marginTop: 24, alignItems: "center" }}>
              <Text style={{ color: "#64748b", fontSize: 14 }}>
                ¿No tienes cuenta?{" "}
                <Text
                  style={{ color: "#6F09EA", fontWeight: "800" }}
                  onPress={() => navigation?.navigate("Register")}
                >
                  Regístrate
                </Text>
              </Text>
            </View>
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({});

import { useState } from "react";
import {
  View,
  Text,
  TextInput,
  Pressable,
  Platform,
  Keyboard,
  StyleSheet,
} from "react-native";
import * as Linking from "expo-linking";
import { supabase } from "../lib/supabase";
import HeaderAdmin from "../components/HeaderAdmin";
import { LinearGradient } from "expo-linear-gradient";

const MIN_PASSWORD_LENGTH = 6;

export default function RegisterScreen({ navigation }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [infoMsg, setInfoMsg] = useState("");
  const [resending, setResending] = useState(false);

  const allowedDomains = (process.env.EXPO_PUBLIC_AUTH_ALLOWED_DOMAINS || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const allowedEmails = (process.env.EXPO_PUBLIC_AUTH_ALLOWED_EMAILS || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const emailAllowed = (value) => {
    if (!value) return false;
    const lower = value.toLowerCase();
    if (allowedEmails.length > 0) return allowedEmails.includes(lower);
    if (allowedDomains.length === 0) return true;
    const domain = value.split("@")[1]?.toLowerCase();
    return !!domain && allowedDomains.includes(domain);
  };

  const onRegister = async () => {
    setErrorMsg("");
    setInfoMsg("");
    if (!email) return setErrorMsg("Ingresa tu correo.");
    if (!password) return setErrorMsg("Ingresa una contraseña.");
    if (password.length < MIN_PASSWORD_LENGTH) {
      return setErrorMsg(
        `La contraseña debe tener al menos ${MIN_PASSWORD_LENGTH} caracteres.`,
      );
    }
    if (!fullName) return setErrorMsg("Ingresa tu nombre.");
    if (!emailAllowed(email))
      return setErrorMsg("Este correo no está autorizado.");

    try {
      setSubmitting(true);
      const redirectTo =
        Platform.OS === "web" && typeof window !== "undefined"
          ? window.location.origin
          : Linking.createURL("/");
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { full_name: fullName },
          emailRedirectTo: redirectTo,
        },
      });
      if (error) {
        const msg = String(error.message || "").toLowerCase();
        if (msg.includes("signups not allowed")) {
          setErrorMsg("Acceso privado: los registros están deshabilitados.");
        } else if (msg.includes("user already registered")) {
          setErrorMsg("Este correo ya está registrado.");
        } else if (msg.includes("password") || msg.includes("weak")) {
          setErrorMsg(
            `La contraseña debe tener al menos ${MIN_PASSWORD_LENGTH} caracteres.`,
          );
        } else {
          setErrorMsg("No se pudo completar el registro.");
        }
      } else {
        if (!data?.user?.email_confirmed_at) {
          setInfoMsg(
            "Te enviamos un correo de verificación. Confirma para poder iniciar sesión.",
          );
        } else {
          setInfoMsg("Registro exitoso. Ya puedes iniciar sesión.");
        }
      }
    } finally {
      setSubmitting(false);
    }
  };

  const onResend = async () => {
    setErrorMsg("");
    setInfoMsg("");
    if (!email) return setErrorMsg("Ingresa tu correo para reenviar.");
    try {
      setResending(true);
      const { error } = await supabase.auth.resend({ type: "signup", email });
      if (error) {
        const msg = String(error.message || "").toLowerCase();
        if (error.status === 429 || msg.includes("retry")) {
          setErrorMsg("Demasiados intentos. Reintenta en unos segundos.");
        } else {
          setErrorMsg("No se pudo reenviar el correo.");
        }
        console.error("Resend verification error:", error);
      } else {
        setInfoMsg(
          "Correo de verificación reenviado. Revisa tu bandeja y spam.",
        );
      }
    } finally {
      setResending(false);
    }
  };

  return (
      <View style={{ flex: 1 }}>
        <HeaderAdmin
          logoSource={require("../assets/MQerK_logo.png")}
          onLogoPress={() => {}}
          title="Fenix Retail"
          showActions={false}
        />
        <View
          style={{
            flexGrow: 1,
            justifyContent: "center",
            alignItems: "center",
            paddingHorizontal: 16,
            paddingVertical: 24,
          }}
        >
          {renderForm()}
        </View>
      </View>
  );

  function renderForm() {
    return (
      <View style={styles.card}>
        <Text style={styles.title}>Regístrate</Text>
        <Text style={styles.subtitle}>Crea tu cuenta para continuar</Text>

        <View style={styles.formGap}>
          <Text style={styles.label}>Nombre completo</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={fullName}
            onChangeText={setFullName}
            placeholder="Tu nombre"
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Text style={styles.label}>Correo</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={email}
            onChangeText={setEmail}
            placeholder="tucorreo@dominio.com"
            autoCapitalize="none"
            keyboardType="email-address"
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Text style={styles.label}>Contraseña</Text>
          <TextInput
            onSubmitEditing={Keyboard.dismiss}
            value={password}
            onChangeText={setPassword}
            placeholder="Tu contraseña"
            autoCapitalize="none"
            secureTextEntry
            style={styles.input}
            placeholderTextColor="#9ca3af"
          />
          <Pressable
            onPress={onRegister}
            disabled={submitting}
            style={[
              styles.button,
              submitting ? styles.buttonDisabled : styles.buttonPrimary,
            ]}
            hitSlop={10}
            android_ripple={{ color: "rgba(255,255,255,0.15)" }}
          >
            <Text style={styles.buttonText}>
              {submitting ? "Creando…" : "Crear cuenta"}
            </Text>
          </Pressable>
          {!!errorMsg && <Text style={styles.errorText}>{errorMsg}</Text>}
          {!!infoMsg && <Text style={styles.infoText}>{infoMsg}</Text>}
          <View style={styles.footer}>
            <Text style={styles.footerText}>¿No te llegó el correo?</Text>
            <Pressable
              onPress={onResend}
              disabled={resending}
              style={styles.resendButton}
              hitSlop={8}
              android_ripple={{ color: "rgba(0,0,0,0.05)" }}
            >
              <Text
                style={[
                  styles.resendText,
                  resending && styles.resendTextDisabled,
                ]}
              >
                {resending ? "Reenviando…" : "Reenviar verificación"}
              </Text>
            </Pressable>
          </View>
        </View>

        <View style={styles.loginLinkContainer}>
          <Text style={styles.loginLinkText}>
            ¿Ya tienes cuenta?{" "}
            <Text
              style={styles.loginLinkAction}
              onPress={() => navigation?.navigate("Login")}
            >
              Inicia sesión
            </Text>
          </Text>
        </View>
      </View>
    );
  }
}

const styles = StyleSheet.create({
  card: {
    width: 520,
    backgroundColor: "#ffffff",
    borderRadius: 16,
    padding: 20,
    ...(Platform.OS === "web"
      ? {
          boxShadow: "0px 10px 15px rgba(0, 0, 0, 0.1)",
        }
      : {
          shadowColor: "#000",
          shadowOffset: { width: 0, height: 10 },
          shadowOpacity: 0.1,
          shadowRadius: 15,
          elevation: 5,
        }),
    borderWidth: 1,
    borderColor: "#e2e8f0",
  },
  title: {
    color: "#0f172a",
    fontSize: 24,
    fontWeight: "800",
    marginBottom: 4,
  },
  subtitle: {
    color: "#475569",
    marginBottom: 24,
  },
  formGap: {
    gap: 12,
  },
  label: {
    color: "#1e293b",
    fontWeight: "bold",
  },
  input: {
    borderWidth: 1,
    borderColor: "#cbd5e1",
    borderRadius: 12,
    paddingHorizontal: 16,
    paddingVertical: 12,
    color: "#0f172a",
  },
  button: {
    marginTop: 4,
    borderRadius: 12,
    paddingVertical: 14,
    alignItems: "center",
  },
  buttonPrimary: {
    backgroundColor: "#6F09EA",
  },
  buttonDisabled: {
    backgroundColor: "#a78bfa",
  },
  buttonText: {
    color: "#ffffff",
    fontWeight: "bold",
  },
  errorText: {
    color: "#dc2626",
    fontSize: 14,
    position: "absolute",
    bottom: 48,
    right: 0,
    left: 0,
    textAlign: "center",
  },
  infoText: {
    color: "#15803d",
    fontSize: 14,
  },
  footer: {
    marginTop: 24,
    alignItems: "center",
  },
  footerText: {
    color: "#475569",
    fontSize: 12,
  },
  resendButton: {
    marginTop: 4,
  },
  resendText: {
    fontWeight: "bold",
    color: "#6F09EA",
  },
  resendTextDisabled: {
    color: "#94a3b8",
  },
  loginLinkContainer: {
    marginTop: 20,
    alignItems: "center",
  },
  loginLinkText: {
    color: "#475569",
  },
  loginLinkAction: {
    color: "#6F09EA",
    fontWeight: "bold",
  },
});

/** @type {import('tailwindcss').Config} */
module.exports = {
  darkMode: "class",
  content: ["./App.jsx", "./components/**/*.{js,jsx,ts,tsx}", "./screens/**/*.{js,jsx,ts,tsx}"],
